/* TRONWELL Conversation Club · Idioms · 1115 idioms */
var IDIOMS = [{"e":"(as) busy as a bee","d":"working hard and doing lots of things","x":"My sister has been [[as busy as a bee]] since she opened her bakery.","es":"no parar ni un minuto; ocupadísimo","o":"Used for people who are busy and active. You can also call someone 'a busy bee'.","th":"animals","lv":"A2","nw":1,"reg":"informal"},{"e":"(as) easy as pie","d":"very simple; not difficult at all","x":"Once you learn the shortcuts, the new app is [[as easy as pie]].","es":"pan comido; facilísimo","o":"Informal. It means the same as 'a piece of cake'.","th":"food","lv":"A2","nw":1,"reg":"informal"},{"e":"a big hit","d":"something that is very popular and successful","x":"The new menu was [[a big hit]] with our customers.","es":"un exitazo; un éxito total","o":"Used for songs, movies, products, food and ideas. Also 'a hit with someone'.","th":"success","lv":"A2","nw":1},{"e":"a dream come true","d":"something wonderful that you wanted for a long time","x":"Living near the beach is [[a dream come true]] for my parents.","es":"un sueño hecho realidad","th":"success","lv":"A2","src":["a2-plans"],"nw":0},{"e":"a know-it-all","d":"a person who acts as if they know everything","x":"Nobody likes working with [[a know-it-all]] who never listens.","es":"un sabelotodo","o":"Negative and informal. Used for people who always correct others.","th":"people","lv":"A2","nw":1,"reg":"informal","uk":"UK also: a know-all"},{"e":"a pain in the neck","d":"a very annoying person or thing","x":"Finding parking downtown on Saturdays is [[a pain in the neck]].","es":"una lata; un dolor de cabeza","o":"Informal but polite enough for work. Use it for tasks, situations or people.","th":"body","lv":"A2","nw":1,"reg":"informal"},{"e":"a piece of cake","d":"very easy","x":"Setting up the new printer was [[a piece of cake]].","es":"pan comido","th":"food","lv":"A2","src":["a2-tech","a2-w-eshop2"],"nw":0},{"e":"a rip-off","d":"something that costs much more than it should","x":"Twelve dollars for a small coffee? That's [[a rip-off]]!","es":"un robo; una estafa","o":"Informal. The verb is 'rip someone off': 'That taxi driver ripped us off.'","th":"money","lv":"A2","nw":1,"reg":"informal"},{"e":"around the clock","d":"all day and all night, without stopping","x":"The factory works [[around the clock]], seven days a week.","es":"día y noche; las 24 horas del día","th":"time","lv":"A2","src":["a2-w-routine"],"nw":0},{"e":"at the last minute","d":"at the latest possible moment","x":"He always buys his plane tickets [[at the last minute]].","es":"a última hora; al último minuto","o":"Before a noun, use hyphens: 'a last-minute change', 'last-minute shopping'.","th":"time","lv":"A2","nw":1},{"e":"be broke","d":"have no money at the moment","x":"We [[were broke]] when we first moved to the city.","es":"estar sin plata; andar pato","o":"Informal. 'Flat broke' means you have absolutely no money.","th":"money","lv":"A2","nw":1,"reg":"informal","uk":"UK also: skint (informal)"},{"e":"be fed up with something","d":"be annoyed and tired of something that keeps happening","x":"I'm [[fed up with]] this traffic every single morning.","es":"estar harto de; estar chato de","o":"Informal. Use 'with' + noun or -ing: 'I'm fed up with waiting.'","th":"feelings","lv":"A2","nw":1,"reg":"informal","uk":"UK informal also: fed up of"},{"e":"be on your way","d":"be traveling to a place right now","x":"Don't start without me! [[I'm on my way]].","es":"voy en camino; voy para allá","o":"Very common in texts: 'On my way!' 'I'll be on my way' can also mean 'I'm leaving now.'","th":"travel","lv":"A2","nw":1},{"e":"be stuck in your head","d":"when a song keeps playing in your mind and you can't stop it","x":"That song from the TV ad [[is stuck in my head]]!","es":"tener algo pegado en la cabeza; se me pegó la canción","th":"body","lv":"A2","src":["a2-music","b2-music"],"nw":0},{"e":"be worried sick","d":"be extremely nervous and afraid about something","x":"Why didn't you call? We [[were worried sick]]!","es":"estar con el alma en un hilo; muerto de preocupación","o":"Common in families: 'Your mom was worried sick about you.'","th":"feelings","lv":"A2","nw":1},{"e":"be your own boss","d":"to work for yourself, with no manager","x":"I'd love to [[be my own boss]] one day.","es":"ser tu propio jefe","th":"money","lv":"A2","src":["a2-careers","b1-smallbiz3"],"nw":0},{"e":"break the bank","d":"to cost too much money","x":"A small team lunch won't [[break the bank]].","es":"costar una fortuna; dejar a alguien en la ruina","th":"money","lv":"A2","src":["b1-shopping3","b2-consumer4","a2-w-budget2"],"nw":0},{"e":"break the ice","d":"to say or do something that helps people relax when they first meet","x":"Our teacher played a game to [[break the ice]] on the first day.","es":"romper el hielo","th":"weather","lv":"A2","src":["a2-relationships","b1-cultureshock3","b2-networking4","a2-w-intro","b1-w-intro","c1-w-execs5"],"nw":0},{"e":"burn bridges","d":"to do something that destroys a relationship, so you can't go back","x":"Don't send an angry email when you leave. Never [[burn bridges]].","es":"cerrarse las puertas; quemar los puentes","th":"people","lv":"A2","src":["a2-w-leaving2"],"nw":0},{"e":"call it a night","d":"to finish an evening and go home","x":"It's 1 a.m. I think it's time to [[call it a night]].","es":"dar por terminada la noche; retirarse","th":"time","lv":"A2","src":["a2-nightout2","b1-w-social3"],"nw":0},{"e":"change your mind","d":"decide something different from before","x":"I wanted pasta, but I [[changed my mind]] and ordered fish.","es":"cambiar de opinión; cambiar de idea","o":"Use 'about' for the topic: 'He changed his mind about the trip.'","th":"risk","lv":"A2","nw":1},{"e":"come a long way","d":"make a lot of progress","x":"Your English [[has come a long way]] since last year!","es":"avanzar mucho; haber progresado mucho","o":"Usually in the present perfect: 'You've come a long way.' The opposite: 'have a long way to go'.","th":"travel","lv":"A2","nw":1},{"e":"cost a fortune","d":"be very expensive","x":"Fixing my car [[cost a fortune]] last month.","es":"costar una fortuna; costar un dineral","o":"A simple, common way to say a price is very high. Also 'spend a fortune' on something.","th":"money","lv":"A2","nw":1},{"e":"cost an arm and a leg","d":"to be very expensive","x":"Concert tickets [[cost an arm and a leg]] these days.","es":"costar un ojo de la cara","th":"body","lv":"A2","src":["a2-money2","b1-negotiation","b2-housing4"],"nw":0},{"e":"cry over spilled milk","d":"be upset about a past mistake you can't change","x":"You missed the train, but it's no use [[crying over spilled milk]].","es":"lo hecho, hecho está; no sirve de nada lamentarse","o":"Usually negative: 'Don't cry over spilled milk' or 'There's no use crying over spilled milk.'","th":"food","lv":"A2","nw":1,"uk":"UK: cry over spilt milk"},{"e":"don't judge a book by its cover","d":"don't decide what something or someone is like only from how it looks","x":"The restaurant looks old, but [[don't judge a book by its cover]]. The food is fantastic.","es":"las apariencias engañan","th":"people","lv":"A2","src":["a2-reading2","b1-stories3"],"nw":0},{"e":"down to earth","d":"practical and friendly; doesn't act more important than others","x":"My new neighbor is really [[down to earth]] and easy to talk to.","es":"sencillo; con los pies en la tierra","o":"A compliment. Before a noun, use hyphens: 'a down-to-earth person'.","th":"weather","lv":"A2","nw":1},{"e":"eat like a horse","d":"eat a lot of food","x":"My teenage son [[eats like a horse]], but he's still very thin.","es":"comer como caballo; comer como lima","o":"The opposite is 'eat like a bird': eat very little.","th":"animals","lv":"A2","nw":1,"reg":"informal"},{"e":"face to face","d":"in person, not by phone or online","x":"I'd rather talk about this [[face to face]] than by email.","es":"cara a cara","o":"Before a noun, use hyphens: a face-to-face meeting, a face-to-face class.","th":"body","lv":"A2","nw":1},{"e":"feel blue","d":"be sad or a little depressed","x":"I always [[feel blue]] on rainy Sunday afternoons.","es":"andar bajoneado; estar triste","o":"Informal. You can also say 'be feeling blue' or 'have the blues'.","th":"colors","lv":"A2","nw":1,"reg":"informal"},{"e":"fingers crossed","d":"I hope it happens; I hope I'm lucky","x":"My job interview is tomorrow. [[Fingers crossed]]!","es":"¡crucemos los dedos!","th":"body","lv":"A2","src":["a2-plans","a2-interview2"],"nw":0},{"e":"from head to toe","d":"over your whole body; completely","x":"She was dressed in black [[from head to toe]] for the concert.","es":"de pies a cabeza","o":"Spanish says it the other way around. You can also say 'from head to foot'.","th":"body","lv":"A2","nw":1},{"e":"game over","d":"it's finished; there's no more chance","x":"If the bank says no to the loan, it's [[game over]] for our plan.","es":"se acabó lo que se daba; se acabó","o":"Informal. These are also the words you see at the end of a video game.","th":"sport","lv":"A2","nw":1,"reg":"informal"},{"e":"get the hang of","d":"to learn how to do something after some practice","x":"The new software is difficult, but I'm [[getting the hang of]] it.","es":"agarrarle la mano a algo","th":"success","lv":"A2","src":["b1-hobbies","b2-tech","a2-w-firstweek2","b1-w-skills","b1-w-webinar3"],"nw":0},{"e":"give someone a hand","d":"to help someone, often with something physical or practical","x":"Can you [[give me a hand]] with these boxes?","es":"echar una mano; darle una mano a alguien","th":"body","lv":"A2","src":["a2-workplace","a2-tasks2"],"nw":0},{"e":"give someone the green light","d":"allow someone to start a plan or project","x":"Our manager finally [[gave us the green light]] to start the project.","es":"dar luz verde","o":"Just like in Spanish. Also 'get the green light': receive permission.","th":"colors","lv":"A2","nw":1},{"e":"go from bad to worse","d":"become even more difficult or unpleasant","x":"After the factory closed, things [[went from bad to worse]] in our town.","es":"ir de mal en peor","o":"Common in stories about bad days, trips or business problems.","th":"trouble","lv":"A2","nw":1},{"e":"go green","d":"to start doing things that are better for the environment","x":"Our company is [[going green]]: no more plastic bottles in meetings.","es":"volverse ecológico; volverse verde","th":"colors","lv":"A2","src":["b1-environment","a2-w-green2"],"nw":0},{"e":"go the extra mile","d":"to do more than people expect","x":"Our drivers always [[go the extra mile]] for our clients.","es":"hacer un esfuerzo extra; ir más allá","th":"success","lv":"A2","src":["b1-customers3","b1-volunteer3","b2-complaints4","a2-w-achieve","b1-w-review3","b2-w-achieve","c1-w-quietquit5"],"nw":0},{"e":"green with envy","d":"very jealous of what someone else has","x":"When I showed my friends my new car, they were [[green with envy]].","es":"muerto de envidia","o":"In English, green is the color of jealousy. Use it with be, look or turn.","th":"colors","lv":"A2","nw":1},{"e":"have a hard time","d":"find something difficult; have problems doing it","x":"I [[had a hard time]] understanding the tour guide's accent.","es":"costarle a uno; pasarlo mal","o":"Use -ing after it: 'have a hard time sleeping'. 'Give someone a hard time' means criticize or tease them.","th":"trouble","lv":"A2","nw":1},{"e":"have a heart of gold","d":"be very kind and generous","x":"My grandfather [[had a heart of gold]]; he helped everyone in town.","es":"tener un corazón de oro","o":"A warm compliment for people who are very kind to others.","th":"people","lv":"A2","nw":1},{"e":"have a lot on my plate","d":"to have a lot of work or problems to deal with","x":"I'd like to help, but I [[have a lot on my plate]] this week.","es":"tener mil cosas encima; estar con mucha pega","th":"food","lv":"A2","src":["b2-health","a2-w-skills","b1-w-boss3"],"nw":0},{"e":"hear (something) through the grapevine","d":"to hear news informally, because people are talking about it","x":"I [[heard it through the grapevine]] that Pablo got the job.","es":"me contó un pajarito; saber de oídas","th":"talk","lv":"A2","src":["a2-w-report","c2-w-report"],"nw":0},{"e":"hit the books","d":"to study hard (informal)","x":"Finals are next week, so it's time to [[hit the books]].","es":"ponerse a estudiar en serio; quemarse las pestañas","th":"success","lv":"A2","src":["a2-courses2","b1-school3","b2-education4"],"nw":0},{"e":"hit the jackpot","d":"have great luck or success, often winning money","x":"We [[hit the jackpot]] with this apartment: great location and low rent.","es":"sacarse la lotería","o":"A jackpot is the biggest prize in a lottery or game. Used for any very lucky result.","th":"success","lv":"A2","nw":1},{"e":"I owe you one.","d":"thank you, I will help you later because you helped me now","x":"Thanks for covering my shift. [[I owe you one]]!","es":"te debo una","th":"people","lv":"A2","src":["a2-workplace"],"nw":0},{"e":"in the middle of nowhere","d":"very far from towns and other people","x":"Their farm is [[in the middle of nowhere]]. There's no phone signal!","es":"en medio de la nada; donde el diablo perdió el poncho","th":"travel","lv":"A2","src":["a2-citycountry2","b1-travel"],"nw":0},{"e":"It's all Greek to me.","d":"I don't understand it at all","x":"My colleague explained the new software, but [[it's all Greek to me]].","es":"me suena a chino; para mí es chino","th":"talk","lv":"A2","src":["a2-w-accents2"],"nw":0},{"e":"it's not my day","d":"everything is going wrong for me today","x":"I missed the bus and then lost my keys. [[It's not my day]]!","es":"no es mi día","o":"Often with 'just': 'It's just not my day.' Change the person: 'It's not his day.'","th":"trouble","lv":"A2","nw":1,"reg":"informal"},{"e":"it's now or never","d":"you must do it now or lose the chance","x":"The sale ends tonight, so [[it's now or never]].","es":"ahora o nunca","o":"Used to push yourself or others to act before a chance disappears.","th":"risk","lv":"A2","nw":1},{"e":"it's the thought that counts","d":"the kindness of a gift is more important than the gift itself","x":"The present was a little strange, but [[it's the thought that counts]].","es":"lo que vale es la intención","th":"people","lv":"A2","src":["a2-ethics","a2-gifts2"],"nw":0},{"e":"it's up to you","d":"you can decide; I'm happy with any choice","x":"“Italian or Mexican food tonight?” “I don't mind. [[It's up to you]].”","es":"tú decides; como quieras","o":"Change the person: 'It's up to her', 'It's up to the manager'.","th":"risk","lv":"A2","nw":1},{"e":"jump for joy","d":"be extremely happy and excited","x":"When they told her about the promotion, she [[jumped for joy]].","es":"saltar de alegría","o":"Often negative: 'I'm not exactly jumping for joy' means you're not happy about it.","th":"feelings","lv":"A2","nw":1},{"e":"keep an eye on","d":"to watch someone or something carefully","x":"Can you [[keep an eye on]] my bag for a minute?","es":"echarle un ojo a; vigilar","th":"body","lv":"A2","src":["a2-safety2","b2-crime4"],"nw":0},{"e":"keep in touch","d":"continue to call or write to someone","x":"Let's [[keep in touch]] after you move to Canada.","es":"mantenerse en contacto","o":"Also 'stay in touch'. A friendly way to say goodbye: 'Keep in touch!'","th":"talk","lv":"A2","nw":1},{"e":"Keep me posted.","d":"please tell me any new information when you have it","x":"I don't know when the truck will arrive. – OK, [[keep me posted]].","es":"mantenme al tanto","th":"talk","lv":"A2","src":["a2-w-email"],"nw":0},{"e":"keep someone company","d":"stay with someone so they are not alone","x":"Can you [[keep me company]] while I wait for the doctor?","es":"hacerle compañía a alguien","o":"Things can do it too: 'My dog keeps me company when I work from home.'","th":"people","lv":"A2","nw":1},{"e":"keep up the good work","d":"continue doing well; don't stop","x":"Your sales numbers look great. [[Keep up the good work]]!","es":"¡sigue así!","o":"Common praise from managers and teachers. Short form: 'Keep it up!'","th":"success","lv":"A2","nw":1},{"e":"keep your chin up","d":"stay positive when things are difficult","x":"I know this week has been hard, but [[keep your chin up]].","es":"¡ánimo!; no te desanimes","o":"Said to encourage someone who is sad or disappointed. Short form: 'Chin up!'","th":"body","lv":"A2","nw":1,"reg":"informal"},{"e":"kill time","d":"do something while you wait, so you don't get bored","x":"We [[killed time]] at the airport by walking around the shops.","es":"matar el tiempo","o":"Used for waiting: at airports, before appointments or between meetings.","th":"time","lv":"A2","nw":1},{"e":"learn the ropes","d":"to learn the basic things you need to know in a new job","x":"It's my first month, so I'm still [[learning the ropes]].","es":"aprender el oficio; aprender cómo funciona todo","th":"success","lv":"A2","src":["b1-careers","b1-presentations","c1-hobbies","a2-w-career","b1-w-webinar3","b2-w-skills","c1-w-career","c2-w-ai6"],"nw":0},{"e":"long time no see","d":"a friendly greeting when you haven't seen someone for a long time","x":"Hey, Pablo! [[Long time no see]]! How have you been?","es":"¡tanto tiempo sin verte!","th":"time","lv":"A2","src":["a2-personal"],"nw":0},{"e":"lose your temper","d":"suddenly become very angry","x":"My boss [[lost his temper]] when the printer broke again.","es":"perder los estribos; perder la paciencia","o":"The opposite is 'keep your temper' or 'stay calm'.","th":"feelings","lv":"A2","nw":1},{"e":"make a fool of yourself","d":"to do something silly in front of other people","x":"I [[made a fool of myself]] at the karaoke party.","es":"hacer el ridículo","th":"feelings","lv":"A2","src":["a2-humor"],"nw":0},{"e":"make small talk","d":"chat about light topics like the weather or weekend","x":"I'm not very good at [[making small talk]] at parties.","es":"conversar de temas livianos","o":"Important in US offices and at networking events: weather, traffic, weekend plans.","th":"talk","lv":"A2","nw":1},{"e":"make someone's day","d":"to make someone very happy","x":"Your lovely message really [[made my day]]!","es":"alegrarle el día a alguien","th":"feelings","lv":"A2","src":["a2-w-reviews2","b1-w-loyalty3"],"nw":0},{"e":"make up your mind","d":"decide, after thinking about it","x":"Have you [[made up your mind]] about the job offer yet?","es":"decidirse","o":"Also 'make your mind up'. Often said when someone is slow to decide.","th":"risk","lv":"A2","nw":1},{"e":"Money doesn't grow on trees.","d":"money is not easy to get, so be careful with it","x":"Turn off the lights when you leave! [[Money doesn't grow on trees]].","es":"la plata no crece en los árboles","th":"money","lv":"A2","src":["a2-money2","b1-money3"],"nw":0},{"e":"my lips are sealed","d":"I promise I won't tell your secret","x":"Your secret is safe with me. [[My lips are sealed]].","es":"soy una tumba","o":"Informal and friendly. People often pretend to close a zipper on their lips.","th":"talk","lv":"A2","nw":1,"reg":"informal"},{"e":"no big deal","d":"not important or serious; not a problem","x":"“Sorry I'm late!” “It's [[no big deal]]. We just started.”","es":"no es para tanto; no es tema","o":"Informal. Also 'It's not a big deal.' A sarcastic 'Big deal!' means you're not impressed.","th":"trouble","lv":"A2","nw":1,"reg":"informal"},{"e":"no pain, no gain","d":"you need hard work to get good results","x":"My legs hurt after yesterday's workout, but [[no pain, no gain]].","es":"el que quiere celeste, que le cueste","o":"Popular with exercise and sports, but also used for study and work.","th":"success","lv":"A2","nw":1},{"e":"on cloud nine","d":"extremely happy","x":"Since she got engaged, Paula has been [[on cloud nine]].","es":"feliz de la vida; no caber en sí de felicidad","o":"Informal. Careful: it means very happy, not 'estar en las nubes' (distracted).","th":"weather","lv":"A2","nw":1,"reg":"informal"},{"e":"on the dot","d":"at exactly that time","x":"The meeting starts at 9:00 [[on the dot]].","es":"en punto","th":"time","lv":"A2","src":["a2-w-details"],"nw":0},{"e":"on the edge of your seat","d":"very excited and nervous because you want to know what happens","x":"The last five minutes had everyone [[on the edge of their seats]].","es":"al borde del asiento; con el alma en un hilo","th":"feelings","lv":"A2","src":["a2-fans2"],"nw":0},{"e":"on the go","d":"very busy and moving around all the time","x":"With two jobs and a new baby, Ana is always [[on the go]].","es":"andar a mil; sin parar","o":"Also used for food and products: 'breakfast on the go', 'snacks for people on the go'.","th":"travel","lv":"A2","nw":1},{"e":"on the house","d":"free, because the restaurant or bar pays for it","x":"We waited a long time, so the coffee was [[on the house]].","es":"invita la casa; cortesía de la casa","th":"money","lv":"A2","src":["a2-complaints2"],"nw":0},{"e":"on the same page","d":"agreeing and understanding a plan in the same way","x":"Before we call the client, let's check we're all [[on the same page]].","es":"estar en la misma sintonía; estar en la misma","th":"talk","lv":"A2","src":["b1-meetings","b1-workplace","c1-crosscultural5","a2-w-opinions"],"nw":0},{"e":"one step at a time","d":"slowly, doing one small thing and then the next","x":"The new system is difficult, so let's learn it [[one step at a time]].","es":"paso a paso; de a poco","th":"time","lv":"A2","src":["a2-w-future"],"nw":0},{"e":"out of the blue","d":"suddenly, when you don't expect it","x":"My old roommate called me [[out of the blue]] last night.","es":"de la nada; de repente","o":"Often with call, text, appear or happen: 'The idea came out of the blue.'","th":"colors","lv":"A2","nw":1},{"e":"peace and quiet","d":"a calm situation with no noise","x":"I work from home on Fridays for some [[peace and quiet]].","es":"paz y tranquilidad","th":"feelings","lv":"A2","src":["a2-w-space"],"nw":0},{"e":"play fair","d":"be honest and follow the rules","x":"If you want your team to trust you, you have to [[play fair]].","es":"jugar limpio","o":"Used in sports, business and relationships. The noun is 'fair play'.","th":"sport","lv":"A2","nw":1},{"e":"practice makes perfect","d":"if you do something many times, you will get very good at it","x":"You play better every week. [[Practice makes perfect]]!","es":"la práctica hace al maestro","th":"success","lv":"A2","src":["a2-hobbies","b1-skills3"],"nw":0},{"e":"put your feet up","d":"sit down and relax, usually at home","x":"After a long week at work, I just want to [[put my feet up]].","es":"echarse a descansar; relajarse","o":"Used for resting at home, often after work or on the weekend.","th":"body","lv":"A2","nw":1,"reg":"informal"},{"e":"rain cats and dogs","d":"rain very heavily","x":"Take an umbrella; it's [[raining cats and dogs]] out there.","es":"llover a cántaros","o":"Playful and a bit old-fashioned, but everyone knows it. 'It's pouring' is more common.","th":"weather","lv":"A2","nw":1,"reg":"informal"},{"e":"rain or shine","d":"in any weather; no matter what happens","x":"The farmers' market is open every Saturday, [[rain or shine]].","es":"llueva o truene","o":"Common on event notices. Also: 'I'll be there, rain or shine' (no matter what).","th":"weather","lv":"A2","nw":1,"uk":"UK often: come rain or shine"},{"e":"sell like hotcakes","d":"to sell very quickly and in large numbers","x":"The new summer jackets are [[selling like hotcakes]].","es":"venderse como pan caliente","th":"food","lv":"A2","src":["b2-ads4","a2-w-selling2"],"nw":0},{"e":"set in your ways","d":"not wanting to change your habits or opinions","x":"My uncle is [[set in his ways]]. He won't try online banking.","es":"aferrado a sus costumbres; chapado a la antigua","th":"people","lv":"A2","src":["b2-generations4","c1-personal","a2-w-generations2"],"nw":0},{"e":"sleep on it","d":"to wait until the next day before you make a decision","x":"It's a big decision. Let's [[sleep on it]].","es":"consultarlo con la almohada","th":"risk","lv":"A2","src":["a2-w-decisions","b1-w-decisions","b1-w-boss3","b2-w-email"],"nw":0},{"e":"slip your mind","d":"to be forgotten, usually by accident","x":"Sorry I didn't call you back. It [[slipped my mind]].","es":"se me olvidó; se me pasó","th":"body","lv":"A2","src":["a2-w-reminders2","b1-w-calls"],"nw":0},{"e":"spill the beans","d":"tell a secret, often by accident","x":"Who [[spilled the beans]] about Laura's surprise party? It was a secret!","es":"irse de lengua; soltar la pepa","o":"Often about surprises, plans or news that should stay secret for now.","th":"food","lv":"A2","nw":1,"reg":"informal","uk":"UK past form also: spilt"},{"e":"spread the word","d":"to tell a lot of people about something","x":"We're opening a new store next month. Please [[spread the word]]!","es":"correr la voz","th":"talk","lv":"A2","src":["a2-w-marketing2"],"nw":0},{"e":"take a rain check","d":"to say no to an invitation now but hope to accept it another time","x":"I can't come to lunch today. Can I [[take a rain check]]?","es":"dejarlo para otra ocasión; ¿lo dejamos para otro día?","th":"weather","lv":"A2","src":["b1-plans","a2-w-invite2"],"nw":0},{"e":"take your time","d":"don't hurry; do it slowly and carefully","x":"There's no rush. [[Take your time]] and read the contract carefully.","es":"tómate tu tiempo; con calma","o":"A kind phrase that tells someone they don't need to hurry.","th":"time","lv":"A2","nw":1},{"e":"talk behind someone's back","d":"say bad things about someone when they're not there","x":"She was upset when she found out her coworkers [[talked behind her back]].","es":"hablar a espaldas de alguien; pelar a alguien","o":"Used about gossip at work, in families and among friends.","th":"talk","lv":"A2","nw":1},{"e":"the best of both worlds","d":"the good things from two different situations at the same time","x":"I work in the city and live by the beach. It's [[the best of both worlds]].","es":"lo mejor de los dos mundos","th":"success","lv":"A2","src":["a2-citycountry2","b1-remote3","b2-hybrid4","b1-w-compare","c1-w-space"],"nw":0},{"e":"the best thing since sliced bread","d":"an excellent new thing (often used as a joke)","x":"My dad thinks his new coffee machine is [[the best thing since sliced bread]].","es":"lo mejor que se ha inventado; lo máximo","th":"food","lv":"A2","src":["a2-inventions2","b1-inventions3"],"nw":0},{"e":"the more, the merrier","d":"it's better and more fun with more people","x":"Can I bring a friend? – Of course! [[The more, the merrier]].","es":"mientras más, mejor","th":"people","lv":"A2","src":["b1-festivals3","a2-w-event2"],"nw":0},{"e":"the trip of a lifetime","d":"a very special trip that you'll probably do only once","x":"Our honeymoon on Easter Island was [[the trip of a lifetime]].","es":"el viaje de mi vida","th":"travel","lv":"A2","src":["a2-travel"],"nw":0},{"e":"those were the days","d":"used to say that a time in the past was very happy","x":"We had no money, but we had so much fun. [[Those were the days]]!","es":"¡qué tiempos aquellos!","th":"time","lv":"A2","src":["a2-childhood2"],"nw":0},{"e":"tie the knot","d":"get married","x":"Sofia and Matt are [[tying the knot]] next June.","es":"casarse; dar el sí","o":"Informal and friendly; common in conversation and in wedding news.","th":"people","lv":"A2","nw":1,"reg":"informal"},{"e":"time flies","d":"it feels like the days pass very fast","x":"Can you believe we've been married for ten years? [[Time flies]]!","es":"el tiempo vuela; cómo pasa el tiempo","o":"Often in the longer form: 'Time flies when you're having fun.'","th":"time","lv":"A2","nw":1},{"e":"travel light","d":"take very little luggage on a trip","x":"I always [[travel light]]: one small backpack for a whole week.","es":"viajar liviano; viajar con poco equipaje","o":"Good advice for low-cost flights, where extra bags cost more.","th":"travel","lv":"A2","nw":1},{"e":"under the weather","d":"a little sick, not very well","x":"I'm feeling a bit [[under the weather]], so I'm going to bed early.","es":"estar indispuesto; andar medio malito","th":"weather","lv":"A2","src":["a2-health"],"nw":0},{"e":"What's the catch?","d":"asking about the hidden problem in an offer that looks very good","x":"A free laptop for every employee? [[What's the catch]]?","es":"¿dónde está la trampa?; ¿cuál es la letra chica?","th":"trouble","lv":"A2","src":["a2-w-decisions"],"nw":0},{"e":"when pigs fly","d":"never; it will not happen","x":"“Do you think Mike will ever be on time?” “Sure, [[when pigs fly]].”","es":"cuando las ranas críen pelo","o":"A sarcastic answer to something you think is impossible.","th":"animals","lv":"A2","nw":1,"reg":"informal","uk":"UK: pigs might fly"},{"e":"win-win","d":"a situation that is good for everyone","x":"Working from home on Fridays is a [[win-win]] for the company and the staff.","es":"ganar-ganar; todos ganan","th":"success","lv":"A2","src":["a2-w-present","b1-w-decisions"],"nw":0},{"e":"work like a dog","d":"work very hard, often for long hours","x":"I [[worked like a dog]] all summer to pay for my trip.","es":"trabajar como burro; sacarse la mugre","o":"Informal. Often used to complain about long hours or a tiring job.","th":"animals","lv":"A2","nw":1,"reg":"informal"},{"e":"worth every penny","d":"so good that the high price was OK","x":"The hotel was expensive, but it was [[worth every penny]].","es":"vale cada peso","o":"Used when you are happy you paid for something, especially something expensive.","th":"money","lv":"A2","nw":1},{"e":"you can say that again","d":"I completely agree with you","x":"“This meeting is taking forever.” “[[You can say that again]].”","es":"¡y que lo digas!","o":"An informal reply to show strong agreement; it doesn't mean 'repeat it'.","th":"talk","lv":"A2","nw":1,"reg":"informal"},{"e":"you can't win them all","d":"nobody can be successful every time","x":"We didn't get the contract, but hey, [[you can't win them all]].","es":"no siempre se puede ganar","o":"Said to accept a small failure calmly. In speech you often hear 'You can't win 'em all.'","th":"sport","lv":"A2","nw":1,"reg":"informal"},{"e":"you get what you pay for","d":"cheap things are usually not very good","x":"My cheap shoes broke in a week. [[You get what you pay for]]!","es":"lo barato sale caro","th":"money","lv":"A2","src":["a2-w-compare","b1-w-compare","b2-w-compare"],"nw":0},{"e":"(as) cool as a cucumber","d":"very calm, especially in a stressful situation","x":"The projector failed, but Rosa stayed [[cool as a cucumber]] and kept presenting.","es":"sin inmutarse, con toda la calma del mundo","o":"A compliment for someone who stays calm under pressure, for example in an interview or an emergency.","th":"food","lv":"B1","nw":1},{"e":"(as) red as a beet","d":"very red in the face, usually because you are embarrassed","x":"When the whole office sang “Happy Birthday,” I turned [[as red as a beet]].","es":"rojo/a como un tomate","o":"American English. Usually with “turn” or “go.” The cause is often embarrassment, but it can also be heat or sun.","th":"colors","lv":"B1","nw":1,"uk":"UK: (as) red as a beetroot"},{"e":"(as) white as a sheet","d":"very pale, usually because of fear, shock or illness","x":"When he saw the repair bill, Tom went [[white as a sheet]].","es":"pálido/a como un papel","o":"Usually with “go,” “turn” or “look”: “She turned as white as a sheet.”","th":"colors","lv":"B1","nw":1},{"e":"(like looking for) a needle in a haystack","d":"something that is almost impossible to find","x":"Finding a cheap apartment downtown is like looking for [[a needle in a haystack]].","es":"como buscar una aguja en un pajar","o":"Same image as in Spanish. Usually after “like looking for” or “like trying to find.”","th":"trouble","lv":"B1","nw":1},{"e":"a blessing in disguise","d":"something that seems bad at first but brings something good","x":"Missing that flight was [[a blessing in disguise]]. I met my wife at the airport!","es":"no hay mal que por bien no venga","th":"success","lv":"B1","src":["b1-changes3","b1-w-past","b1-w-badnews3","b2-w-past","c1-w-past"],"nw":0},{"e":"a bookworm","d":"a person who loves reading and reads a lot","x":"My daughter is [[a real bookworm]]. She reads three books a week.","es":"un ratón de biblioteca","th":"animals","lv":"B1","src":["b1-stories3"],"nw":0},{"e":"a concrete jungle","d":"a city with too many buildings and very little nature","x":"Without its parks, this city would be [[a concrete jungle]].","es":"una selva de cemento","th":"weather","lv":"B1","src":["b1-city3"],"nw":0},{"e":"a couch potato","d":"a person who watches a lot of TV and doesn't exercise","x":"On rainy Sundays, I'm [[a total couch potato]].","es":"un adicto al sillón (y a la tele); un flojo","th":"food","lv":"B1","src":["b1-hobbies","b1-health"],"nw":0},{"e":"a drop in the bucket","d":"a very small amount compared to what is needed","x":"Fifty new chairs are [[a drop in the bucket]]. We need five hundred.","es":"una gota en el mar","th":"money","lv":"B1","src":["b2-environment","c1-resources5","b1-w-stock","b2-w-research4","c1-w-circular5"],"nw":0},{"e":"a fish out of water","d":"a person who feels uncomfortable in a new situation","x":"At my first business dinner in Tokyo, I felt like [[a fish out of water]].","es":"como pez fuera del agua","th":"animals","lv":"B1","src":["b1-cultureshock3","b2-abroad4","b1-w-intern3","c1-w-imposter5","c2-w-trips"],"nw":0},{"e":"a fresh start","d":"a chance to begin again in a new way","x":"Moving to a new city gave me [[a fresh start]].","es":"un nuevo comienzo; empezar de cero","th":"time","lv":"B1","src":["b1-changes3"],"nw":0},{"e":"a game changer","d":"something that completely changes the way people do things","x":"Online banking was [[a game changer]] for my grandparents.","es":"un antes y un después","th":"sport","lv":"B1","src":["b1-tech","b2-gaming4","c1-innovation5"],"nw":0},{"e":"a golden opportunity","d":"a very good chance that may not come again","x":"This internship is [[a golden opportunity]] to work with top designers.","es":"una oportunidad de oro","o":"Common at work, in sports and in the news. Often with “miss”: “We missed a golden opportunity.”","th":"colors","lv":"B1","nw":1},{"e":"a heads-up","d":"a short warning about something that is going to happen","x":"Just [[a heads-up]]: the client is arriving at 3, not 4.","es":"un aviso previo; para que estés al tanto","th":"body","lv":"B1","src":["b1-w-email"],"nw":0},{"e":"a household name","d":"a person or company that almost everybody knows","x":"In ten years, we want to be [[a household name]] in Chile.","es":"un nombre que todo el mundo conoce","th":"success","lv":"B1","src":["b2-fame4","b1-w-brand3"],"nw":0},{"e":"a leap of faith","d":"a brave decision to do something when you can't be sure it will work","x":"Leaving my stable job to open a café was [[a real leap of faith]].","es":"un salto al vacío; un acto de fe","th":"risk","lv":"B1","src":["c2-change6","c2-trust6","b1-w-career","b2-w-fintech4","c2-w-decisions"],"nw":0},{"e":"a lucky break","d":"a piece of good luck that helps you succeed","x":"Her [[lucky break]] came when a famous chef tasted her food at a fair.","es":"un golpe de suerte","o":"Common in stories about careers in music, movies and business. Also: “catch a break.”","th":"success","lv":"B1","nw":1},{"e":"a means to an end","d":"something you do only because it helps you get something else","x":"For many students, a part-time job is just [[a means to an end]].","es":"un medio para lograr un fin","th":"success","lv":"B1","src":["c1-happiness5","b1-w-motivation3"],"nw":0},{"e":"a night owl","d":"a person who likes to stay up late at night","x":"I'm [[a night owl]]. I do my best work after 10 p.m.","es":"un ave nocturna; trasnochador","th":"animals","lv":"B1","src":["b1-everyday"],"nw":0},{"e":"a no-brainer","d":"a decision that is very easy and obvious","x":"Same price, but twice as fast? That's [[a no-brainer]]!","es":"algo obvio; no hay nada que pensar","th":"risk","lv":"B1","src":["b1-w-compare","b2-w-opinions"],"nw":0},{"e":"a page-turner","d":"a book that is so exciting you want to keep reading","x":"Take this thriller on your trip. It's [[a real page-turner]].","es":"un libro atrapante","th":"talk","lv":"B1","src":["b1-stories3"],"nw":0},{"e":"a party animal","d":"a person who loves going to parties and having fun","x":"Diego was [[a party animal]] in college, but now he's in bed by ten.","es":"fiestero/a, carretero/a (Chile)","o":"Informal and usually positive or joking. Often used about someone's younger years.","th":"animals","lv":"B1","nw":1,"reg":"informal"},{"e":"a penny for your thoughts","d":"used to ask someone what they are thinking about","x":"You've been quiet all evening. [[A penny for your thoughts]]?","es":"¿en qué estás pensando?","o":"Friendly and a little old-fashioned, but still used, often when someone looks lost in thought.","th":"talk","lv":"B1","nw":1},{"e":"a people person","d":"someone who enjoys being with and working with other people","x":"I'm [[a people person]], so I love working in sales.","es":"tener don de gente; ser muy sociable","th":"people","lv":"B1","src":["b1-presentations"],"nw":0},{"e":"a pet peeve","d":"a small thing that annoys you a lot","x":"My biggest [[pet peeve]] is people who leave the printer empty.","es":"lo que más me carga; algo que me saca de quicio","th":"animals","lv":"B1","src":["b1-w-space"],"nw":0},{"e":"a picture is worth a thousand words","d":"an image can explain something better than a long description","x":"Show them a photo of the old warehouse. [[A picture is worth a thousand words]].","es":"una imagen vale más que mil palabras","th":"talk","lv":"B1","src":["b1-w-present"],"nw":0},{"e":"a ray of sunshine","d":"a person or thing that makes people feel happier","x":"Our new receptionist is [[a ray of sunshine]] — she always makes everyone smile.","es":"un rayito de sol, un sol","o":"A warm compliment. Also used for good news in a bad time: “the only ray of sunshine this week.”","th":"weather","lv":"B1","nw":1},{"e":"a recipe for disaster","d":"a plan or situation that will probably end badly","x":"Cooking a new dish for your boss on your first try is [[a recipe for disaster]].","es":"la receta perfecta para el desastre","th":"food","lv":"B1","src":["b1-kitchen3","c2-w-process"],"nw":0},{"e":"a small fish in a big pond","d":"an unimportant person in a big organization","x":"At the multinational, I was just [[a small fish in a big pond]].","es":"uno más del montón","th":"animals","lv":"B1","src":["b1-w-bigsmall3"],"nw":0},{"e":"a steal","d":"something that is surprisingly cheap","x":"Only 5,000 pesos for these boots? That's [[a steal]]!","es":"una ganga; está regalado","th":"money","lv":"B1","src":["b1-shopping3","b2-consumer4"],"nw":0},{"e":"a steep learning curve","d":"a situation where you have to learn a lot very quickly","x":"The new software has [[a steep learning curve]], so the first weeks are slow.","es":"una curva de aprendizaje pronunciada","th":"trouble","lv":"B1","src":["b1-skills3"],"nw":0},{"e":"a sticky situation","d":"a difficult or embarrassing situation that is hard to deal with","x":"Two of my friends want the same job at my company. It's [[a sticky situation]].","es":"una situación delicada","o":"Informal. Often used when you must choose between people or say something uncomfortable.","th":"trouble","lv":"B1","nw":1,"reg":"informal"},{"e":"a team player","d":"a person who works well with other people","x":"We're looking for [[a team player]] with good communication skills.","es":"alguien que sabe trabajar en equipo","th":"sport","lv":"B1","src":["b1-careers"],"nw":0},{"e":"a thing of the past","d":"something that people don't use or do anymore","x":"Paper tickets are [[a thing of the past]] at most airlines.","es":"cosa del pasado","th":"time","lv":"B1","src":["b2-cashless4","b1-w-cashless3"],"nw":0},{"e":"a trip down memory lane","d":"a time when you remember happy things from the past","x":"Looking at old photos with my mom was [[a real trip down memory lane]].","es":"un viaje al pasado; recordar viejos tiempos","th":"time","lv":"B1","src":["b1-personal","c2-memory6"],"nw":0},{"e":"a two-way street","d":"a situation where both sides must give something","x":"Trust is [[a two-way street]] between a company and its clients.","es":"es de ida y vuelta; tiene que ser mutuo","th":"people","lv":"B1","src":["c1-globalization5","b1-w-loyalty3","c1-w-quietquit5"],"nw":0},{"e":"a white lie","d":"a small lie you tell to be kind","x":"I told my aunt I loved her soup. It was [[a white lie]]!","es":"una mentira piadosa","th":"colors","lv":"B1","src":["b1-ethics"],"nw":0},{"e":"ahead of its time","d":"too modern or advanced for the period when it appeared","x":"The first video phones appeared in the 1960s. The idea was [[ahead of its time]].","es":"adelantado a su época","th":"time","lv":"B1","src":["b1-inventions3"],"nw":0},{"e":"an early bird","d":"a person who likes to get up very early","x":"My mom is [[an early bird]]; she's up at 5:30 every day.","es":"madrugador; ser de levantarse temprano","th":"animals","lv":"B1","src":["b1-everyday"],"nw":0},{"e":"at a snail's pace","d":"very, very slowly","x":"The line of cars moved [[at a snail's pace]] all the way to the coast.","es":"a paso de tortuga","th":"animals","lv":"B1","src":["b1-traffic3"],"nw":0},{"e":"at the crack of dawn","d":"very early in the morning","x":"We left [[at the crack of dawn]] to avoid the traffic to the coast.","es":"de madrugada, al alba","o":"Often used to complain about getting up early: “I had to get up at the crack of dawn.”","th":"time","lv":"B1","nw":1},{"e":"back to square one","d":"back at the start, because an attempt has failed","x":"The new password didn't work either, so we're [[back to square one]].","es":"volver a foja cero; volver al punto de partida","th":"success","lv":"B1","src":["b1-w-problems"],"nw":0},{"e":"back to the drawing board","d":"starting again because the first plan failed","x":"The client hated our design, so it's [[back to the drawing board]].","es":"volver a empezar desde cero; rehacer el plan","th":"success","lv":"B1","src":["b2-startups4","c1-architecture5","b1-w-achieve"],"nw":0},{"e":"be a breeze","d":"be very easy to do","x":"With the new app, booking a doctor's appointment [[is a breeze]].","es":"ser pan comido, ser facilísimo","o":"Informal, mainly American. Also “breeze through something”: “She breezed through the exam.”","th":"weather","lv":"B1","nw":1,"reg":"informal"},{"e":"be a good sport","d":"to accept losing or a joke in a nice, friendly way","x":"We lost 5–0, but our captain [[was a good sport]] and congratulated the other team.","es":"saber perder; tomarse las cosas con buena onda","th":"sport","lv":"B1","src":["b1-fitness3"],"nw":0},{"e":"be dying to do something","d":"want to do something very much","x":"I'm [[dying to]] see your new apartment. Can I visit this weekend?","es":"morirse de ganas de (hacer algo)","o":"Informal and enthusiastic. Also “be dying for something”: “I'm dying for a coffee.”","th":"feelings","lv":"B1","nw":1,"reg":"informal"},{"e":"be glued to","d":"to look at something (a phone, a screen) all the time","x":"My brother [[is glued to]] his phone, even during dinner.","es":"estar pegado a (el celular, la tele)","th":"talk","lv":"B1","src":["b1-tech"],"nw":0},{"e":"be out of shape","d":"to be physically unfit","x":"I ran for the bus and couldn't breathe. I'm so [[out of shape]]!","es":"estar fuera de forma","th":"body","lv":"B1","src":["b1-health"],"nw":0},{"e":"be swamped","d":"to have much more work than you can easily do","x":"Sorry, I can't talk right now. I'm [[swamped]].","es":"estar tapado de pega; estar hasta el cuello","th":"trouble","lv":"B1","src":["b1-workplace"],"nw":0},{"e":"be thrown in at the deep end","d":"to be given a difficult job with no preparation","x":"Interns here [[are thrown in at the deep end]]. They meet clients in their first week.","es":"tirar a alguien a los leones; aprender sobre la marcha","th":"trouble","lv":"B1","src":["b1-w-intern3"],"nw":0},{"e":"beat around the bush","d":"to avoid saying something directly","x":"Don't [[beat around the bush]]. Did we get the contract or not?","es":"andarse con rodeos; darle vueltas al asunto","th":"talk","lv":"B1","src":["c1-crosscultural5","b1-w-badnews3","b2-w-email"],"nw":0},{"e":"behind the times","d":"old-fashioned; not using modern ideas or technology","x":"My dad still pays all his bills by check — he's a bit [[behind the times]].","es":"anticuado/a, quedado/a en el tiempo","o":"Used for people, companies and places. Adding “a bit” makes it sound softer.","th":"time","lv":"B1","nw":1},{"e":"believe it or not","d":"used to introduce a surprising fact","x":"[[Believe it or not]], bananas are berries.","es":"aunque no lo creas","th":"talk","lv":"B1","src":["b1-curious"],"nw":0},{"e":"bend over backwards","d":"to try very hard to help or please someone","x":"The staff [[bent over backwards]] to find me a room.","es":"hacer lo imposible; desvivirse por ayudar","th":"body","lv":"B1","src":["b1-customers3","b2-w-pushback4"],"nw":0},{"e":"bend the rules","d":"to break a rule a little because it seems OK in that situation","x":"Can we [[bend the rules]] and let him leave early today?","es":"hacer una excepción; saltarse un poco las reglas","th":"risk","lv":"B1","src":["b1-w-rules","b2-w-rules"],"nw":0},{"e":"better late than never","d":"it's better to do or get something late than not at all","x":"The report arrived three days late, but [[better late than never]].","es":"más vale tarde que nunca","th":"time","lv":"B1","src":["b1-w-stock"],"nw":0},{"e":"better safe than sorry","d":"it's better to be careful now than to have problems later","x":"I'll call the client to confirm the date. [[Better safe than sorry]].","es":"más vale prevenir que lamentar","th":"risk","lv":"B1","src":["b1-w-details"],"nw":0},{"e":"bite off more than you can chew","d":"to try to do more than you are able to do","x":"I offered to cook for 30 people. I [[bit off more than I could chew]]!","es":"quien mucho abarca, poco aprieta","th":"food","lv":"B1","src":["b1-kitchen3","b2-time4","b1-w-routine","b1-w-freelance3","c1-w-now","c1-w-mental5","c1-w-ma5"],"nw":0},{"e":"bored to death","d":"extremely bored","x":"The training session was three hours of slides. I was [[bored to death]].","es":"muerto/a de aburrimiento, aburrido/a como ostra","o":"An exaggeration, not meant literally. Also “bored to tears.”","th":"feelings","lv":"B1","nw":1,"reg":"informal"},{"e":"bumper to bumper","d":"(of traffic) so heavy that the cars are almost touching","x":"On Friday evenings, the traffic out of the city is [[bumper to bumper]].","es":"un taco tremendo; auto pegado a auto","th":"travel","lv":"B1","src":["b1-traffic3"],"nw":0},{"e":"burn the candle at both ends","d":"to work very hard, going to bed late and getting up early","x":"During the audit, the whole team was [[burning the candle at both ends]].","es":"trabajar de sol a sol; no parar ni para dormir","th":"time","lv":"B1","src":["b1-w-wellness3","b2-w-routine"],"nw":0},{"e":"by the book","d":"exactly as the rules or instructions say","x":"Our accountant does everything [[by the book]].","es":"al pie de la letra; según las reglas","th":"risk","lv":"B1","src":["b1-w-rules","b1-w-process"],"nw":0},{"e":"cabin fever","d":"a bored, restless feeling from staying inside for too long","x":"After a rainy week at home, I had terrible [[cabin fever]].","es":"estar chato del encierro; sentirse enclaustrado","th":"feelings","lv":"B1","src":["b1-remote3"],"nw":0},{"e":"call the shots","d":"to be the person who makes the important decisions","x":"The head office in Madrid [[calls the shots]] on prices.","es":"cortar el queque; llevar la batuta","th":"risk","lv":"B1","src":["b2-leadership4","b1-w-role"],"nw":0},{"e":"carrot and stick","d":"using rewards and punishments to make people work harder","x":"Our old boss used a [[carrot-and-stick]] approach: bonuses for good results and angry emails for bad ones.","es":"la zanahoria y el garrote","th":"food","lv":"B1","src":["b1-w-motivation3"],"nw":0},{"e":"cash is king","d":"cash is the most useful or the safest way to pay","x":"At the farmers' market, [[cash is king]]: many stalls don't take cards.","es":"el efectivo manda; nada como la plata en efectivo","th":"money","lv":"B1","src":["b2-cashless4","b1-w-cashless3"],"nw":0},{"e":"chicken out","d":"decide not to do something because you are afraid","x":"I was going to ask for a raise, but I [[chickened out]] at the last minute.","es":"acobardarse, arrugar (informal)","o":"Informal. Often followed by “of”: “He chickened out of the bungee jump.”","th":"animals","lv":"B1","nw":1,"reg":"informal"},{"e":"climb the career ladder","d":"to get better and better jobs, one step at a time","x":"He [[climbed the career ladder]] fast, from intern to director.","es":"escalar posiciones; hacer carrera","th":"success","lv":"B1","src":["b2-careers","b1-w-future"],"nw":0},{"e":"come out on top","d":"win or be the most successful in the end","x":"After a long legal battle, the small company [[came out on top]].","es":"salir ganando, salir victorioso/a","o":"Used for competitions, arguments, elections and business deals.","th":"success","lv":"B1","nw":1},{"e":"count your blessings","d":"to think about the good things you have","x":"You have a job you like and great colleagues. [[Count your blessings]]!","es":"agradecer lo que uno tiene","th":"feelings","lv":"B1","src":["b1-w-satisfaction3"],"nw":0},{"e":"crunch time","d":"the busy, stressful period just before a deadline","x":"It's [[crunch time]] at the office, so I'm working late all week.","es":"la recta final; la hora de la verdad","th":"time","lv":"B1","src":["b1-deadlines3"],"nw":0},{"e":"cut corners","d":"to do something quickly or cheaply by skipping important steps","x":"Never [[cut corners]] on safety, even when you're in a hurry.","es":"hacer las cosas a la rápida; saltarse pasos","th":"risk","lv":"B1","src":["c1-bizethics5","c2-workplace","b1-w-process","b2-w-process","c2-w-process","c2-w-trustasset6"],"nw":0},{"e":"do the right thing","d":"to act in an honest or fair way, even when it's difficult","x":"It wasn't easy, but she [[did the right thing]] and told her boss.","es":"hacer lo correcto","th":"risk","lv":"B1","src":["b1-ethics"],"nw":0},{"e":"do the trick","d":"to solve a problem or give the result you need","x":"I restarted the router, and that [[did the trick]].","es":"dar resultado; funcionar","th":"success","lv":"B1","src":["b1-w-problems"],"nw":0},{"e":"don't count your chickens (before they hatch)","d":"don't make plans based on a good result that hasn't happened yet","x":"The client seems interested, but [[don't count your chickens]] until the contract is signed.","es":"no cantes victoria antes de tiempo","o":"A common friendly warning. People often say only the first part: “Don't count your chickens.”","th":"animals","lv":"B1","nw":1},{"e":"dot the i's and cross the t's","d":"to pay attention to every small detail","x":"Before we sign the contract, let's [[dot the i's and cross the t's]].","es":"revisar todo con lupa; cuidar hasta el último detalle","th":"talk","lv":"B1","src":["b1-w-details"],"nw":0},{"e":"down to the wire","d":"until the very last moment before the end or the deadline","x":"The project went [[down to the wire]], but we delivered it.","es":"hasta el último minuto","th":"time","lv":"B1","src":["b1-deadlines3"],"nw":0},{"e":"dressed to kill","d":"wearing very elegant clothes to impress people","x":"Everyone at the party was [[dressed to kill]].","es":"de punta en blanco","th":"people","lv":"B1","src":["b1-fashion3"],"nw":0},{"e":"drop someone a line","d":"write someone a short message or email","x":"[[Drop me a line]] when you get to Boston so I know you arrived.","es":"escribirle unas líneas a alguien, mandarle un mensaje","o":"Informal and friendly. Often at the end of emails: “Drop me a line sometime.”","th":"talk","lv":"B1","nw":1,"reg":"informal"},{"e":"drop the ball","d":"to make a mistake by not doing something you were responsible for","x":"Sorry, I [[dropped the ball]]. I forgot to send the invoice.","es":"descuidarse; mandarse un condoro","th":"sport","lv":"B1","src":["c2-globalhealth6","b1-w-calls","b2-w-past","c1-w-role"],"nw":0},{"e":"every little bit helps","d":"small actions are useful, too","x":"I know one cloth bag won't save the planet, but [[every little bit helps]].","es":"todo suma; cada granito de arena cuenta","th":"success","lv":"B1","src":["b1-environment"],"nw":0},{"e":"fall flat","d":"(a joke or an idea) to fail to get the reaction you wanted","x":"My joke [[fell flat]]. Nobody in the room laughed.","es":"no pegar; caer en el vacío","th":"success","lv":"B1","src":["c2-humor","b1-w-humor3","c2-w-irony6"],"nw":0},{"e":"fall through the cracks","d":"to be forgotten or not noticed in a big system","x":"In a big company, good ideas can easily [[fall through the cracks]].","es":"quedar en el olvido; pasar inadvertido","th":"trouble","lv":"B1","src":["c2-futureorgs6","b1-w-bigsmall3","b2-w-role","c1-w-role"],"nw":0},{"e":"feast or famine","d":"a situation where you have either too much or too little of something","x":"Freelance work is [[feast or famine]]: I'm either exhausted or bored.","es":"o mucho o nada; o sobra o falta","th":"food","lv":"B1","src":["b1-w-freelance3"],"nw":0},{"e":"fight like cats and dogs","d":"argue very often and angrily","x":"My brother and I [[fought like cats and dogs]] as teenagers, but now we're close.","es":"llevarse como perros y gatos","o":"Describes arguing, not physical fighting. Common for brothers and sisters, couples and roommates.","th":"animals","lv":"B1","nw":1},{"e":"first come, first served","d":"the people who arrive first get something first","x":"Parking spaces are [[first come, first served]].","es":"por orden de llegada","th":"time","lv":"B1","src":["b1-w-space"],"nw":0},{"e":"fit like a glove","d":"to fit perfectly","x":"I bought these boots online, and they [[fit like a glove]].","es":"quedar como anillo al dedo; quedar pintado","th":"body","lv":"B1","src":["b1-fashion3"],"nw":0},{"e":"for good","d":"forever; permanently","x":"After ten years in Canada, Sofía has moved back to Chile [[for good]].","es":"para siempre, definitivamente","o":"Short but very common. Used for moving, quitting jobs and stopping habits: “I've quit smoking for good.”","th":"time","lv":"B1","nw":1},{"e":"from the bottom of my heart","d":"very sincerely and with real feeling","x":"Thank you [[from the bottom of my heart]] for helping us when we moved.","es":"de todo corazón","o":"Makes thanks, apologies and good wishes stronger. Common in speeches, cards and emotional messages.","th":"body","lv":"B1","nw":1},{"e":"get a head start","d":"start before others, which gives you an advantage","x":"Let's [[get a head start]] on the report tonight so tomorrow is easier.","es":"adelantarse, tomar la delantera","o":"Often followed by “on”: “get a head start on the competition.” Common at work and in studies.","th":"sport","lv":"B1","nw":1},{"e":"get a pink slip","d":"be told officially that you have lost your job","x":"After twenty years at the factory, he [[got a pink slip]] just before the holidays.","es":"recibir la carta de despido","o":"American English and informal. Also “give someone a pink slip.” Used for being fired or laid off.","th":"colors","lv":"B1","nw":1,"reg":"informal"},{"e":"get away from it all","d":"go somewhere quiet to escape your normal stress and routine","x":"We rented a cabin in the mountains to [[get away from it all]] for a week.","es":"desconectarse de todo, escaparse de la rutina","o":"Common in travel ads and vacation talk. “A getaway” is a short vacation.","th":"travel","lv":"B1","nw":1},{"e":"get back on your feet","d":"become healthy, strong or successful again after a difficult time","x":"After losing his business, it took Juan two years to [[get back on his feet]].","es":"recuperarse, volver a levantarse","o":"Used after an illness, a job loss, a divorce or money problems. Also: “be back on your feet.”","th":"body","lv":"B1","nw":1},{"e":"get carried away","d":"become so excited that you lose control of what you do","x":"I [[got carried away]] at the sale and spent way more than I planned.","es":"entusiasmarse de más, dejarse llevar","o":"Often used to apologize: “Sorry, I got a little carried away.”","th":"feelings","lv":"B1","nw":1},{"e":"get down to business","d":"to start talking about the important work topic","x":"After coffee and a little small talk, we [[got down to business]].","es":"entrar en materia; ponerse manos a la obra","th":"money","lv":"B1","src":["b2-meetings","b1-w-etiquette3"],"nw":0},{"e":"get off on the wrong foot","d":"to start a relationship badly","x":"I arrived late to our first meeting, so we [[got off on the wrong foot]].","es":"empezar con el pie izquierdo","th":"body","lv":"B1","src":["b1-w-etiquette3","b2-w-body4"],"nw":0},{"e":"get off the ground","d":"to start successfully (a project or a business)","x":"It took us almost a year to [[get the business off the ground]].","es":"despegar; echar a andar","th":"success","lv":"B1","src":["b1-smallbiz3"],"nw":0},{"e":"get on someone's nerves","d":"to annoy someone, often again and again","x":"My little brother [[gets on my nerves]] when he uses my things.","es":"sacar de quicio; poner los nervios de punta","th":"feelings","lv":"B1","src":["b1-relationships","b1-w-space"],"nw":0},{"e":"get the ball rolling","d":"to start an activity or a process","x":"Let's [[get the ball rolling]] with a quick look at last week's numbers.","es":"dar el puntapié inicial; echar a andar las cosas","th":"sport","lv":"B1","src":["b2-presentations","b1-w-now"],"nw":0},{"e":"get to the bottom of","d":"to discover the real reason for a problem","x":"Don't worry, we're going to [[get to the bottom of]] this.","es":"llegar al fondo del asunto","th":"trouble","lv":"B1","src":["b1-w-problems","b2-w-problems"],"nw":0},{"e":"get to the point","d":"to talk or write about the most important thing directly","x":"Busy people want emails that [[get to the point]].","es":"ir al grano","th":"talk","lv":"B1","src":["b1-w-email"],"nw":0},{"e":"get your foot in the door","d":"to get a first chance to work in a company or industry","x":"An internship is a great way to [[get your foot in the door]].","es":"poner un pie dentro; abrirse camino","th":"body","lv":"B1","src":["b1-careers","b2-networking4","c1-negotiation","b1-w-sales3"],"nw":0},{"e":"get your money's worth","d":"get good value for the money you paid","x":"We stayed at the buffet for three hours — we really [[got our money's worth]].","es":"sacarle el jugo a lo que pagaste","o":"Often humorous, when people use something as much as possible because they paid for it.","th":"money","lv":"B1","nw":1},{"e":"get your wires crossed","d":"to misunderstand each other without noticing","x":"We [[got our wires crossed]], and we both went to different meeting rooms.","es":"entenderse mal; tener un malentendido","th":"talk","lv":"B1","src":["b1-w-details","b2-w-details"],"nw":0},{"e":"give someone a buzz","d":"to phone someone (informal)","x":"[[Give me a buzz]] when you get to the airport.","es":"dar un telefonazo; hacer un llamado","th":"talk","lv":"B1","src":["b1-w-calls"],"nw":0},{"e":"give something two thumbs up","d":"to say that something is really good","x":"The critics [[gave the new comedy two thumbs up]].","es":"dar el visto bueno; ponerle un siete","th":"body","lv":"B1","src":["b1-series3"],"nw":0},{"e":"glued to your phone","d":"looking at your phone all the time","x":"My teenage son is [[glued to his phone]] from morning to night.","es":"pegado al celular","th":"talk","lv":"B1","src":["b1-media"],"nw":0},{"e":"go bananas","d":"become very excited or very angry; go crazy","x":"The fans [[went bananas]] when the band came back on stage.","es":"volverse loco/a","o":"Very informal and a bit humorous. It can describe great excitement or great anger.","th":"food","lv":"B1","nw":1,"reg":"informal"},{"e":"go downhill","d":"gradually become worse","x":"The service at that hotel has really [[gone downhill]] since the new owners took over.","es":"ir cuesta abajo, ir de mal en peor","o":"Used for quality, health, relationships and businesses: “Things went downhill after that.”","th":"success","lv":"B1","nw":1},{"e":"go over someone's head","d":"to talk to someone's boss without speaking to that person first","x":"I was upset when my colleague [[went over my head]] and called my director.","es":"pasar por encima de alguien","th":"body","lv":"B1","src":["b1-w-role","c1-w-report"],"nw":0},{"e":"go through the motions","d":"to do something without any interest or energy","x":"After ten years in the same position, he was just [[going through the motions]].","es":"hacer las cosas por cumplir; funcionar en piloto automático","th":"feelings","lv":"B1","src":["c2-rituals6","b1-w-motivation3","b2-w-engage4","c1-w-now","c2-w-meaning6"],"nw":0},{"e":"go through the roof","d":"to rise to a very high level very quickly","x":"Demand for heaters [[went through the roof]] in July.","es":"dispararse; irse por las nubes","th":"money","lv":"B1","src":["b1-w-trends","b2-w-trends"],"nw":0},{"e":"go viral","d":"to spread very quickly on the internet","x":"Her video of a singing parrot [[went viral]] overnight.","es":"hacerse viral; viralizarse","th":"talk","lv":"B1","src":["b1-media","b2-w-socialmkt4"],"nw":0},{"e":"go with the flow","d":"relax and accept what happens instead of trying to control it","x":"We didn't plan much for the trip; we just [[went with the flow]].","es":"fluir, dejarse llevar","o":"Informal and positive. The image is a river: you move with the water, not against it.","th":"weather","lv":"B1","nw":1,"reg":"informal"},{"e":"grab a bite","d":"to have a quick meal or snack (informal)","x":"Do you want to [[grab a bite]] after class?","es":"comer algo al paso; picar algo","th":"food","lv":"B1","src":["b1-food"],"nw":0},{"e":"have a blast","d":"to have a really good time","x":"We [[had a blast]] at the beach last weekend.","es":"pasarlo chancho; pasarlo increíble","th":"feelings","lv":"B1","src":["b1-plans","b1-hobbies"],"nw":0},{"e":"have a sweet tooth","d":"to love sweet food","x":"My dad [[has a real sweet tooth]]. He eats manjar straight from the jar!","es":"ser bueno para lo dulce; ser goloso","th":"food","lv":"B1","src":["b1-food"],"nw":0},{"e":"have a way with words","d":"to be very good at expressing ideas when you speak or write","x":"Ask Valeria to write the email. She [[has a way with words]].","es":"tener facilidad de palabra; saber expresarse","th":"talk","lv":"B1","src":["b1-w-skills"],"nw":0},{"e":"have mixed feelings","d":"feel both happy and unhappy about something at the same time","x":"I [[have mixed feelings]] about moving to a new city: it's exciting but scary.","es":"tener sentimientos encontrados","o":"A polite, neutral way to say you're not sure. Followed by “about” a person, plan or change.","th":"feelings","lv":"B1","nw":1},{"e":"have two left feet","d":"be very bad at dancing","x":"I'd love to join the salsa class, but I [[have two left feet]].","es":"ser un tronco para bailar","o":"Humorous. People usually say it about themselves, as a friendly excuse not to dance.","th":"body","lv":"B1","nw":1,"reg":"informal"},{"e":"have your hands full","d":"be very busy, with a lot of work or problems to deal with","x":"Can you call the client? I [[have my hands full]] with the year-end report.","es":"no dar abasto, estar con mil cosas","o":"Very common with busy jobs and small children: “She has her hands full with three kids.”","th":"body","lv":"B1","nw":1},{"e":"have your head in the clouds","d":"not pay attention to real life because you are daydreaming","x":"Jake is smart, but he often [[has his head in the clouds]] during meetings.","es":"estar en las nubes, andar en la luna","o":"Describes someone dreamy or unrealistic. Don't confuse it with “on cloud nine,” which means very happy.","th":"weather","lv":"B1","nw":1},{"e":"head over heels (in love)","d":"completely and deeply in love with someone","x":"Pablo fell [[head over heels]] for a woman he met on a work trip.","es":"enamorarse perdidamente, estar perdidamente enamorado/a","o":"Usually with “fall” or “be”: “fall head over heels for someone,” “be head over heels in love.”","th":"body","lv":"B1","nw":1},{"e":"highway robbery","d":"a price that is much too high","x":"Twelve dollars for a coffee at the airport? That's [[highway robbery]]!","es":"¡es un robo!","o":"American English and informal. Said with surprise or anger about prices, fees and bills.","th":"money","lv":"B1","nw":1,"reg":"informal","uk":"UK: daylight robbery"},{"e":"hit a snag","d":"to have an unexpected problem","x":"We [[hit a snag]] when the supplier sent the wrong parts.","es":"toparse con un problema; surgir un inconveniente","th":"trouble","lv":"B1","src":["b1-w-achieve","b1-w-now"],"nw":0},{"e":"hit it off","d":"to like someone immediately and become friendly","x":"Pablo and the new engineer [[hit it off]] right away. They're both crazy about soccer.","es":"hacer buenas migas; hacer clic","th":"people","lv":"B1","src":["b2-relationships","b1-w-social3"],"nw":0},{"e":"hit or miss","d":"sometimes good and sometimes bad; not reliable","x":"The quality of their deliveries is [[hit or miss]].","es":"a veces sí, a veces no; irregular","th":"risk","lv":"B1","src":["b1-w-quality3","b2-w-socialmkt4"],"nw":0},{"e":"hit rock bottom","d":"to reach the lowest possible level","x":"Sales [[hit rock bottom]] in April, but then they started to recover.","es":"tocar fondo","th":"success","lv":"B1","src":["b1-w-trends"],"nw":0},{"e":"hit the ground running","d":"to start working hard and fast as soon as you arrive or begin","x":"We land at eight and the meeting is at nine, so we'll have to [[hit the ground running]].","es":"partir con todo; empezar a toda máquina","th":"success","lv":"B1","src":["b1-biztravel3","b2-careers","c1-w-career"],"nw":0},{"e":"hit the gym","d":"to go to the gym to exercise (informal)","x":"I [[hit the gym]] three times a week after work.","es":"ir al gimnasio a entrenar","th":"sport","lv":"B1","src":["b1-fitness3"],"nw":0},{"e":"hit the nail on the head","d":"describe a situation or problem exactly right","x":"You [[hit the nail on the head]]: the problem isn't the price, it's the service.","es":"dar en el clavo","o":"Said to agree strongly with someone's comment or analysis. Same idea as the Spanish expression.","th":"talk","lv":"B1","nw":1},{"e":"hit the shelves","d":"to become available in stores for the first time","x":"The new flavor [[hits the shelves]] next Monday.","es":"salir a la venta; llegar a las tiendas","th":"money","lv":"B1","src":["b1-w-launch3"],"nw":0},{"e":"hold your horses","d":"wait a moment; don't act or decide too quickly","x":"[[Hold your horses]]! Let's read the contract before we sign anything.","es":"¡calma!, ¡espérate un poco!","o":"Friendly and a little humorous. Said to someone who is too excited or in too much of a hurry.","th":"animals","lv":"B1","nw":1,"reg":"informal"},{"e":"if worst comes to worst","d":"if the most difficult or negative situation happens","x":"[[If worst comes to worst]], we can stay with my parents for a few weeks.","es":"en el peor de los casos","o":"Used to talk about a backup plan. Americans also say “if worse comes to worst.”","th":"risk","lv":"B1","nw":1,"uk":"UK: if the worst comes to the worst"},{"e":"in a nutshell","d":"in a very short, simple way","x":"[[In a nutshell]], the new process is faster and cheaper.","es":"en pocas palabras; en resumen","th":"talk","lv":"B1","src":["b2-presentations","b1-w-webinar3","b2-w-intro"],"nw":0},{"e":"in a pickle","d":"in a difficult or confusing situation","x":"I locked my keys in the car. I'm [[in a pickle]] — can you help?","es":"estar en un aprieto, estar en un lío","o":"Light and informal: for annoying problems, not serious tragedies. Often “in a bit of a pickle.”","th":"food","lv":"B1","nw":1,"reg":"informal"},{"e":"in high spirits","d":"happy, excited and full of energy","x":"The team was [[in high spirits]] after winning the company's biggest contract.","es":"de muy buen ánimo","o":"Often describes a group at a celebration or after good news. The opposite is “in low spirits.”","th":"feelings","lv":"B1","nw":1},{"e":"in no time","d":"very quickly or very soon","x":"Don't worry about the new software — you'll learn it [[in no time]].","es":"en un dos por tres, al tiro (Chile)","o":"Also “in no time at all.” Common when encouraging someone or promising fast service.","th":"time","lv":"B1","nw":1},{"e":"in the bag","d":"certain to be won or achieved","x":"The client loved our proposal. I think the contract is [[in the bag]].","es":"estar en el bolsillo","o":"Informal. Be careful: saying it too early can sound overconfident.","th":"success","lv":"B1","nw":1,"reg":"informal"},{"e":"in the blink of an eye","d":"extremely quickly","x":"The weekend went by [[in the blink of an eye]], and suddenly it was Monday again.","es":"en un abrir y cerrar de ojos","o":"Same image as the Spanish expression. Often used about time passing or things disappearing very fast.","th":"body","lv":"B1","nw":1},{"e":"in the zone","d":"completely focused on what you are doing","x":"Don't talk to Rodrigo now. He's [[in the zone]].","es":"estar enchufado; estar súper concentrado","th":"feelings","lv":"B1","src":["b1-w-routine"],"nw":0},{"e":"it's a small world","d":"said when you meet someone you know, or someone connected to you, in an unexpected place","x":"I met my old teacher at a café in Lisbon. [[It's a small world]]!","es":"el mundo es un pañuelo","th":"people","lv":"B1","src":["b1-travel","b1-w-intro"],"nw":0},{"e":"it's about time","d":"used to say that something should have happened earlier","x":"They're finally fixing the elevator? [[It's about time]]!","es":"¡ya era hora!","o":"Shows impatience or relief. Also with a clause: “It's about time you called your mother.”","th":"time","lv":"B1","nw":1},{"e":"it's not rocket science","d":"it's easy to understand or do","x":"Just follow the steps. [[It's not rocket science]]!","es":"no hay que ser un genio; no es física cuántica","th":"trouble","lv":"B1","src":["b1-tech","b2-space4"],"nw":0},{"e":"it's on me","d":"I'll pay (for the food or drinks)","x":"Put your wallet away. [[It's on me]] today!","es":"yo invito","th":"money","lv":"B1","src":["b1-food"],"nw":0},{"e":"jump at the chance","d":"accept an opportunity quickly and with enthusiasm","x":"When they offered me a job in Barcelona, I [[jumped at the chance]].","es":"no pensarlo dos veces, aprovechar la oportunidad","o":"Also “jump at the opportunity” or “jump at an offer.” It shows you didn't hesitate.","th":"risk","lv":"B1","nw":1},{"e":"jump on the bandwagon","d":"to copy something just because it's popular right now","x":"Every company is [[jumping on the bandwagon]] and making short videos.","es":"subirse al carro (de la moda)","th":"people","lv":"B1","src":["b2-media","c1-music","c1-health","b1-w-brand3","b2-w-greenbiz4","c1-w-pr5","c2-w-now"],"nw":0},{"e":"jump the gun","d":"to do something too soon, before the right moment","x":"I [[jumped the gun]] and sent the invitation before the date was confirmed.","es":"adelantarse (a los hechos); precipitarse","th":"time","lv":"B1","src":["b1-w-mistakes3"],"nw":0},{"e":"just kidding","d":"I'm only joking","x":"I'm leaving the company… [[just kidding]]!","es":"¡es broma!; ¡era broma!","th":"talk","lv":"B1","src":["b1-humor"],"nw":0},{"e":"keep a straight face","d":"to stop yourself from laughing or smiling","x":"When his cat walked across the keyboard, it was hard to [[keep a straight face]].","es":"aguantarse la risa; mantenerse serio","th":"body","lv":"B1","src":["c2-humor","b1-w-humor3","b2-w-body4"],"nw":0},{"e":"keep someone in the loop","d":"to keep someone informed about what is happening","x":"Please [[keep me in the loop]] about the new client.","es":"mantener a alguien al tanto","th":"talk","lv":"B1","src":["b1-w-role","b1-w-boss3"],"nw":0},{"e":"keep someone on the edge of their seat","d":"to make someone very excited and nervous to know what happens next","x":"The last episode [[kept me on the edge of my seat]].","es":"tener a alguien al borde del asiento; mantener en suspenso","th":"feelings","lv":"B1","src":["b1-series3"],"nw":0},{"e":"keep someone posted","d":"to give someone regular news about a situation","x":"The flight is delayed. I'll [[keep you posted]].","es":"mantener informado; tener al tanto","th":"talk","lv":"B1","src":["b1-w-email","b2-w-now"],"nw":0},{"e":"keep your cool","d":"to stay calm in a difficult situation","x":"The customer was shouting, but Ana [[kept her cool]].","es":"mantener la calma; no perder la cabeza","th":"feelings","lv":"B1","src":["b1-customers3","c1-w-skills"],"nw":0},{"e":"keep your eye on the ball","d":"stay focused on what is most important","x":"Ignore the office gossip and [[keep your eye on the ball]]: the launch is in two weeks.","es":"no perder el foco, concentrarse en lo importante","o":"The image comes from ball sports. Not the same as “keep an eye on” (watch carefully).","th":"sport","lv":"B1","nw":1},{"e":"keep your options open","d":"not make a final decision yet, so you can still choose later","x":"I'm interviewing with two companies to [[keep my options open]].","es":"no cerrarse puertas, dejar las opciones abiertas","o":"Common in decisions about work, studies and relationships. Neutral and polite.","th":"risk","lv":"B1","nw":1},{"e":"kick something off","d":"start an event, meeting or activity","x":"Let's [[kick off]] the meeting with a quick update from each team.","es":"dar el puntapié inicial, empezar","o":"From soccer and football, where a kick starts the game. Also a noun: “the kickoff meeting.”","th":"sport","lv":"B1","nw":1},{"e":"kill two birds with one stone","d":"to do two useful things with one action","x":"I bike to work, so I [[kill two birds with one stone]]: I exercise and save money.","es":"matar dos pájaros de un tiro","th":"animals","lv":"B1","src":["b1-environment","b2-time4","b1-w-routine","b2-w-greenbiz4"],"nw":0},{"e":"learn by heart","d":"to memorize something so you can say it without looking","x":"As a child, I [[learned the national anthem by heart]].","es":"aprenderse de memoria","th":"body","lv":"B1","src":["b1-school3","b2-education4"],"nw":0},{"e":"learn the hard way","d":"to learn something from an unpleasant experience","x":"I [[learned the hard way]] that you should always save your work.","es":"aprender a los porrazos; aprender por las malas","th":"trouble","lv":"B1","src":["b2-personal","b2-startups4","b1-w-past","c1-w-past"],"nw":0},{"e":"lend a hand","d":"to help someone, especially with a practical job","x":"Can you [[lend me a hand]] with these boxes?","es":"echar una mano; dar una mano","th":"body","lv":"B1","src":["b1-volunteer3"],"nw":0},{"e":"let the cat out of the bag","d":"to tell a secret, often by mistake","x":"We planned a surprise party for Dad, but my little brother [[let the cat out of the bag]].","es":"soltar la pepa; irse de lengua","th":"animals","lv":"B1","src":["b1-animals3"],"nw":0},{"e":"let your hair down","d":"to relax and enjoy yourself without worrying","x":"Work has been crazy. This weekend I just want to [[let my hair down]].","es":"soltarse el pelo; relajarse","th":"body","lv":"B1","src":["b1-festivals3","b1-w-social3"],"nw":0},{"e":"like clockwork","d":"very smoothly and regularly, without any problems","x":"Our delivery system works [[like clockwork]].","es":"como un reloj; a la perfección","th":"time","lv":"B1","src":["b1-w-process"],"nw":0},{"e":"like father, like son","d":"a son is often similar to his father","x":"Alex is an engineer, just like his dad. [[Like father, like son]]!","es":"de tal palo, tal astilla","o":"You can also say “like mother, like daughter.” Used for character, habits and jobs.","th":"people","lv":"B1","nw":1},{"e":"like it was yesterday","d":"very clearly, even though it happened a long time ago","x":"I remember my first day of school [[like it was yesterday]].","es":"como si fuera ayer","th":"time","lv":"B1","src":["b1-personal"],"nw":0},{"e":"live out of a suitcase","d":"to travel so much that you never really unpack","x":"I love my job, but I'm tired of [[living out of a suitcase]].","es":"vivir con la maleta a cuestas","th":"travel","lv":"B1","src":["b1-biztravel3","b2-travel","c1-w-trips"],"nw":0},{"e":"look like a million bucks","d":"to look extremely good (informal)","x":"You [[look like a million bucks]] in that suit!","es":"verse espectacular; estar de revista","th":"money","lv":"B1","src":["b1-fashion3"],"nw":0},{"e":"look on the bright side","d":"to see the good part of a bad situation","x":"The flight was canceled, but [[look on the bright side]]: we can finish the report tonight.","es":"ver el lado positivo","th":"feelings","lv":"B1","src":["b1-w-badnews3"],"nw":0},{"e":"make a comeback","d":"become successful or popular again after a period of failure","x":"Vinyl records have [[made a comeback]] in the last few years.","es":"volver a las pistas, volver a estar de moda","o":"Used for artists, athletes, products and fashion styles.","th":"success","lv":"B1","nw":1},{"e":"make a quick buck","d":"earn money fast and easily, often in a way that isn't very honest","x":"Some landlords just want to [[make a quick buck]] and never fix anything.","es":"hacer plata fácil","o":"Informal. A “buck” is a dollar. It often suggests greed or a short-term attitude.","th":"money","lv":"B1","nw":1,"reg":"informal"},{"e":"make a splash","d":"to get a lot of attention in an exciting way","x":"Their first ad [[made a big splash]] on social media.","es":"causar sensación; hacer ruido","th":"success","lv":"B1","src":["b1-w-launch3"],"nw":0},{"e":"make ends meet","d":"to pay for everything you need each month, often with difficulty","x":"With two kids and high rent, it's hard to [[make ends meet]].","es":"llegar a fin de mes","th":"money","lv":"B1","src":["b1-money3","b2-everyday","c1-gig5","c2-ubi6"],"nw":0},{"e":"make hay while the sun shines","d":"to use a good time or opportunity before it ends","x":"Business is great right now, so let's [[make hay while the sun shines]].","es":"aprovechar mientras se pueda; aprovechar la racha","th":"weather","lv":"B1","src":["b1-w-tourism3"],"nw":0},{"e":"make or break","d":"deciding whether something will be a complete success or a failure","x":"This meeting with the investors is [[make or break]] for our startup.","es":"decisivo/a, todo o nada","o":"Before a noun, use hyphens: “a make-or-break moment.” Common in business and sports news.","th":"risk","lv":"B1","nw":1},{"e":"make yourself at home","d":"relax and feel comfortable in my home (said to guests)","x":"Come in! [[Make yourself at home]]. Would you like some tea?","es":"siéntete como en tu casa; estás en tu casa","th":"people","lv":"B1","src":["b1-home3"],"nw":0},{"e":"man's best friend","d":"a dog (because dogs are so loyal to people)","x":"They say a dog is [[man's best friend]], and my dog Toby is definitely mine.","es":"el mejor amigo del hombre","th":"animals","lv":"B1","src":["b1-animals3"],"nw":0},{"e":"meet someone halfway","d":"to compromise, so each person gets part of what they want","x":"You want 50,000 pesos and I offered 30,000. Can we [[meet halfway]] at 40,000?","es":"llegar a un punto medio; ceder cada uno un poco","th":"people","lv":"B1","src":["b1-negotiation","c1-w-calls"],"nw":0},{"e":"money is no object","d":"the cost doesn't matter because there is enough money","x":"If [[money were no object]], I'd travel around the world for a year.","es":"la plata no es problema","o":"Often used in “if” sentences to talk about dreams, or to describe very rich customers.","th":"money","lv":"B1","nw":1},{"e":"music to my ears","d":"news that makes you very happy","x":"'No homework today' — that's [[music to my ears]]!","es":"música para mis oídos","th":"body","lv":"B1","src":["b1-music"],"nw":0},{"e":"my mind went blank","d":"I suddenly couldn't remember or think of anything","x":"The client asked me a simple question, and [[my mind went blank]].","es":"quedarse en blanco","th":"body","lv":"B1","src":["b1-w-past"],"nw":0},{"e":"neck and neck","d":"exactly equal in a race or competition, so either could win","x":"Our two best salespeople are [[neck and neck]] for Employee of the Month.","es":"codo a codo, muy parejos","o":"From horse racing, when two horses run side by side. Common in news about competitions and sales.","th":"sport","lv":"B1","nw":1},{"e":"nip something in the bud","d":"to stop a problem early, before it gets worse","x":"We saw a few late deliveries and [[nipped the problem in the bud]].","es":"cortar de raíz","th":"trouble","lv":"B1","src":["c1-crisis5","b1-w-quality3"],"nw":0},{"e":"not my cup of tea","d":"not the kind of thing I like","x":"Thanks for the invitation, but musicals are [[not my cup of tea]].","es":"no es lo mío; no es de mi gusto","th":"food","lv":"B1","src":["b1-series3","c2-aesthetics6"],"nw":0},{"e":"not take no for an answer","d":"to keep trying even when someone refuses","x":"She called the hospital five times. She just [[wouldn't take no for an answer]].","es":"no aceptar un no por respuesta","th":"success","lv":"B1","src":["b1-w-sales3"],"nw":0},{"e":"not the end of the world","d":"not as serious or terrible as it seems","x":"You forgot the attachment? It's [[not the end of the world]]. Just send it again.","es":"no es el fin del mundo","th":"trouble","lv":"B1","src":["b1-w-mistakes3"],"nw":0},{"e":"off the beaten path","d":"in a place that tourists don't usually know about","x":"Our guide took us to a little restaurant [[off the beaten path]].","es":"fuera de las rutas turísticas; poco conocido","th":"travel","lv":"B1","src":["b1-city3","b1-wildlife3","b2-travel","c2-travel","b1-w-tourism3"],"nw":0},{"e":"on edge","d":"nervous, worried and easily upset","x":"Everyone in the office was [[on edge]] while we waited for news about layoffs.","es":"con los nervios de punta","o":"Usually with “be” or “feel.” Don't confuse it with “on the edge of your seat” (very excited).","th":"feelings","lv":"B1","nw":1},{"e":"on the ball","d":"quick to understand things and react to them","x":"Our new assistant is really [[on the ball]]. She found the mistake in the invoice right away.","es":"estar atento; ser muy despierto","th":"sport","lv":"B1","src":["b1-w-review3"],"nw":0},{"e":"on the fence","d":"not able to decide between two options","x":"Most of the team agreed, but Pedro was still [[on the fence]].","es":"estar indeciso; no decidirse","th":"risk","lv":"B1","src":["c1-meetings","b1-w-decisions"],"nw":0},{"e":"on the right track","d":"doing something in a way that will probably succeed","x":"Your business plan isn't finished, but you're [[on the right track]].","es":"ir por buen camino","o":"Used to encourage someone. The opposite is “on the wrong track.”","th":"travel","lv":"B1","nw":1},{"e":"one thing after another","d":"a series of problems that never seem to stop","x":"First the car, then the roof, now the dishwasher — it's been [[one thing after another]].","es":"una cosa tras otra, un problema tras otro","o":"Usually about a stressful week or period: “It's been one thing after another.”","th":"trouble","lv":"B1","nw":1},{"e":"out of sight, out of mind","d":"people soon forget about things or people they don't see","x":"I worry my boss will forget about me. You know: [[out of sight, out of mind]].","es":"ojos que no ven, corazón que no siente","th":"people","lv":"B1","src":["b1-remote3","b2-hybrid4","b2-w-subscription4","c1-w-space","c2-w-calls","c2-w-trips"],"nw":0},{"e":"out of the question","d":"impossible, or not allowed at all","x":"Another day off this month is [[out of the question]], I'm afraid.","es":"ni pensarlo, ni hablar","o":"A firm, slightly formal way to say no. Always with “the”: “out of the question.”","th":"risk","lv":"B1","nw":1},{"e":"paint the town red","d":"to go out and celebrate in a wild, noisy way","x":"It's Carla's 40th birthday, so we're going to [[paint the town red]] on Saturday.","es":"salir a carretear; irse de fiesta","th":"colors","lv":"B1","src":["b1-festivals3"],"nw":0},{"e":"pass with flying colors","d":"to pass a test or exam very easily, with a high score","x":"She practiced every day and [[passed her driving test with flying colors]].","es":"aprobar con nota máxima; sacarse un siete","th":"colors","lv":"B1","src":["b1-school3","b2-education4"],"nw":0},{"e":"patch things up","d":"become friends again after an argument","x":"Jen and her sister finally [[patched things up]] after a year of not speaking.","es":"hacer las paces, arreglarse","o":"Common for friends, couples and families. Also “patch it up with someone.”","th":"people","lv":"B1","nw":1},{"e":"pay it forward","d":"to help someone else because another person helped you","x":"A stranger paid for my coffee, so I [[paid it forward]] and bought one for the next customer.","es":"hacer una cadena de favores","th":"people","lv":"B1","src":["b1-volunteer3"],"nw":0},{"e":"pay through the nose","d":"to pay much more than something is worth","x":"We [[paid through the nose]] for our first card machine.","es":"pagar un ojo de la cara","th":"body","lv":"B1","src":["b1-w-cashless3"],"nw":0},{"e":"pinch pennies","d":"try very hard to spend as little money as possible","x":"We're [[pinching pennies]] this year because we're saving for a house.","es":"cuidar hasta el último peso","o":"A “penny-pincher” is a person who hates spending money, which can sound a little negative.","th":"money","lv":"B1","nw":1},{"e":"play devil's advocate","d":"to argue the opposite side to test an idea","x":"I like the plan, but let me [[play devil's advocate]] for a minute.","es":"hacer de abogado del diablo","th":"talk","lv":"B1","src":["c1-meetings","b1-w-opinions"],"nw":0},{"e":"play hard to get","d":"pretend you are not interested in someone who likes you","x":"She likes him, but she's [[playing hard to get]] to see if he's serious.","es":"hacerse el/la difícil, hacerse de rogar","o":"Mostly about dating, but also used for job candidates or clients who seem hard to win.","th":"people","lv":"B1","nw":1},{"e":"play phone tag","d":"to keep missing each other's calls and leaving messages","x":"We [[played phone tag]] for three days before we finally talked.","es":"no lograr ubicarse por teléfono","th":"talk","lv":"B1","src":["b1-calls3"],"nw":0},{"e":"pop the question","d":"ask someone to marry you","x":"He [[popped the question]] at the restaurant where they had their first date.","es":"pedirle matrimonio a alguien","o":"Informal. Everyone understands which question it is: “Will you marry me?”","th":"people","lv":"B1","nw":1,"reg":"informal"},{"e":"pull an all-nighter","d":"to stay awake all night to work or study","x":"I [[pulled an all-nighter]] before my final exam.","es":"amanecerse (estudiando o trabajando); pasar la noche en vela","th":"time","lv":"B1","src":["b1-deadlines3"],"nw":0},{"e":"pull someone's leg","d":"to tell someone something untrue as a joke","x":"Relax, there's no meeting on Saturday. I'm just [[pulling your leg]]!","es":"tomarle el pelo a alguien","th":"body","lv":"B1","src":["b2-humor","b1-w-humor3"],"nw":0},{"e":"pull your weight","d":"to do your fair share of the work","x":"Everyone on this team [[pulls their weight]].","es":"hacer su parte; poner de su parte","th":"people","lv":"B1","src":["b1-meetings","c2-ubi6"],"nw":0},{"e":"puppy dog eyes","d":"a sad, cute look that someone uses to get what they want","x":"My son gave me [[puppy dog eyes]] until I bought him an ice cream.","es":"ojitos de cachorro; carita de pena","th":"animals","lv":"B1","src":["b1-animals3"],"nw":0},{"e":"put a face to the name","d":"to finally meet someone you only knew by name, email or phone","x":"It's great to finally [[put a face to the name]] after all our emails!","es":"ponerle cara al nombre; conocer en persona","th":"body","lv":"B1","src":["b1-w-intro"],"nw":0},{"e":"put something on the map","d":"to make a place or a company famous","x":"That international award really [[put our small agency on the map]].","es":"dar a conocer; poner en el mapa","th":"success","lv":"B1","src":["b1-w-brand3"],"nw":0},{"e":"put your foot in your mouth","d":"to say something embarrassing or offensive by accident","x":"I [[put my foot in my mouth]] when I called the client by the wrong name.","es":"meter la pata","th":"body","lv":"B1","src":["c1-etiquette5","b1-w-etiquette3","c1-w-execs5"],"nw":0},{"e":"rain on someone's parade","d":"spoil someone's happy plans or good news","x":"I hate to [[rain on your parade]], but the beach will be closed on Saturday.","es":"aguarle la fiesta a alguien","o":"Often “I hate to rain on your parade, but…” as a polite way to give bad news.","th":"weather","lv":"B1","nw":1},{"e":"raise the bar","d":"to set a higher standard for everyone","x":"The new manager has really [[raised the bar]] for customer service.","es":"subir la vara; poner la vara alta","th":"sport","lv":"B1","src":["b1-w-review3"],"nw":0},{"e":"read between the lines","d":"to understand what someone really means but doesn't say directly","x":"He said he'd 'think about it', but if you [[read between the lines]], the answer is no.","es":"leer entre líneas","th":"talk","lv":"B1","src":["c1-media","c2-literature6","b1-w-report","b2-w-report","c1-w-email","c2-w-email"],"nw":0},{"e":"recharge your batteries","d":"to rest so that you have energy again","x":"A long weekend at the beach is the perfect way to [[recharge your batteries]].","es":"cargar las pilas","th":"feelings","lv":"B1","src":["c2-solitude6","b1-w-wellness3","b2-w-introverts4"],"nw":0},{"e":"red tape","d":"too many official rules and papers that slow things down","x":"There's so much [[red tape]] here that a simple purchase takes two weeks.","es":"burocracia; mucho papeleo","th":"colors","lv":"B1","src":["b1-w-bigsmall3","b2-w-rules"],"nw":0},{"e":"reinvent the wheel","d":"to waste time creating something that already exists","x":"There are great templates online, so don't [[reinvent the wheel]].","es":"reinventar la rueda; complicarse la vida","th":"time","lv":"B1","src":["b1-inventions3","c1-edreform5","c1-w-stock","c2-w-compare","c2-w-process"],"nw":0},{"e":"ring a bell","d":"to sound familiar","x":"Her name [[rings a bell]], but I can't remember any of her songs.","es":"sonar conocido; me suena","th":"talk","lv":"B1","src":["b1-music","c1-nostalgia5"],"nw":0},{"e":"roll out the red carpet","d":"to welcome an important guest in a special way","x":"When the CEO visited, the Antofagasta office [[rolled out the red carpet]].","es":"recibir con alfombra roja","th":"colors","lv":"B1","src":["b1-w-trips"],"nw":0},{"e":"rumor has it","d":"people are saying something, but it may not be true","x":"[[Rumor has it]] that the company is moving to a bigger building.","es":"dicen que, corre el rumor de que","o":"Usually at the start of a sentence, followed by a clause with or without “that.”","th":"talk","lv":"B1","nw":1,"uk":"UK spelling: rumour has it"},{"e":"run on empty","d":"to keep working when you have no energy left","x":"I only slept three hours. I'm [[running on empty]] today.","es":"andar con las pilas bajas; estar sin energía","th":"feelings","lv":"B1","src":["b1-w-wellness3"],"nw":0},{"e":"safe and sound","d":"not hurt or damaged, especially after a trip or a dangerous situation","x":"Text me when you get home so I know you're [[safe and sound]].","es":"sano/a y salvo/a","o":"Usually after “arrive,” “get home” or “be back.” Same idea as the Spanish expression.","th":"travel","lv":"B1","nw":1},{"e":"save for a rainy day","d":"to keep some money for problems in the future","x":"Don't spend all your bonus. [[Save some for a rainy day]].","es":"guardar para las vacas flacas; ahorrar para imprevistos","th":"weather","lv":"B1","src":["b1-money3"],"nw":0},{"e":"see eye to eye","d":"to agree with someone","x":"My mom and I don't always [[see eye to eye]] about money.","es":"estar de acuerdo; ver las cosas de la misma forma","th":"body","lv":"B1","src":["b1-relationships","b2-generations4","b1-w-opinions"],"nw":0},{"e":"set your sights on","d":"to decide that you really want to get or achieve something","x":"Ana has [[set her sights on]] a job at the head office in Madrid.","es":"poner la mira en; tener la mira puesta en","th":"success","lv":"B1","src":["b1-w-future"],"nw":0},{"e":"shop till you drop","d":"to shop for a very long time, until you're exhausted","x":"On Black Friday, my sister and I [[shopped till we dropped]].","es":"comprar hasta caer rendido","th":"money","lv":"B1","src":["b1-shopping3"],"nw":0},{"e":"speak of the devil","d":"said when the person you're talking about suddenly appears","x":"Have you seen Martín today? Oh, [[speak of the devil]] — here he comes!","es":"hablando del rey de Roma","o":"Humorous, not rude. Usually said as the person walks in or calls.","th":"talk","lv":"B1","nw":1,"reg":"informal"},{"e":"steer clear of something","d":"avoid a person, place or thing because it may cause problems","x":"Experts say you should [[steer clear of]] investments that sound too good to be true.","es":"mantenerse alejado/a de algo, evitar","o":"The image is steering a car or boat away from danger. Common in advice: “Steer clear of him.”","th":"travel","lv":"B1","nw":1},{"e":"step out of your comfort zone","d":"to try something new that feels difficult or a little scary","x":"Presenting to the board helped me [[step out of my comfort zone]].","es":"salir de la zona de confort","th":"risk","lv":"B1","src":["b2-personal","b1-w-future"],"nw":0},{"e":"straight from the horse's mouth","d":"directly from the person who knows or decided something","x":"The CEO told me herself, so I heard it [[straight from the horse's mouth]].","es":"de primera fuente; directamente de la fuente","th":"animals","lv":"B1","src":["b1-w-report"],"nw":0},{"e":"stretch your legs","d":"go for a short walk after sitting for a long time","x":"We stopped at a gas station to [[stretch our legs]] and buy some snacks.","es":"estirar las piernas","o":"Very common on road trips, long flights and after long meetings. Same image as in Spanish.","th":"travel","lv":"B1","nw":1},{"e":"stuck in a rut","d":"in a boring situation that never changes","x":"I did the same tasks every day for years. I was [[stuck in a rut]].","es":"estar estancado; caer en la rutina","th":"trouble","lv":"B1","src":["b1-w-career"],"nw":0},{"e":"take it easy","d":"to relax and not work too hard","x":"I'm going to [[take it easy]] this weekend and just read.","es":"tomárselo con calma; relajarse","th":"feelings","lv":"B1","src":["b1-health"],"nw":0},{"e":"take it or leave it","d":"said when your offer is final and you won't change it","x":"Twenty dollars for both. [[Take it or leave it]].","es":"lo tomas o lo dejas","th":"money","lv":"B1","src":["b1-negotiation"],"nw":0},{"e":"take sides","d":"support one person or group in an argument","x":"When two coworkers argue, a good manager doesn't [[take sides]].","es":"tomar partido","o":"Often negative: “I don't want to take sides.” Also “take someone's side.”","th":"people","lv":"B1","nw":1},{"e":"take something with a grain of salt","d":"to not believe something completely","x":"I [[take celebrity gossip with a grain of salt]].","es":"tomar algo con pinzas","th":"food","lv":"B1","src":["b1-media","b2-tech","c1-curious","c1-food","c1-health","c2-language6","c2-memory6","c2-trust6","b2-w-genz4","c2-w-report"],"nw":0},{"e":"take the plunge","d":"to finally do something big or risky after thinking about it for a long time","x":"After years of renting, we [[took the plunge]] and bought an apartment.","es":"lanzarse; tirarse a la piscina","th":"risk","lv":"B1","src":["b1-changes3","b1-smallbiz3","b2-personal","b2-hobbies","b2-abroad4"],"nw":0},{"e":"take the red-eye","d":"to take a flight that leaves late at night and arrives early in the morning","x":"I [[took the red-eye]], so I'm a little tired today.","es":"tomar el vuelo nocturno","th":"travel","lv":"B1","src":["b1-biztravel3"],"nw":0},{"e":"take your breath away","d":"to be so beautiful or surprising that you feel amazed","x":"The view from the top of the volcano [[took my breath away]].","es":"dejar sin aliento","th":"feelings","lv":"B1","src":["b1-wildlife3"],"nw":0},{"e":"talk shop","d":"to talk about work in a social situation","x":"Please, no [[talking shop]] at the Christmas party!","es":"hablar de pega; hablar de trabajo","th":"talk","lv":"B1","src":["b2-networking4","b1-w-trips","c1-w-execs5"],"nw":0},{"e":"talk someone's ear off","d":"to talk to someone for a very long time, often too long","x":"My aunt called and [[talked my ear off]] for an hour!","es":"darle la lata a alguien; hablar hasta por los codos","th":"talk","lv":"B1","src":["b1-calls3"],"nw":0},{"e":"tell me about it","d":"used to say you understand because you have the same problem","x":"“This traffic is terrible.” “[[Tell me about it]]. I've been stuck for an hour.”","es":"¡a quién se lo dices!, ¡ni me lo digas!","o":"Informal. It doesn't ask for more information; it's a way of agreeing, often in a tired tone.","th":"talk","lv":"B1","nw":1,"reg":"informal"},{"e":"test the waters","d":"to try something on a small scale to see how people react","x":"We're selling it in two stores first to [[test the waters]].","es":"tantear el terreno","th":"risk","lv":"B1","src":["b1-w-launch3"],"nw":0},{"e":"the apple of someone's eye","d":"the person someone loves most and is very proud of","x":"Their youngest granddaughter is [[the apple of their eye]].","es":"la niña de sus ojos","o":"Usually about a child or grandchild, but also about a project or possession someone loves.","th":"food","lv":"B1","nw":1},{"e":"the big picture","d":"the general situation, not the small details","x":"Before we talk about costs, let's look at [[the big picture]].","es":"el panorama general; la visión global","th":"risk","lv":"B1","src":["b2-presentations","b1-w-present"],"nw":0},{"e":"the black sheep of the family","d":"a family member who is very different from the others, often in a way the family doesn't like","x":"My uncle is [[the black sheep of the family]]. He's always getting into trouble.","es":"la oveja negra de la familia","th":"animals","lv":"B1","src":["b1-relationships"],"nw":0},{"e":"the daily grind","d":"boring work that you have to do every day","x":"Weekends are my escape from [[the daily grind]].","es":"la rutina diaria; el día a día","th":"time","lv":"B1","src":["c1-everyday","b1-w-satisfaction3","c2-w-routine"],"nw":0},{"e":"the gift of gab","d":"a natural ability to talk easily and persuade people","x":"My brother has [[the gift of gab]]. He could sell sand in the desert!","es":"tener labia; tener el don de la palabra","th":"talk","lv":"B1","src":["b1-w-sales3"],"nw":0},{"e":"the golden rule","d":"the most important rule or principle to follow","x":"[[The golden rule]] of saving money is simple: spend less than you earn.","es":"la regla de oro","o":"Used for advice in any area. It also means treating others the way you want them to treat you.","th":"colors","lv":"B1","nw":1},{"e":"the grass is always greener","d":"other people's jobs or lives always seem better than yours","x":"Everyone wants my job, and I want theirs. [[The grass is always greener]]!","es":"el pasto del vecino siempre es más verde","th":"colors","lv":"B1","src":["c2-relationships","b1-w-career","b2-w-turnover4"],"nw":0},{"e":"the home stretch","d":"the last part of a long journey, project or task","x":"The project ends on Friday, so we're in [[the home stretch]] now.","es":"la recta final","o":"From horse racing: the last straight part of the track before the finish line.","th":"sport","lv":"B1","nw":1,"uk":"UK also: the home straight"},{"e":"the hustle and bustle","d":"the noise and activity of a busy place","x":"I love [[the hustle and bustle]] of downtown, but I need a quiet home.","es":"el ajetreo; el ir y venir","th":"travel","lv":"B1","src":["b1-city3"],"nw":0},{"e":"the icing on the cake","d":"something extra that makes a good situation even better","x":"We finished early, and the bonus was [[the icing on the cake]].","es":"la guinda de la torta","th":"food","lv":"B1","src":["b1-w-achieve"],"nw":0},{"e":"the last straw","d":"the final problem in a series that makes you lose your patience","x":"The Wi-Fi went down in the middle of my presentation. That was [[the last straw]]!","es":"la gota que rebalsó el vaso","th":"trouble","lv":"B1","src":["b1-workplace","b2-complaints4"],"nw":0},{"e":"the last thing I need","d":"something unwelcome, because you already have enough problems","x":"A flat tire on the way to my interview? That's [[the last thing I need]].","es":"¡lo único que me faltaba!","o":"Said with frustration about bad timing. Also with other people: “That's the last thing she needs.”","th":"trouble","lv":"B1","nw":1},{"e":"the life of the party","d":"a fun, lively person who makes a party more enjoyable","x":"My aunt is always [[the life of the party]].","es":"el alma de la fiesta","th":"people","lv":"B1","src":["b1-humor"],"nw":0},{"e":"the personal touch","d":"small human details that make service feel special","x":"A handwritten note adds [[the personal touch]] to every order.","es":"el toque personal","th":"people","lv":"B1","src":["b1-w-loyalty3"],"nw":0},{"e":"there's no place like home","d":"your own home is the best place to be","x":"The trip was amazing, but [[there's no place like home]].","es":"como en casa, en ninguna parte","th":"feelings","lv":"B1","src":["b1-home3"],"nw":0},{"e":"think on your feet","d":"to make quick, good decisions without time to prepare","x":"In sales, you have to [[think on your feet]] when a client says no.","es":"pensar rápido; improvisar sobre la marcha","th":"body","lv":"B1","src":["c1-presentations","b1-w-skills","b2-w-introverts4"],"nw":0},{"e":"think outside the box","d":"to think in a new and creative way","x":"We need to [[think outside the box]] to beat our competitors.","es":"pensar fuera de la caja; salirse de lo convencional","th":"success","lv":"B1","src":["b2-art4","b1-w-opinions"],"nw":0},{"e":"think twice","d":"to think very carefully before you do something","x":"I'd [[think twice]] before keeping money that isn't mine.","es":"pensarlo dos veces","th":"risk","lv":"B1","src":["b1-ethics","b1-w-mistakes3"],"nw":0},{"e":"third time's the charm","d":"the third try will be successful after two failures","x":"I failed my driving test twice, but [[third time's the charm]]!","es":"la tercera es la vencida","o":"American English. Said to encourage yourself or someone else before a third attempt.","th":"success","lv":"B1","nw":1,"uk":"UK: third time lucky"},{"e":"through the grapevine","d":"informally, from other people and not from an official source","x":"I heard [[through the grapevine]] that Marcela is leaving the company.","es":"por radio pasillo; me lo contó un pajarito","th":"talk","lv":"B1","src":["b1-w-report"],"nw":0},{"e":"throw in the towel","d":"to stop trying because something is too hard","x":"After three failed driving tests, I almost [[threw in the towel]].","es":"tirar la toalla","th":"sport","lv":"B1","src":["b1-fitness3","b2-competition4"],"nw":0},{"e":"time will tell","d":"we will only know the result in the future","x":"Will the new manager be any good? Only [[time will tell]].","es":"el tiempo lo dirá","o":"Often with “only”: “Only time will tell.” Used when the result is not clear yet.","th":"time","lv":"B1","nw":1},{"e":"to make matters worse","d":"used to add one more problem to a bad situation","x":"It was raining hard, and [[to make matters worse]], I forgot my umbrella.","es":"para colmo, para peor","o":"Works like a connector when telling a story. Usually at the start of a sentence or clause.","th":"trouble","lv":"B1","nw":1},{"e":"too many cooks in the kitchen","d":"too many people trying to help with or control one task, so it goes badly","x":"Let's not all work on the same report. [[Too many cooks in the kitchen]]!","es":"muchas manos en un plato hacen mucho garabato","th":"food","lv":"B1","src":["b1-kitchen3"],"nw":0},{"e":"touch base","d":"to contact someone briefly to share news or check progress","x":"Let's [[touch base]] on Monday to see how it's going.","es":"ponerse en contacto; hablar para ver cómo va todo","th":"talk","lv":"B1","src":["b1-meetings","b2-w-jargon4"],"nw":0},{"e":"two peas in a pod","d":"two people who are very similar or always together","x":"My sister and her best friend are like [[two peas in a pod]].","es":"ser tal para cual, ser como dos gotas de agua","o":"Usually with “like”: “They're like two peas in a pod.” Positive and friendly.","th":"food","lv":"B1","nw":1},{"e":"under the same roof","d":"living together in the same house","x":"Three generations of my family live [[under the same roof]].","es":"bajo el mismo techo","th":"people","lv":"B1","src":["b1-home3"],"nw":0},{"e":"up to par","d":"good enough; at the level that people expect","x":"The new supplier's fabric isn't [[up to par]].","es":"estar a la altura; dar el ancho","th":"success","lv":"B1","src":["b1-w-quality3"],"nw":0},{"e":"up to your ears in","d":"having a very large amount of something to deal with","x":"I'm [[up to my ears in]] invoices this week.","es":"estar hasta el cuello de algo; estar tapado de","th":"body","lv":"B1","src":["b1-w-now"],"nw":0},{"e":"wear many hats","d":"to have several different jobs or roles at the same time","x":"In a startup, everyone [[wears many hats]].","es":"cumplir muchos roles a la vez; ser hombre orquesta","th":"money","lv":"B1","src":["b1-presentations","b1-w-freelance3","b2-w-intro"],"nw":0},{"e":"when in Rome","d":"when you're in another place, follow the local customs","x":"Everyone was having dinner at ten at night, so I did too. [[When in Rome]]!","es":"donde fueres, haz lo que vieres","th":"travel","lv":"B1","src":["b1-cultureshock3","b1-w-rules"],"nw":0},{"e":"wine and dine","d":"to entertain someone with good food and drinks, often for business","x":"The company [[wined and dined]] the investors at a top restaurant.","es":"agasajar con comida y bebida; atender a cuerpo de rey","th":"food","lv":"B1","src":["b1-w-trips"],"nw":0},{"e":"word of mouth","d":"when people tell other people about something they liked","x":"We don't pay for ads. All our clients come by [[word of mouth]].","es":"el boca a boca; de boca en boca","th":"talk","lv":"B1","src":["b1-w-tourism3"],"nw":0},{"e":"work your way up","d":"to start at a low level and slowly get promoted","x":"He [[worked his way up]] from warehouse assistant to operations manager.","es":"ir escalando posiciones; partir desde abajo","th":"success","lv":"B1","src":["b1-w-intern3"],"nw":0},{"e":"worth your weight in gold","d":"extremely useful or valuable","x":"A good IT technician is [[worth their weight in gold]].","es":"valer oro; valer su peso en oro","th":"money","lv":"B1","src":["b1-w-satisfaction3"],"nw":0},{"e":"you can't teach an old dog new tricks","d":"older people find it hard to learn new things or change their habits","x":"My grandpa says [[you can't teach an old dog new tricks]], but he uses his smartphone better than I do.","es":"loro viejo no aprende a hablar","th":"animals","lv":"B1","src":["b1-skills3","b2-w-skills"],"nw":0},{"e":"you learn something new every day","d":"said when you hear a fact that surprises you","x":"Flamingos are pink because of the food they eat? Well, [[you learn something new every day]]!","es":"cada día se aprende algo nuevo","th":"talk","lv":"B1","src":["b1-curious"],"nw":0},{"e":"a backseat driver","d":"a passenger who gives the driver unwanted advice; anyone who interferes like this","x":"My father is the worst [[backseat driver]] — he tells me when to brake and which lane to use.","es":"el copiloto que todo lo critica / el que da órdenes sin estar al volante","o":"Also used at work for someone who isn't in charge but keeps telling others how to do their job.","th":"travel","lv":"B2","nw":1},{"e":"a ballpark figure","d":"a number that is approximately right, but not exact","x":"I can't give you the final price yet, but [[a ballpark figure]] is about two million pesos.","es":"una cifra aproximada; un cálculo al ojo","th":"sport","lv":"B2","src":["b2-w-details","c1-w-details"],"nw":0},{"e":"a bone of contention","d":"a subject that people keep arguing about","x":"The bonus system has been [[a bone of contention]] between managers and staff for years.","es":"la manzana de la discordia","th":"people","lv":"B2","src":["b2-w-family4"],"nw":0},{"e":"a bottleneck","d":"a point where a process slows down and delays everything after it","x":"Quality control has become [[a bottleneck]]; orders wait there for days.","es":"un cuello de botella","th":"trouble","lv":"B2","src":["b2-w-stock"],"nw":0},{"e":"a breath of fresh air","d":"something new and different that feels very pleasant","x":"The new office, with all its plants, is [[a breath of fresh air]].","es":"un soplo de aire fresco","th":"weather","lv":"B2","src":["b2-w-space"],"nw":0},{"e":"a cash cow","d":"a product or business that brings in a lot of money regularly with little effort","x":"The old software is still the company's [[cash cow]].","es":"la gallina de los huevos de oro","th":"animals","lv":"B2","src":["b2-w-subscription4"],"nw":0},{"e":"a close call","d":"a situation where something bad almost happened","x":"A car almost hit me at the crosswalk. It was [[a close call]].","es":"salvarse por un pelo; salvarse jabonado","th":"risk","lv":"B2","src":["b2-crime4"],"nw":0},{"e":"a creature of habit","d":"a person who likes to do the same things in the same way every day","x":"My dad is [[a creature of habit]]. He's eaten the same breakfast for 30 years.","es":"un animal de costumbres","th":"people","lv":"B2","src":["b2-everyday"],"nw":0},{"e":"a dark horse","d":"a person who is not well known but surprises everyone by doing very well","x":"The quiet new chef was [[a dark horse]] — nobody expected him to win the competition.","es":"la gran sorpresa; una carta tapada","o":"From horse racing, where it meant a little-known horse that won unexpectedly. Common in sports, contests and job competitions.","th":"animals","lv":"B2","nw":1},{"e":"a dead-end job","d":"a job with no chance of promotion or development","x":"I didn't want to stay in [[a dead-end job]] forever.","es":"un trabajo sin futuro; una pega sin proyección","th":"money","lv":"B2","src":["b2-careers"],"nw":0},{"e":"a diamond in the rough","d":"a person with great potential who still needs training and experience","x":"He's [[a diamond in the rough]]; with a good mentor, he'll be excellent.","es":"un diamante en bruto","th":"people","lv":"B2","src":["b2-w-hiring4"],"nw":0},{"e":"a dime a dozen","d":"very common, and therefore not special or valuable","x":"Coffee shops are [[a dime a dozen]] in this neighborhood, so ours has to stand out.","es":"hay por montones","o":"American English; a dime is a ten-cent coin. Often slightly negative about things or people that are too common.","th":"money","lv":"B2","nw":1,"uk":"UK: two a penny / ten a penny"},{"e":"a double-edged sword","d":"something that has both good and bad effects","x":"Social media is [[a double-edged sword]] for small businesses.","es":"un arma de doble filo","th":"risk","lv":"B2","src":["b2-tech","c1-travel","c1-careers","c1-media","c2-identity6","c2-urban6","c1-w-candor5","c2-w-ai6","c2-w-deglobal6"],"nw":0},{"e":"a far cry from","d":"very different from something, usually much better or much worse","x":"My new studio is [[a far cry from]] the big house I grew up in.","es":"estar muy lejos de; no tener nada que ver con","th":"travel","lv":"B2","src":["b2-housing4","c1-plans","c1-food","c2-aiart6","c2-w-luxury6"],"nw":0},{"e":"a flash in the pan","d":"a sudden success that doesn't last","x":"The app was popular for a month, but it was just [[a flash in the pan]].","es":"flor de un día; un éxito pasajero","th":"success","lv":"B2","src":["c1-artworld5","b2-w-trends","c2-w-now"],"nw":0},{"e":"a gray area","d":"a situation where it isn't clear what is right or wrong","x":"Using the company laptop for personal projects is a bit of [[a gray area]].","es":"una zona gris","th":"colors","lv":"B2","src":["b2-ethics","c2-bioethics6","c1-w-rules"],"nw":0},{"e":"a guinea pig","d":"a person used to test something new, like a product, a method or an idea","x":"Our team agreed to be [[guinea pigs]] for the new software, so we found all the bugs first.","es":"conejillo de Indias","o":"Often “be a guinea pig” or “use someone as a guinea pig.” It refers to animals used in lab experiments.","th":"animals","lv":"B2","nw":1},{"e":"a hot potato","d":"a difficult, controversial issue that people would rather not deal with","x":"Salary cuts are [[a hot potato]], so management keeps postponing the discussion.","es":"una papa caliente; un tema delicado","o":"Common in the news and at work for topics nobody wants to be responsible for.","th":"food","lv":"B2","nw":1},{"e":"a judgment call","d":"a decision you make using your own opinion because there is no clear rule","x":"There's no policy on working from home on Fridays, so it's [[a judgment call]] for each manager.","es":"una decisión que queda a criterio de cada uno","o":"Common at work and in sports, where referees make judgment calls. Note the American spelling \"judgment.\"","th":"risk","lv":"B2","nw":1,"uk":"UK spelling: judgement call"},{"e":"a labor of love","d":"hard work done for pleasure, not money","x":"Restoring this old car was [[a labor of love]].","es":"por amor al arte; un trabajo hecho con cariño","th":"feelings","lv":"B2","src":["b2-hobbies","c2-hobbies","c2-w-meaning6"],"nw":0},{"e":"a late bloomer","d":"someone whose talent or success appears later in life than usual","x":"My grandmother started writing poetry at 70. She's a real [[late bloomer]].","es":"alguien que florece tarde; un talento tardío","th":"weather","lv":"B2","src":["b2-art4"],"nw":0},{"e":"a level playing field","d":"a situation where everyone has the same chances","x":"Rich clubs can buy the best players, so it isn't [[a level playing field]].","es":"igualdad de condiciones; una cancha pareja","th":"sport","lv":"B2","src":["b2-competition4","c1-fairplay5","c1-globalization5","b2-w-paytransp4","c2-w-merit6"],"nw":0},{"e":"a little bird told me","d":"said when you know a secret but don't want to reveal who you heard it from","x":"[[A little bird told me]] you're moving to Valparaíso — is it true?","es":"me lo contó un pajarito","o":"Playful and friendly; often used to tease someone about news or a secret you've heard.","th":"animals","lv":"B2","nw":1,"reg":"informal"},{"e":"a long shot","d":"something that has only a small chance of success","x":"Winning the government contract is [[a long shot]], but let's try anyway.","es":"una posibilidad remota; algo muy difícil de lograr","th":"risk","lv":"B2","src":["b2-w-opinions"],"nw":0},{"e":"a necessary evil","d":"something unpleasant that you have to accept because it's needed","x":"For most small companies, paperwork is [[a necessary evil]].","es":"un mal necesario","th":"trouble","lv":"B2","src":["b2-w-chatbots4"],"nw":0},{"e":"a nest egg","d":"an amount of money saved for the future","x":"They've built up a nice [[nest egg]] for their retirement.","es":"un colchón; unos ahorros para el futuro","o":"Usually savings for retirement, a house or emergencies. You build up, save or dip into a nest egg.","th":"money","lv":"B2","nw":1},{"e":"a pat on the back","d":"praise for something you did well","x":"The whole team deserves [[a pat on the back]] for this launch.","es":"una palmadita en la espalda; un reconocimiento","th":"body","lv":"B2","src":["b2-feedback4"],"nw":0},{"e":"a race against time","d":"a situation in which you must act very quickly before it's too late","x":"Saving the last few frogs of this species is [[a race against time]].","es":"una carrera contra el tiempo; una carrera contrarreloj","th":"time","lv":"B2","src":["b2-conservation4"],"nw":0},{"e":"a race to the bottom","d":"a situation where companies keep cutting prices or quality to compete, and everyone loses","x":"Cutting delivery fees again would just start [[a race to the bottom]].","es":"una competencia a la baja; una guerra de precios","th":"money","lv":"B2","src":["c1-gig5","c2-strategy6","b2-w-pricing4"],"nw":0},{"e":"a red flag","d":"a warning sign that something is wrong","x":"If someone is rude to the server on a first date, that's [[a red flag]].","es":"una señal de alerta; una bandera roja","th":"colors","lv":"B2","src":["b2-relationships","c2-w-details"],"nw":0},{"e":"a ripple effect","d":"a situation where one event causes a series of other effects","x":"The strike at the port had [[a ripple effect]] on stores all over the country.","es":"un efecto dominó; un efecto en cadena","th":"weather","lv":"B2","src":["b2-w-stock"],"nw":0},{"e":"a safe bet","d":"something that is almost certain to happen or succeed","x":"Hiring extra staff for December is [[a safe bet]]; it's always our busiest month.","es":"una apuesta segura; ir a la segura","th":"risk","lv":"B2","src":["b2-w-future"],"nw":0},{"e":"a shot in the dark","d":"a guess made with almost no information","x":"Nobody knows next year's exchange rate. Any number would be [[a shot in the dark]].","es":"un tiro a ciegas; decirlo al achunte","th":"risk","lv":"B2","src":["c2-uncertainty6","b2-w-future"],"nw":0},{"e":"a slap in the face","d":"something that feels like an insult or a sign of disrespect","x":"After all that overtime, a 1% raise felt like [[a slap in the face]].","es":"una cachetada; una falta de respeto","th":"body","lv":"B2","src":["b2-w-achieve"],"nw":0},{"e":"a slap on the wrist","d":"a punishment that is much too mild","x":"He broke the safety rules and only got [[a slap on the wrist]].","es":"un tirón de orejas; un castigo simbólico","th":"body","lv":"B2","src":["b2-w-rules"],"nw":0},{"e":"a sore loser","d":"a person who gets angry or upset when they lose","x":"Don't be [[a sore loser]]. Shake hands and congratulate them.","es":"un mal perdedor; no saber perder","th":"sport","lv":"B2","src":["b2-competition4"],"nw":0},{"e":"a stone's throw from","d":"very close to a place","x":"Our apartment is [[a stone's throw from]] the beach.","es":"a pasos de; a un paso de","th":"travel","lv":"B2","src":["b2-housing4"],"nw":0},{"e":"a tall order","d":"a task or request that is very difficult to do","x":"Finishing the whole report by Friday is [[a tall order]], but we'll do our best.","es":"mucho pedir / una tarea muy difícil","o":"Often \"That's a tall order\" when someone asks for too much, in too little time or with too little money.","th":"trouble","lv":"B2","nw":1},{"e":"a toss-up","d":"a choice or result where both options are equally likely","x":"It's [[a toss-up]] between the beach and the mountains for our vacation this year.","es":"cara o sello / está muy parejo","o":"The image is tossing a coin to decide. Used for close elections, games and personal choices.","th":"risk","lv":"B2","nw":1,"reg":"informal"},{"e":"a tough nut to crack","d":"a problem that is hard to solve, or a person who is hard to persuade","x":"The new client is [[a tough nut to crack]] — she rejected all three of our proposals.","es":"un hueso duro de roer","o":"Works for people and problems alike: a demanding customer, a tricky puzzle or a market that's hard to enter.","th":"food","lv":"B2","nw":1,"uk":"UK also: a hard nut to crack"},{"e":"a turning point","d":"a moment when an important change happens","x":"Moving abroad was [[a turning point]] in my life.","es":"un punto de inflexión; un antes y un después","th":"time","lv":"B2","src":["b2-personal"],"nw":0},{"e":"a vicious cycle","d":"a situation where one problem causes another that makes the first one worse","x":"More traffic leads to more roads, which leads to more traffic. It's [[a vicious cycle]].","es":"un círculo vicioso","th":"trouble","lv":"B2","src":["b2-environment"],"nw":0},{"e":"a wake-up call","d":"an event that makes you realize a problem needs action","x":"The cyberattack was [[a wake-up call]] for the company to invest in better security.","es":"un llamado de atención / una señal de alerta","o":"Common in news and at work. It can also be literal: a phone call from a hotel to wake you up.","th":"trouble","lv":"B2","nw":1},{"e":"a whole new ball game","d":"a completely different situation that needs new skills or ideas","x":"I managed a team of five easily, but leading fifty people is [[a whole new ball game]].","es":"otra historia / harina de otro costal","o":"In American English a \"ball game\" is often a baseball game. Also \"a different ball game.\"","th":"sport","lv":"B2","nw":1,"reg":"informal"},{"e":"a wild goose chase","d":"a long, useless search for something that is impossible to find","x":"The directions were wrong, and we spent two hours on [[a wild goose chase]] around downtown.","es":"una búsqueda inútil; dar vueltas para nada","o":"Usually with “go on” or “send someone on”: “They sent me on a wild goose chase.”","th":"animals","lv":"B2","nw":1},{"e":"against all odds","d":"despite great difficulties and very little chance of success","x":"[[Against all odds]], the small local company won the contract over three international firms.","es":"contra todo pronóstico","o":"Common in news and inspiring stories. Often at the start of a sentence, followed by a comma.","th":"success","lv":"B2","nw":1},{"e":"all hands on deck","d":"a situation in which everyone must help because there's a lot of work","x":"It's [[all hands on deck]] this week; the fair starts on Thursday.","es":"todos a arrimar el hombro; todos a bordo","th":"travel","lv":"B2","src":["b2-w-trips"],"nw":0},{"e":"an accident waiting to happen","d":"a situation that is very likely to cause problems soon","x":"Those boxes on the top shelf are [[an accident waiting to happen]].","es":"un accidente a punto de ocurrir; un peligro latente","th":"trouble","lv":"B2","src":["b2-w-problems","c1-w-problems"],"nw":0},{"e":"an acquired taste","d":"something you only start to like after trying it several times","x":"Fernet is definitely [[an acquired taste]]. It's incredibly bitter.","es":"un gusto adquirido; algo a lo que hay que acostumbrarse","th":"food","lv":"B2","src":["b2-food"],"nw":0},{"e":"an old wives' tale","d":"a traditional belief that many people repeat but that isn't true","x":"Eating carrots won't help you see in the dark. That's [[an old wives' tale]].","es":"un mito popular; una creencia sin fundamento","th":"talk","lv":"B2","src":["b2-science4"],"nw":0},{"e":"an open secret","d":"something that is supposed to be secret but that many people already know","x":"It's [[an open secret]] that the sales team earns more than we do.","es":"un secreto a voces","th":"talk","lv":"B2","src":["b2-w-paytransp4"],"nw":0},{"e":"an uphill battle","d":"a long, difficult struggle that is hard to win","x":"Protecting the forest from illegal logging is [[an uphill battle]], but some communities are winning it.","es":"una lucha cuesta arriba","th":"trouble","lv":"B2","src":["b2-conservation4"],"nw":0},{"e":"analysis paralysis","d":"a situation where you think about something so much that you never decide","x":"We've studied the options for six months. It's [[analysis paralysis]]!","es":"parálisis por análisis","th":"risk","lv":"B2","src":["b2-w-decisions"],"nw":0},{"e":"at a crossroads","d":"at a point where you must make an important decision about your future","x":"After twenty years in banking, Diego is [[at a crossroads]]: stay at the bank or start his own business.","es":"estar en una encrucijada","o":"Used for big life or career decisions, and also for countries or companies facing an important change.","th":"travel","lv":"B2","nw":1},{"e":"at someone's beck and call","d":"always ready to do whatever someone asks","x":"Assistants shouldn't be [[at their boss's beck and call]] 24 hours a day.","es":"estar a entera disposición de alguien; estar a la orden las 24 horas","th":"people","lv":"B2","src":["b2-w-routine"],"nw":0},{"e":"at the drop of a hat","d":"immediately, without hesitating or needing a reason","x":"In this job, you have to be ready to travel [[at the drop of a hat]].","es":"en un dos por tres; sin pensarlo dos veces","o":"Often about how quickly or easily someone does something: “She'd help you at the drop of a hat.”","th":"time","lv":"B2","nw":1},{"e":"at the eleventh hour","d":"at the last possible moment","x":"The two companies reached an agreement [[at the eleventh hour]], just before the deadline.","es":"al cuarto para las doce; a última hora","o":"Common in news about deals and negotiations. Also an adjective: “an eleventh-hour decision.”","th":"time","lv":"B2","nw":1},{"e":"at your wits' end","d":"so worried, tired or confused that you don't know what to do next","x":"The baby hasn't slept properly in weeks, and we're [[at our wits' end]].","es":"no saber qué más hacer; estar desesperado","o":"Note the apostrophe after the s: wits'. Used when you have tried everything and feel desperate.","th":"feelings","lv":"B2","nw":1},{"e":"be all ears","d":"to be ready and eager to listen","x":"You have a new idea for the campaign? [[I'm all ears]].","es":"ser todo oídos","th":"body","lv":"B2","src":["b2-w-listening4"],"nw":0},{"e":"be at a loss for words","d":"be so surprised, moved or shocked that you cannot speak","x":"When my coworkers surprised me with a farewell party, I [[was at a loss for words]].","es":"quedarse sin palabras","o":"Used for strong emotions, good or bad. In speeches, \"I'm at a loss for words\" often expresses deep thanks.","th":"talk","lv":"B2","nw":1,"uk":"UK also: lost for words"},{"e":"be at the end of your rope","d":"to have no patience or energy left","x":"After three sleepless nights with the baby, they [[were at the end of their rope]].","es":"no dar más; estar chato","th":"feelings","lv":"B2","src":["b2-health","c1-w-mental5"],"nw":0},{"e":"be on the same wavelength","d":"think in a similar way and understand each other easily","x":"My new business partner and I are [[on the same wavelength]], so our meetings are short and productive.","es":"estar en la misma sintonía","o":"About general compatibility between people. Compare \"on the same page,\" which means agreeing about a specific plan.","th":"people","lv":"B2","nw":1},{"e":"be out of the loop","d":"to not have the latest information that other people have","x":"I [[was out of the loop]] because nobody added me to the team chat.","es":"no estar al tanto; quedar fuera de la conversación","th":"talk","lv":"B2","src":["b2-hybrid4"],"nw":0},{"e":"beauty is in the eye of the beholder","d":"different people have different ideas about what is beautiful","x":"I think that sculpture is ugly, but [[beauty is in the eye of the beholder]].","es":"sobre gustos no hay nada escrito; la belleza está en los ojos de quien mira","th":"body","lv":"B2","src":["b2-art4"],"nw":0},{"e":"beginner's luck","d":"unexpected success when you try something for the first time","x":"I caught three fish on my first fishing trip. Pure [[beginner's luck]]!","es":"suerte de principiante","th":"success","lv":"B2","src":["b2-luck4"],"nw":0},{"e":"between a rock and a hard place","d":"having to choose between two options that are both bad","x":"We're [[between a rock and a hard place]]: raise prices and lose customers, or keep them low and lose money.","es":"estar entre la espada y la pared","o":"Always about two bad options, not just any difficult situation. Very common in American English.","th":"trouble","lv":"B2","nw":1},{"e":"big shoes to fill","d":"a job that is hard to take over because the person before you did it very well","x":"Our old CFO was brilliant, so her replacement has [[big shoes to fill]].","es":"dejar la vara muy alta; ser difícil de reemplazar","th":"success","lv":"B2","src":["b2-w-career","c2-w-future"],"nw":0},{"e":"bite the bullet","d":"to make yourself do something unpleasant that you've been avoiding","x":"I finally [[bit the bullet]] and told my boss the project was behind schedule.","es":"hacer de tripas corazón; armarse de valor","th":"risk","lv":"B2","src":["b2-w-email","c1-w-inflation5","c2-w-layoffs6"],"nw":0},{"e":"bite your tongue","d":"to stop yourself from saying something rude or angry","x":"The customer was shouting, but I [[bit my tongue]] and stayed polite.","es":"morderse la lengua","th":"body","lv":"B2","src":["b2-complaints4","c2-meetings","c1-w-skills"],"nw":0},{"e":"blood is thicker than water","d":"family loyalty is stronger than any other relationship","x":"He hired his cousin instead of the best candidate. I guess [[blood is thicker than water]].","es":"la sangre tira; la familia es primero","th":"people","lv":"B2","src":["b2-w-family4"],"nw":0},{"e":"blow off steam","d":"to do something that helps you release strong emotions or energy","x":"I go running after work to [[blow off steam]].","es":"desahogarse; liberar tensiones","th":"feelings","lv":"B2","src":["b2-health"],"nw":0},{"e":"blow the whistle","d":"to tell the authorities or the public about wrongdoing in an organization","x":"An employee [[blew the whistle]] on the company's illegal dumping.","es":"denunciar irregularidades; destapar la olla","th":"talk","lv":"B2","src":["b2-ethics","c1-bizethics5"],"nw":0},{"e":"blue-sky thinking","d":"creative thinking without worrying about practical limits","x":"This session is for [[blue-sky thinking]], so forget about the budget for now.","es":"pensar sin límites; pensar fuera de la caja","th":"colors","lv":"B2","src":["b2-w-opinions"],"nw":0},{"e":"boil the ocean","d":"to try to do far too much at once","x":"Let's not [[boil the ocean]]. We'll start with our three biggest clients.","es":"querer abarcar demasiado; el que mucho abarca poco aprieta","th":"weather","lv":"B2","src":["b2-w-jargon4"],"nw":0},{"e":"bread and butter","d":"the main work or product that gives a person or company most of its income","x":"Weddings are the [[bread and butter]] of our photography business.","es":"el pan de cada día; el sustento","o":"Also an adjective: “bread-and-butter issues” are the basic everyday concerns that matter most to people.","th":"food","lv":"B2","nw":1},{"e":"break a leg","d":"a friendly way to say 'good luck' before a performance or presentation","x":"Your big pitch is today? [[Break a leg]]!","es":"¡mucha suerte!; ¡mucho éxito!","th":"body","lv":"B2","src":["b2-w-present"],"nw":0},{"e":"breathe down someone's neck","d":"to watch someone too closely while they work","x":"I can't concentrate when my boss is [[breathing down my neck]].","es":"estar encima de alguien; no dejar a alguien ni respirar","th":"body","lv":"B2","src":["b2-leadership4","c1-w-micro5","c2-w-calls"],"nw":0},{"e":"bridge the gap","d":"to reduce the differences between two groups or things","x":"Family lunches help [[bridge the gap]] between young and old.","es":"acortar distancias; tender puentes","th":"people","lv":"B2","src":["b2-generations4"],"nw":0},{"e":"bring home the bacon","d":"to earn the money that a family needs to live","x":"Since my husband lost his job, I'm the one [[bringing home the bacon]].","es":"parar la olla; llevar el pan a la casa","o":"Informal and a bit humorous. Often about who earns the main income in a household.","th":"food","lv":"B2","nw":1,"reg":"informal"},{"e":"burn a hole in your pocket","d":"(of money) to make you want to spend it immediately","x":"My bonus is [[burning a hole in my pocket]]. I want to buy everything!","es":"quemarle la plata en las manos","th":"money","lv":"B2","src":["b2-consumer4","c1-money5"],"nw":0},{"e":"burn the midnight oil","d":"to work or study late at night","x":"She's been [[burning the midnight oil]] to finish the project.","es":"quemarse las pestañas; trasnochar trabajando","th":"time","lv":"B2","src":["b2-everyday","c2-w-busy6"],"nw":0},{"e":"burn your bridges","d":"to damage a relationship so badly that you can't go back later","x":"Don't send that angry email; you don't want to [[burn your bridges]].","es":"cerrarse las puertas; quemar los puentes","th":"people","lv":"B2","src":["c2-careers","b2-w-turnover4","c2-w-decisions","c2-w-loyalty6"],"nw":0},{"e":"bury the hatchet","d":"agree to stop arguing and be friendly again","x":"After ten years of not speaking, the two brothers finally [[buried the hatchet]] at their dad's birthday party.","es":"hacer las paces / enterrar el hacha de guerra","o":"Used for ending a long or serious conflict in families, at work or between rival companies. A hatchet is a small ax.","th":"people","lv":"B2","nw":1},{"e":"butt heads (with)","d":"to disagree strongly, often again and again","x":"Our sales and marketing managers [[butt heads]] all the time.","es":"chocar con alguien; llevarse como perro y gato","th":"body","lv":"B2","src":["b2-workplace"],"nw":0},{"e":"butter someone up","d":"to be extra nice to someone or praise them because you want a favor","x":"Jake has been [[buttering up]] his in-laws all week because he wants to borrow their beach house.","es":"jabonear a alguien; hacerle la pata a alguien","o":"Informal. The praise is not sincere: it has a clear purpose.","th":"food","lv":"B2","nw":1,"reg":"informal"},{"e":"can't hear yourself think","d":"used to say a place is extremely noisy","x":"With the construction work next door, you [[can't hear yourself think]].","es":"no se puede ni pensar (con tanto ruido)","th":"trouble","lv":"B2","src":["b2-w-space"],"nw":0},{"e":"catch someone red-handed","d":"to discover someone at the moment they are doing something wrong","x":"My roommate [[caught me red-handed]] eating her leftover pizza.","es":"pillar a alguien con las manos en la masa","o":"Often used humorously for small wrongs, but also in news about real crimes.","th":"colors","lv":"B2","nw":1},{"e":"catch someone's eye","d":"to attract someone's attention","x":"The bright yellow packaging really [[caught my eye]].","es":"llamarle la atención a alguien; saltar a la vista","th":"body","lv":"B2","src":["b2-ads4"],"nw":0},{"e":"check all the boxes","d":"to have every quality or requirement that is needed","x":"On paper, her CV [[checks all the boxes]].","es":"cumplir con todos los requisitos","th":"success","lv":"B2","src":["b2-w-hiring4"],"nw":0},{"e":"clear the air","d":"to talk openly about a problem to end bad feelings","x":"We went for a coffee to [[clear the air]] after the argument.","es":"aclarar las cosas; limar asperezas","th":"weather","lv":"B2","src":["b2-workplace","c1-relationships"],"nw":0},{"e":"come out of your shell","d":"to become more confident and willing to talk to people","x":"After a few months on the sales team, Ana really [[came out of her shell]].","es":"salir del cascarón; soltarse","th":"animals","lv":"B2","src":["b2-w-introverts4"],"nw":0},{"e":"comparing apples and oranges","d":"comparing two things that are too different to compare fairly","x":"A luxury hotel and a hostel? That's [[comparing apples and oranges]].","es":"comparar peras con manzanas","th":"food","lv":"B2","src":["b2-w-compare"],"nw":0},{"e":"crash and burn","d":"fail suddenly and completely, often in a dramatic way","x":"Their first restaurant [[crashed and burned]] within a year, but the second one is doing great.","es":"fracasar rotundamente / irse a pique","o":"Informal and dramatic. Used for businesses, plans and relationships, or for a person who fails badly, for example in an interview.","th":"success","lv":"B2","nw":1,"reg":"informal"},{"e":"crocodile tears","d":"a show of sadness or regret that is not sincere","x":"The CEO shed [[crocodile tears]] on TV, but nobody believed he cared about the workers.","es":"lágrimas de cocodrilo","o":"Usually with “cry” or “shed.” It comes from an old legend that crocodiles cry while they eat.","th":"animals","lv":"B2","nw":1},{"e":"cut someone some slack","d":"be less strict or critical with someone because they are in a difficult situation","x":"Come on, [[cut him some slack]] — it's only his second week on the job.","es":"darle un respiro a alguien / no ser tan duro con alguien","o":"Very common in American English. Often an imperative: \"Cut me some slack!\" when you feel someone is criticizing you too much.","th":"people","lv":"B2","nw":1,"reg":"informal"},{"e":"down in the dumps","d":"sad and without energy, often for no special reason","x":"Gabriel has been [[down in the dumps]] since his best friend moved to Canada.","es":"bajoneado; con la depre","o":"Informal and light: it describes a low mood, not serious depression.","th":"feelings","lv":"B2","nw":1,"reg":"informal"},{"e":"draw the line","d":"to decide that you will not accept something beyond a certain point","x":"I'll answer a quick question on Saturday, but I [[draw the line]] at Sunday meetings.","es":"poner un límite; hasta ahí no más","th":"risk","lv":"B2","src":["b2-w-routine"],"nw":0},{"e":"drive a hard bargain","d":"to negotiate firmly and insist on a good deal for yourself","x":"Our new client [[drives a hard bargain]]. He questioned every single number.","es":"ser duro para negociar; no regalar nada","th":"money","lv":"B2","src":["b2-negotiation"],"nw":0},{"e":"drive someone up the wall","d":"to annoy someone very much","x":"That hold music [[drives me up the wall]].","es":"sacar de quicio; tener chato a alguien","th":"feelings","lv":"B2","src":["b2-w-chatbots4"],"nw":0},{"e":"eat your words","d":"to admit that something you said was wrong","x":"She said I'd never finish the marathon, but she had to [[eat her words]].","es":"tragarse sus palabras","o":"Often “make someone eat their words”: to prove them wrong, usually with some satisfaction.","th":"food","lv":"B2","nw":1},{"e":"err on the side of caution","d":"to be extra careful instead of taking a risk","x":"Let's [[err on the side of caution]] and order a little less stock this time.","es":"pecar de prudente; más vale prevenir que curar","th":"risk","lv":"B2","src":["c2-trust6","b2-w-future","c1-w-rules","c1-w-risk5"],"nw":0},{"e":"every cloud has a silver lining","d":"something good can come out of every bad situation","x":"Losing that client hurt, but it pushed us to find better ones. [[Every cloud has a silver lining]].","es":"no hay mal que por bien no venga","o":"Often shortened: “The silver lining is that I have more time for my family.”","th":"weather","lv":"B2","nw":1},{"e":"face the music","d":"to accept the consequences of your actions","x":"He broke the rules, and now he has to [[face the music]].","es":"dar la cara; asumir las consecuencias","th":"trouble","lv":"B2","src":["b2-music"],"nw":0},{"e":"fall off the wagon","d":"to start doing a bad habit again after stopping for a while (informal)","x":"I hadn't smoked in six months, but I [[fell off the wagon]] at my cousin's wedding.","es":"recaer; volver a las andadas","th":"trouble","lv":"B2","src":["b2-willpower4"],"nw":0},{"e":"fall short (of something)","d":"fail to reach a goal, a standard or an expected amount","x":"Sales were good this quarter, but they still [[fell short of]] our target by about ten percent.","es":"quedarse corto / no alcanzar la meta","o":"Neutral and very common in business and news: \"fall short of expectations.\" Also \"come up short.\"","th":"success","lv":"B2","nw":1},{"e":"fifteen minutes of fame","d":"a short period when an ordinary person is famous","x":"After his funny interview went viral, he enjoyed his [[fifteen minutes of fame]].","es":"sus quince minutos de fama; fama pasajera","th":"time","lv":"B2","src":["b2-fame4"],"nw":0},{"e":"find your feet","d":"to become confident and independent in a new situation","x":"Give yourself a few months to [[find your feet]] in a new country.","es":"adaptarse; encontrar tu lugar","th":"body","lv":"B2","src":["b2-abroad4"],"nw":0},{"e":"fly off the handle","d":"to suddenly become very angry, often for a small reason","x":"There's no need to [[fly off the handle]] — it was just a small mistake.","es":"perder los estribos; salirse de sus casillas","o":"Informal. It stresses that the anger is sudden and too strong for the situation.","th":"feelings","lv":"B2","nw":1,"reg":"informal"},{"e":"food for thought","d":"an idea that makes you think seriously about something","x":"Your comments about my presentation gave me a lot of [[food for thought]].","es":"algo para reflexionar; dar que pensar","th":"food","lv":"B2","src":["b2-feedback4"],"nw":0},{"e":"for the time being","d":"for now; until the situation changes","x":"[[For the time being]], I'm working from home while they finish the new office.","es":"por ahora; por el momento","o":"Suggests the situation is temporary. A little more formal than “for now.”","th":"time","lv":"B2","nw":1},{"e":"get a foot in the door","d":"to get a first small opportunity that can lead to something bigger","x":"The free pilot helped us [[get a foot in the door]] with a big mining client.","es":"poner un pie adentro; dar el primer paso","th":"body","lv":"B2","src":["b2-w-subscription4"],"nw":0},{"e":"get along like a house on fire","d":"like each other a lot and become friends very quickly","x":"I was nervous about my sister meeting my new roommate, but they [[got along like a house on fire]].","es":"llevarse de maravilla / hacer buenas migas","o":"Informal and very positive. Often used about people who have just met: neighbors, in-laws, new coworkers.","th":"people","lv":"B2","nw":1,"reg":"informal","uk":"UK: get on like a house on fire"},{"e":"get out of hand","d":"to become difficult or impossible to control","x":"The comments under our post [[got out of hand]], so we turned them off.","es":"írsele de las manos a alguien; salirse de control","o":"Used for situations, costs, parties, arguments or behavior that become worse than expected.","th":"body","lv":"B2","nw":1},{"e":"get something off the ground","d":"to make a project or business start successfully","x":"It took us two years to [[get the app off the ground]].","es":"echar a andar algo; sacar adelante un proyecto","th":"success","lv":"B2","src":["b2-startups4"],"nw":0},{"e":"get something off your chest","d":"to tell someone about a worry or problem so that you feel better","x":"Thanks for listening — I really needed to [[get that off my chest]].","es":"desahogarse; sacarse un peso de encima","o":"Used when you finally share something that has been bothering you, like a complaint, a fear or a confession.","th":"body","lv":"B2","nw":1},{"e":"get the gist","d":"to understand the general meaning without every detail","x":"I didn't understand every word, but I [[got the gist]] of the presentation.","es":"captar la idea general; cachar de qué se trata","th":"talk","lv":"B2","src":["b2-w-report"],"nw":0},{"e":"get the word out","d":"to tell a lot of people about something","x":"We used social media to [[get the word out]] about the launch.","es":"correr la voz; difundir","th":"talk","lv":"B2","src":["b2-w-trips"],"nw":0},{"e":"get to the heart of (something)","d":"to find the most important part or the real cause of something","x":"After an hour of questions, we finally [[got to the heart of]] the problem.","es":"llegar al fondo del asunto; dar con el meollo","th":"body","lv":"B2","src":["b2-w-questions4"],"nw":0},{"e":"get up to speed","d":"to get all the knowledge you need to do something well, quickly","x":"Can you help the new analyst [[get up to speed]] on the project?","es":"ponerse al día; empaparse del tema","th":"success","lv":"B2","src":["b2-w-skills"],"nw":0},{"e":"get your tongue around","d":"to manage to pronounce a difficult word","x":"I still can't [[get my tongue around]] \"Worcestershire\".","es":"lograr pronunciar algo; trabarse la lengua","th":"body","lv":"B2","src":["b2-languages4","c1-langculture5"],"nw":0},{"e":"ghost someone","d":"to suddenly stop answering someone's messages with no explanation (informal)","x":"We went on three dates, and then he just [[ghosted me]].","es":"hacer ghosting; desaparecer sin dar explicaciones","th":"people","lv":"B2","src":["b2-relationships"],"nw":0},{"e":"give credit where credit is due","d":"to praise the people who really deserve it","x":"I have to [[give credit where credit is due]]: Ana's idea saved the project.","es":"reconocer el mérito a quien corresponde","th":"success","lv":"B2","src":["b2-w-achieve"],"nw":0},{"e":"give someone a heads-up","d":"to warn someone early about something that is going to happen","x":"Just [[a heads-up]]: the auditors are coming on Monday.","es":"avisar con tiempo; dar un aviso","th":"body","lv":"B2","src":["b2-w-now"],"nw":0},{"e":"give someone a piece of your mind","d":"tell someone angrily and directly that you disapprove of what they did","x":"If the neighbors play loud music at 3 a.m. again, I'm going to [[give them a piece of my mind]].","es":"cantarle las cuarenta a alguien / decirle unas cuantas verdades","o":"The speaker is angry. Often used as a plan or threat: \"I'm going to give him a piece of my mind.\"","th":"talk","lv":"B2","nw":1,"reg":"informal"},{"e":"give someone the benefit of the doubt","d":"to believe someone's explanation even though you can't be sure it's true","x":"He says the traffic was terrible, so let's [[give him the benefit of the doubt]].","es":"dar el beneficio de la duda","th":"people","lv":"B2","src":["c1-relationships","b2-w-trust4","c2-w-calls","c2-w-trustasset6"],"nw":0},{"e":"give someone the cold shoulder","d":"to ignore someone on purpose or treat them in an unfriendly way","x":"After I forgot her birthday, my sister [[gave me the cold shoulder]] for a whole week.","es":"aplicarle la ley del hielo a alguien","o":"Describes silent, deliberate coldness rather than open anger. Also: “get the cold shoulder.”","th":"body","lv":"B2","nw":1},{"e":"glued to the screen","d":"watching or playing something without stopping","x":"The kids were [[glued to the screen]] all afternoon.","es":"pegado a la pantalla","th":"talk","lv":"B2","src":["b2-gaming4"],"nw":0},{"e":"go around in circles","d":"to keep doing or discussing the same thing without making any progress","x":"We [[went around in circles]] for an hour and decided nothing.","es":"dar vueltas y vueltas sin llegar a nada","th":"travel","lv":"B2","src":["c2-curious","b2-w-chatbots4"],"nw":0},{"e":"go behind someone's back","d":"to do something secretly without telling a person who should know about it","x":"I can't believe my coworker [[went behind my back]] and complained to our manager.","es":"hacer algo a espaldas de alguien","o":"A strong complaint: it suggests disloyalty or dishonesty, often by a friend, partner or colleague.","th":"body","lv":"B2","nw":1},{"e":"go cold turkey","d":"to stop a habit suddenly and completely, not little by little","x":"He didn't cut down slowly. He [[went cold turkey]] and stopped drinking coffee overnight.","es":"dejarlo de golpe; cortar por lo sano","th":"food","lv":"B2","src":["b2-willpower4"],"nw":0},{"e":"go Dutch","d":"to share the cost of a meal or outing so that each person pays for themselves","x":"On our first date, we [[went Dutch]] — it felt fair to both of us.","es":"pagar a la americana; cada uno paga lo suyo","o":"Common for meals and dates between friends or couples.","th":"money","lv":"B2","nw":1},{"e":"go for it","d":"to try something with confidence","x":"If you really want that job, [[go for it]]!","es":"¡dale!; tirarse a la piscina","th":"risk","lv":"B2","src":["b2-plans"],"nw":0},{"e":"go haywire","d":"suddenly stop working properly or go out of control","x":"My laptop [[went haywire]] five minutes before the presentation, and I had to borrow one.","es":"volverse loco (un aparato) / descontrolarse","o":"Common with machines, computers and systems, but also with plans: \"Everything went haywire when the bus broke down.\"","th":"trouble","lv":"B2","nw":1,"reg":"informal"},{"e":"go in one ear and out the other","d":"to be heard but immediately forgotten or ignored","x":"I explained the new process three times, but it [[went in one ear and out the other]].","es":"entrar por un oído y salir por el otro","th":"body","lv":"B2","src":["b2-w-listening4"],"nw":0},{"e":"go off on a tangent","d":"to suddenly start talking about something unrelated to the topic","x":"Our boss often [[goes off on a tangent]] about his dog.","es":"irse por las ramas","th":"talk","lv":"B2","src":["b2-meetings"],"nw":0},{"e":"go off the rails","d":"start to go badly wrong or behave in an uncontrolled way","x":"The project [[went off the rails]] when the two main developers quit in the same month.","es":"descarrilarse / irse a la deriva","o":"The image is a train leaving its tracks. Used for plans and projects, and for people who start behaving badly.","th":"travel","lv":"B2","nw":1},{"e":"go places","d":"be likely to become very successful in the future","x":"Our new intern is smart, hardworking and great with clients. She's really [[going places]].","es":"llegar lejos / tener un gran futuro","o":"Usually in the continuous form: \"He's going places.\" A compliment, often about young people starting their careers.","th":"success","lv":"B2","nw":1,"reg":"informal"},{"e":"go to your head","d":"to make you think you're more important than other people","x":"He became rich at 19, but he never let success [[go to his head]].","es":"subírsele a la cabeza; subírsele los humos","th":"body","lv":"B2","src":["b2-fame4"],"nw":0},{"e":"go way back","d":"have known each other for a very long time","x":"Sandra and I [[go way back]] — we started at the company on the same day in 2009.","es":"conocerse de toda la vida / ser amigos de años","o":"Usually in the present simple with \"we\" or \"they\": \"We go way back.\" It suggests trust and a long friendship.","th":"people","lv":"B2","nw":1,"reg":"informal"},{"e":"have a green thumb","d":"to be very good at growing plants","x":"My dad [[has a green thumb]] — his tomatoes are the best on our street.","es":"tener buena mano para las plantas","o":"American English. Often in the negative: “I don't have a green thumb.”","th":"colors","lv":"B2","nw":1,"uk":"UK: have green fingers"},{"e":"have butterflies (in your stomach)","d":"to feel nervous and excited before something important","x":"I always [[have butterflies]] before I speak in front of the board.","es":"tener mariposas en el estómago; estar con los nervios de punta","th":"animals","lv":"B2","src":["b2-w-present"],"nw":0},{"e":"have friends in high places","d":"know important or powerful people who can help you","x":"He got the permit in two days, while we waited six months. He must [[have friends in high places]].","es":"tener contactos (o \"pitutos\")","o":"Often a little critical, suggesting someone got help others didn't. Also used jokingly: \"I have friends in high places.\"","th":"people","lv":"B2","nw":1},{"e":"have second thoughts","d":"begin to doubt a decision you have already made","x":"I'm [[having second thoughts]] about buying the apartment — the monthly payments are really high.","es":"tener dudas / estar arrepintiéndose","o":"Often with \"about.\" Compare \"on second thought,\" used when you change your mind while speaking (UK: on second thoughts).","th":"risk","lv":"B2","nw":1},{"e":"have someone's back","d":"to be ready to support and defend someone","x":"Don't worry about the meeting with the director. [[I've got your back]].","es":"cubrirle las espaldas a alguien; ¡cuenta conmigo!","th":"body","lv":"B2","src":["b2-w-trust4"],"nw":0},{"e":"hit below the belt","d":"say or do something unfair and hurtful, especially about someone's weak point","x":"When the argument got heated, she [[hit below the belt]] and brought up his failed business.","es":"dar un golpe bajo","o":"From boxing, where hitting below the belt is against the rules. People also say \"That was below the belt.\"","th":"sport","lv":"B2","nw":1},{"e":"hit the road","d":"to start a journey; to leave","x":"It's getting late — let's [[hit the road]]!","es":"ponerse en camino; partir","th":"travel","lv":"B2","src":["b2-travel"],"nw":0},{"e":"hold all the cards","d":"have all the power or advantages in a situation","x":"They're the only supplier in the region, so they [[hold all the cards]] in the price negotiations.","es":"tener la sartén por el mango","o":"From card games. Common in business and negotiations, about the stronger side: \"The landlord holds all the cards.\"","th":"sport","lv":"B2","nw":1},{"e":"in hot water","d":"in trouble because of something you did","x":"I'll be [[in hot water]] with my wife if I forget our anniversary again.","es":"estar en problemas / meterse en un lío","o":"Often \"get into hot water\" or \"be in hot water with someone\": your boss, your partner, the authorities.","th":"trouble","lv":"B2","nw":1},{"e":"in stitches","d":"laughing a lot","x":"His story had us all [[in stitches]].","es":"morirse de la risa; tentarse de la risa","th":"feelings","lv":"B2","src":["b2-humor"],"nw":0},{"e":"in the long run","d":"eventually; after a long time","x":"Learning English will pay off [[in the long run]].","es":"a la larga; a largo plazo","th":"time","lv":"B2","src":["b2-plans"],"nw":0},{"e":"in the nick of time","d":"just before it was too late","x":"We sent the proposal [[in the nick of time]], two minutes before the deadline.","es":"justo a tiempo; en el último minuto","th":"time","lv":"B2","src":["b2-time4"],"nw":0},{"e":"in the red","d":"owing money, or spending more money than you earn","x":"After the expensive renovation, our bank account was [[in the red]] for months.","es":"en números rojos","o":"The opposite is “in the black” (making a profit). It comes from writing losses in red ink.","th":"colors","lv":"B2","nw":1},{"e":"in the same boat","d":"in the same difficult situation as other people","x":"If you're struggling with the new software, don't worry — we're all [[in the same boat]].","es":"estar todos en la misma / estar en el mismo barco","o":"Usually \"We're all in the same boat.\" Used to comfort people: they are not alone with the problem.","th":"travel","lv":"B2","nw":1},{"e":"iron out the kinks","d":"solve the small problems in a new plan, product or system","x":"The new booking app still crashes sometimes, but the developers are [[ironing out the kinks]].","es":"pulir los detalles / corregir las fallas","o":"Common at work, especially with new technology and processes. Also \"work out the kinks\" and \"iron out the problems.\"","th":"trouble","lv":"B2","nw":1},{"e":"itchy feet","d":"a strong desire to travel","x":"After a month at home, I get [[itchy feet]].","es":"tener ganas de viajar; ser patiperro","th":"body","lv":"B2","src":["b2-travel"],"nw":0},{"e":"jump ship","d":"to leave a job or an organization suddenly, often to join another one","x":"Two of our best salespeople [[jumped ship]] to a competitor.","es":"abandonar el barco; irse a la competencia","th":"travel","lv":"B2","src":["b2-w-turnover4","c2-w-loyalty6"],"nw":0},{"e":"jump through hoops","d":"to have to do a lot of difficult or annoying things to get something","x":"Customers had to [[jump through hoops]] to get a simple refund.","es":"pasar por mil trámites; sortear un montón de obstáculos","th":"trouble","lv":"B2","src":["b2-w-process"],"nw":0},{"e":"keep (something) in the family","d":"to keep something, like a company, a job or a problem, among relatives only","x":"The founders want to [[keep the company in the family]] for at least one more generation.","es":"que quede en familia","th":"people","lv":"B2","src":["b2-w-family4"],"nw":0},{"e":"keep your fingers crossed","d":"to hope that something will happen the way you want","x":"I have my final interview tomorrow. [[Keep your fingers crossed]] for me!","es":"cruzar los dedos","th":"body","lv":"B2","src":["b2-luck4"],"nw":0},{"e":"keep your head above water","d":"to just manage to survive a difficult situation, especially when you have money problems","x":"Since our café lost half its customers, we've barely been [[keeping our heads above water]].","es":"mantenerse a flote","o":"Very often about money and debt, but also about having too much work.","th":"body","lv":"B2","nw":1},{"e":"knock on wood","d":"something you say after mentioning your good luck, so that it doesn't change","x":"I've never lost my luggage on a flight, [[knock on wood]].","es":"toco madera","th":"risk","lv":"B2","src":["b2-luck4"],"nw":0},{"e":"laugh your head off","d":"to laugh very loudly and a lot","x":"We [[laughed our heads off]] at the comedy show.","es":"morirse de la risa; reírse a carcajadas","th":"body","lv":"B2","src":["b2-humor"],"nw":0},{"e":"leave money on the table","d":"to get a worse deal than you could have gotten","x":"If you accept the first offer, you might be [[leaving money on the table]].","es":"dejar plata sobre la mesa; perder la oportunidad de ganar más","th":"money","lv":"B2","src":["b2-negotiation","c1-w-inflation5","c2-w-behavioral6"],"nw":0},{"e":"less is more","d":"something simple, or a smaller amount, is often more effective","x":"When it comes to hashtags, [[less is more]].","es":"menos es más","th":"success","lv":"B2","src":["c1-minimalism5","b2-w-socialmkt4"],"nw":0},{"e":"lose track of time","d":"to not notice how much time has passed","x":"When I'm playing, I completely [[lose track of time]].","es":"perder la noción del tiempo","th":"time","lv":"B2","src":["b2-gaming4"],"nw":0},{"e":"lost in translation","d":"when meaning, humor or feeling disappears in another language","x":"Puns often get [[lost in translation]], so the joke isn't funny in English.","es":"perderse en la traducción","th":"talk","lv":"B2","src":["b2-languages4","c1-langculture5","c2-travel","c2-softpower6","c2-w-email"],"nw":0},{"e":"low-hanging fruit","d":"easy improvements that you can make quickly","x":"Let's start with the [[low-hanging fruit]], like removing duplicate forms.","es":"lo más fácil de lograr; las victorias rápidas","th":"food","lv":"B2","src":["b2-w-process","c1-w-stock","c1-w-circular5"],"nw":0},{"e":"make it big","d":"become very successful, rich or famous","x":"She left her small town at nineteen, determined to [[make it big]] as a fashion designer in New York.","es":"triunfar / llegar lejos","o":"Common with careers in music, sports, business and entertainment: \"make it big in Hollywood.\"","th":"success","lv":"B2","nw":1,"reg":"informal"},{"e":"make the grade","d":"be good enough to reach the required standard","x":"Hundreds of people apply for the program every year, but only a few [[make the grade]].","es":"dar la talla / estar a la altura","o":"Often negative: \"He didn't make the grade.\" Common with jobs, sports teams, schools and products.","th":"success","lv":"B2","nw":1},{"e":"make up for lost time","d":"to do a lot of something because you could not do it earlier","x":"After years of working abroad, she's [[making up for lost time]] with her grandchildren.","es":"recuperar el tiempo perdido","o":"Spanish has the same expression. Often about family, travel or hobbies after a busy or difficult period.","th":"time","lv":"B2","nw":1},{"e":"miss the boat","d":"lose a chance because you acted too slowly","x":"Tickets sold out in ten minutes. If you didn't buy them right away, you [[missed the boat]].","es":"perder el tren / dejar pasar la oportunidad","o":"Used for opportunities that are now gone: deals, jobs, investments, tickets. Neutral to informal.","th":"travel","lv":"B2","nw":1},{"e":"more trouble than it's worth","d":"causing more problems or effort than the benefits it brings","x":"We tried to fix the old dishwasher ourselves, but it was [[more trouble than it was worth]].","es":"sale más caro el remedio que la enfermedad / no vale la pena","o":"Used for objects, tasks and sometimes people. Informal variant: \"more hassle than it's worth.\"","th":"trouble","lv":"B2","nw":1},{"e":"move the goalposts","d":"to change the rules or targets after work has started","x":"Every time we finish the report, the client [[moves the goalposts]] and asks for something new.","es":"cambiar las reglas del juego a mitad de camino","th":"sport","lv":"B2","src":["c1-fairplay5","c2-ambition6","b2-w-pushback4","c1-w-now","c2-w-investors6"],"nw":0},{"e":"move the needle","d":"to make a noticeable difference to results","x":"The new ads look great, but they haven't [[moved the needle]] on sales.","es":"marcar la diferencia; mover la aguja","th":"success","lv":"B2","src":["c2-media","b2-w-jargon4","c1-w-achieve"],"nw":0},{"e":"no news is good news","d":"if you hear nothing, it probably means there are no problems","x":"The supplier hasn't called back, but [[no news is good news]], I guess.","es":"si no hay noticias, son buenas noticias","th":"talk","lv":"B2","src":["b2-w-now"],"nw":0},{"e":"not out of the woods (yet)","d":"still not completely safe from a difficult or dangerous situation","x":"Sales are better this month, but the company is [[not out of the woods yet]].","es":"todavía no estar fuera de peligro","o":"Usually with “yet.” Common in news about the economy, health and companies in trouble.","th":"weather","lv":"B2","nw":1},{"e":"nothing ventured, nothing gained","d":"you can't get anything good if you don't take a chance","x":"The job probably needs more experience than I have, but [[nothing ventured, nothing gained]] — I'll apply anyway.","es":"el que no arriesga no gana","o":"A proverb often used in conversation to encourage yourself or others to try something uncertain.","th":"risk","lv":"B2","nw":1},{"e":"off the record","d":"said unofficially and not meant to be published or repeated","x":"[[Off the record]], the director told me the project is three months behind schedule.","es":"extraoficialmente / entre nos","o":"Common in journalism and at work. The opposite, \"on the record,\" means officially and publicly.","th":"talk","lv":"B2","nw":1},{"e":"off the top of your head","d":"without checking the facts or thinking about it carefully","x":"[[Off the top of my head]], I'd say the repairs will cost about two thousand dollars.","es":"así, de memoria; a ojo","o":"Useful at work when you give a quick answer or estimate and want to show it may not be exact.","th":"body","lv":"B2","nw":1},{"e":"old habits die hard","d":"it's very difficult to stop doing something you've done for a long time","x":"I've worked from home for years, but I still wake up at six. [[Old habits die hard]]!","es":"cuesta quitarse las mañas; la costumbre es más fuerte","th":"people","lv":"B2","src":["b2-willpower4","c2-change6","b2-w-fintech4"],"nw":0},{"e":"on a roll","d":"having a series of successes, one after another","x":"Our team has closed three big deals this month — we're really [[on a roll]]!","es":"estar en racha / tener una buena racha","o":"Used when things keep going well, at work, in sports or in games: \"Don't stop now — you're on a roll!\"","th":"success","lv":"B2","nw":1,"reg":"informal"},{"e":"on a shoestring","d":"with very little money","x":"We started the business [[on a shoestring]], working from our kitchen table.","es":"con muy poca plata; con lo justo","o":"Often “on a shoestring budget.” It suggests making something work with very few resources.","th":"money","lv":"B2","nw":1},{"e":"on pins and needles","d":"very nervous or anxious while waiting for something","x":"I was [[on pins and needles]] all weekend, waiting to hear about the job.","es":"con el alma en un hilo; en ascuas","o":"American English. Typical when waiting for news: exam results, medical tests or a job offer.","th":"feelings","lv":"B2","nw":1,"uk":"UK: on tenterhooks"},{"e":"on the tip of my tongue","d":"when you know a word but can't remember it at that moment","x":"What's the name of that actor? It's [[on the tip of my tongue]]!","es":"tenerlo en la punta de la lengua","th":"body","lv":"B2","src":["b2-languages4"],"nw":0},{"e":"on thin ice","d":"in a risky situation where you could easily get into trouble","x":"You've been late three times this week, so you're [[on thin ice]] with your manager.","es":"estar en la cuerda floja","o":"Often “be on thin ice” or “skate on thin ice.” Typically used as a warning.","th":"weather","lv":"B2","nw":1},{"e":"once in a blue moon","d":"very rarely","x":"I watch horror movies [[once in a blue moon]].","es":"de uvas a peras; muy de vez en cuando","th":"colors","lv":"B2","src":["b2-curious"],"nw":0},{"e":"only a matter of time","d":"certain to happen soon, although nobody knows exactly when","x":"With so many mistakes in the report, it was [[only a matter of time]] before someone noticed.","es":"ser solo cuestión de tiempo","o":"Usually followed by “before” or “until”: “It's only a matter of time before prices go up.”","th":"time","lv":"B2","nw":1},{"e":"open a can of worms","d":"to start dealing with something that creates many new, complicated problems","x":"Comparing everyone's bonuses would [[open a can of worms]].","es":"abrir la caja de Pandora","th":"animals","lv":"B2","src":["c1-tech","c2-bioethics6","b2-w-paytransp4","c1-w-ip5","c2-w-problems"],"nw":0},{"e":"out of someone's league","d":"too good, attractive or expensive for someone","x":"Everyone told him she was [[out of his league]], but they've been married for twenty years.","es":"ser demasiado para alguien / estar fuera de su alcance","o":"Often about dating, but also about prices or abilities. A league is a group of teams at the same level.","th":"sport","lv":"B2","nw":1,"reg":"informal"},{"e":"out of this world","d":"extremely good or impressive","x":"The view of the Milky Way from the Elqui Valley was [[out of this world]].","es":"de otro mundo; espectacular","th":"success","lv":"B2","src":["b2-space4"],"nw":0},{"e":"packed like sardines","d":"very crowded, with almost no space to move","x":"There were forty of us in that small room, [[packed like sardines]].","es":"como sardinas en lata","th":"food","lv":"B2","src":["b2-w-space"],"nw":0},{"e":"pay lip service to","d":"to say you support something without doing anything to help it","x":"Many companies [[pay lip service to]] well-being but never reduce workloads.","es":"decir algo de la boca para afuera","th":"body","lv":"B2","src":["c1-environment","c2-csr6","b2-w-engage4"],"nw":0},{"e":"pay your dues","d":"to work hard in a junior position for a long time before you get a better one","x":"I [[paid my dues]] in the warehouse before I moved to the office.","es":"pagar el derecho de piso","th":"money","lv":"B2","src":["b2-w-genz4"],"nw":0},{"e":"pick someone's brain","d":"to ask someone who knows a lot for advice or information","x":"Can I [[pick your brain]] about the new tax rules? You know them better than anyone.","es":"pedirle consejo a alguien que sabe; consultarle a alguien","th":"body","lv":"B2","src":["b2-w-questions4"],"nw":0},{"e":"pick up the tab","d":"to pay the bill for something, often for other people","x":"Put your wallet away — the company is [[picking up the tab]] tonight.","es":"pagar la cuenta; invitar","o":"Mainly American. Used for restaurants and bars, and also for companies or governments paying costs.","th":"money","lv":"B2","nw":1,"uk":"UK also: pick up the bill"},{"e":"pie in the sky","d":"a plan or idea that sounds good but is very unlikely to happen","x":"A hotel on the moon by 2030? That sounds like [[pie in the sky]] to me.","es":"castillos en el aire; un sueño imposible","th":"food","lv":"B2","src":["b2-space4","c1-spacefuture5"],"nw":0},{"e":"play it by ear","d":"to decide what to do as things happen","x":"Let's not plan — we'll [[play it by ear]].","es":"improvisar sobre la marcha; ir viendo en el camino","th":"body","lv":"B2","src":["b2-music"],"nw":0},{"e":"play the blame game","d":"to argue about whose fault a problem is instead of solving it","x":"Let's not [[play the blame game]]. Let's find a solution.","es":"tirarse la pelota; echarse la culpa unos a otros","th":"sport","lv":"B2","src":["b2-w-past"],"nw":0},{"e":"play with fire","d":"do something dangerous that could cause you serious problems","x":"Ignoring tax deadlines is [[playing with fire]] — the fines can be huge.","es":"jugar con fuego","o":"A warning about risky behavior. Usually in the continuous form: \"You're playing with fire.\"","th":"risk","lv":"B2","nw":1},{"e":"point the finger at","d":"to say that someone is responsible for something bad","x":"When the project failed, everyone [[pointed the finger at]] the IT team.","es":"apuntar con el dedo; echarle la culpa a alguien","th":"body","lv":"B2","src":["b2-w-problems"],"nw":0},{"e":"pull yourself together","d":"to control your emotions and start acting calmly again","x":"I cried for ten minutes, then [[pulled myself together]] and went back to the meeting.","es":"recomponerse; calmarse","o":"As an order (“Pull yourself together!”) it can sound harsh, so be careful with someone who is upset.","th":"feelings","lv":"B2","nw":1},{"e":"push your luck","d":"to risk losing what you have by trying to get even more","x":"You already got Friday off. Don't [[push your luck]] by asking for Monday too.","es":"tentar a la suerte; abusar de la suerte","th":"risk","lv":"B2","src":["b2-luck4"],"nw":0},{"e":"put a pin in it","d":"to stop discussing something for now and return to it later","x":"Great question, but let's [[put a pin in it]] until next week.","es":"dejarlo en pausa; dejarlo para después","th":"talk","lv":"B2","src":["b2-meetings"],"nw":0},{"e":"put all your eggs in one basket","d":"to depend completely on one person, plan or supplier","x":"We work with three suppliers because we don't want to [[put all our eggs in one basket]].","es":"poner todos los huevos en la misma canasta; jugárselo todo a una carta","th":"food","lv":"B2","src":["c1-globalization5","b2-w-stock","c1-w-risk5","c2-w-decisions"],"nw":0},{"e":"put someone on the spot","d":"to ask someone a difficult question unexpectedly, so they feel uncomfortable","x":"Sorry to [[put you on the spot]], but could you give us a quick update?","es":"poner a alguien en aprietos; pillar desprevenido a alguien","th":"talk","lv":"B2","src":["b2-w-calls","c1-w-toughq5"],"nw":0},{"e":"put something to the test","d":"to find out if something is true or works by trying it","x":"Everyone says this app helps you sleep, so I'm going to [[put it to the test]].","es":"poner a prueba","th":"success","lv":"B2","src":["b2-science4"],"nw":0},{"e":"put words in someone's mouth","d":"to say that someone said or meant something that they didn't","x":"Please don't [[put words in my mouth]]. I never said the plan was bad.","es":"poner palabras en boca de alguien","th":"body","lv":"B2","src":["b2-w-report","c1-w-media5"],"nw":0},{"e":"put your money where your mouth is","d":"to show with actions, especially by paying, that you really mean what you say","x":"Everyone says they want local products, but will they [[put their money where their mouth is]]?","es":"pasar de las palabras a los hechos; demostrarlo con hechos","th":"money","lv":"B2","src":["c2-csr6","b2-w-research4"],"nw":0},{"e":"put yourself in someone's shoes","d":"to imagine how you would feel in another person's situation","x":"[[Put yourself in the customer's shoes]]. Would you wait 40 minutes on hold?","es":"ponerse en el lugar del otro; ponerse en los zapatos de alguien","th":"people","lv":"B2","src":["b2-w-listening4","c1-w-skills"],"nw":0},{"e":"quiet quitting","d":"doing only the minimum your job requires, with no extra effort or enthusiasm","x":"[[Quiet quitting]] is often a sign of burnout, not laziness.","es":"renuncia silenciosa; hacer lo justo y necesario en la pega","th":"money","lv":"B2","src":["b2-w-engage4"],"nw":0},{"e":"read the room","d":"to understand how the people in a group are feeling","x":"He didn't [[read the room]] and told a joke right after the bad news.","es":"leer el ambiente; cachar el ambiente","th":"people","lv":"B2","src":["c1-meetings","c1-presentations","c1-workplace","b2-w-calls","c1-w-voice5","c2-w-rules"],"nw":0},{"e":"rise to the occasion","d":"do well in a difficult situation, especially when it really matters","x":"Nobody expected much from the young lawyer, but she [[rose to the occasion]] and won the case.","es":"estar a la altura (de las circunstancias)","o":"Positive. Used when someone performs better than expected under pressure: a big game, a crisis, an important presentation.","th":"success","lv":"B2","nw":1},{"e":"rub someone the wrong way","d":"to annoy someone, often without meaning to","x":"His jokes in meetings [[rub some clients the wrong way]].","es":"caerle mal a alguien; caer pesado","th":"people","lv":"B2","src":["c1-etiquette5","b2-w-global4"],"nw":0},{"e":"rule with an iron fist","d":"to control people in a very strict, severe way","x":"The old manager [[ruled with an iron fist]]. Nobody dared to disagree with him.","es":"gobernar con mano de hierro; tener mano dura","th":"body","lv":"B2","src":["b2-leadership4"],"nw":0},{"e":"run in the family","d":"to be a quality or talent that many people in a family have","x":"Good cooking [[runs in the family]]. My mom and my grandma are both amazing cooks.","es":"venir de familia; traerlo en la sangre","th":"people","lv":"B2","src":["b2-food","c2-naturenurture6"],"nw":0},{"e":"run out of steam","d":"lose energy or enthusiasm and slow down or stop","x":"I start every diet full of enthusiasm, but I usually [[run out of steam]] after two weeks.","es":"quedarse sin energía / desinflarse","o":"The image is a steam engine losing power. Used for people, projects, campaigns and even the economy.","th":"travel","lv":"B2","nw":1},{"e":"run something by someone","d":"tell someone about an idea or plan to get their opinion","x":"Before we send the proposal to the client, let me [[run it by]] my boss.","es":"consultarle algo a alguien / comentárselo a alguien","o":"Very common at work. Also \"run something past someone.\" Usually with \"it\": \"Let me run it by Ana first.\"","th":"talk","lv":"B2","nw":1},{"e":"saved by the bell","d":"rescued from a difficult situation at the last moment","x":"My boss was about to ask about the unfinished report when her phone rang. [[Saved by the bell]]!","es":"salvado por la campana","o":"From boxing, where the bell ends a round. Usually said as a short, funny exclamation.","th":"sport","lv":"B2","nw":1},{"e":"scratch the surface","d":"to deal with only a small, basic part of a subject","x":"Our survey only [[scratched the surface]]. We need to interview the clients.","es":"quedarse en la superficie; apenas rozar el tema","th":"trouble","lv":"B2","src":["b2-w-questions4"],"nw":0},{"e":"see red","d":"to suddenly become very angry","x":"When the driver cut in front of me and laughed, I just [[saw red]].","es":"ponerse rojo de rabia; echar chispas","o":"Describes a sudden, strong anger that makes it hard to think clearly.","th":"colors","lv":"B2","nw":1},{"e":"sell yourself short","d":"to present yourself or your work as less valuable than it really is","x":"Don't [[sell yourself short]] in the interview. You've managed huge projects.","es":"subestimarse; no valorarse lo suficiente","th":"money","lv":"B2","src":["b2-w-pricing4","c1-w-intro"],"nw":0},{"e":"short and sweet","d":"brief and pleasant, without any unnecessary parts","x":"Let's keep today's meeting [[short and sweet]]: fifteen minutes, maximum.","es":"breve y al grano; lo bueno, si breve, dos veces bueno","th":"talk","lv":"B2","src":["b2-w-calls"],"nw":0},{"e":"show your true colors","d":"to reveal what you are really like, especially when it is something bad","x":"He seemed so friendly, but he [[showed his true colors]] when the deal went wrong.","es":"mostrar la hilacha; mostrar su verdadera cara","o":"Usually negative. “Colors” here means a ship's flag; ships sometimes flew false flags to trick enemies.","th":"colors","lv":"B2","nw":1,"uk":"UK spelling: show your true colours"},{"e":"smoke and mirrors","d":"tricks that make something look better than it really is","x":"The company's \"green\" report was all [[smoke and mirrors]]. The numbers didn't add up.","es":"pura fachada; puro cuento","th":"trouble","lv":"B2","src":["b2-w-greenbiz4"],"nw":0},{"e":"sound like a broken record","d":"keep repeating the same thing so often that it becomes annoying","x":"I know I [[sound like a broken record]], but please lock the door when you leave.","es":"parecer disco rayado","o":"Often used about yourself, as a small apology before repeating advice or a request.","th":"talk","lv":"B2","nw":1},{"e":"sour grapes","d":"pretending you don't want something only because you can't have it","x":"He says he never wanted the promotion anyway, but that's just [[sour grapes]].","es":"“están verdes”, como dijo la zorra","o":"From Aesop's fable of the fox that can't reach some grapes and decides they must be sour.","th":"food","lv":"B2","nw":1},{"e":"speak your mind","d":"say honestly what you think, even if others may not like it","x":"Our manager wants everyone to [[speak their minds]] in meetings, even when they disagree with her.","es":"decir lo que uno piensa / hablar con franqueza","o":"Usually positive: a person who speaks their mind is honest and direct. Sometimes it suggests being a little too blunt.","th":"talk","lv":"B2","nw":1},{"e":"stand out from the crowd","d":"to be noticeably different from or better than others","x":"With so many coffee shops in Providencia, you need something special to [[stand out from the crowd]].","es":"destacar entre los demás; sobresalir","th":"success","lv":"B2","src":["b2-ads4"],"nw":0},{"e":"steal someone's thunder","d":"to take attention or praise away from someone, often by doing what they planned first","x":"I was going to announce my engagement, but my brother [[stole my thunder]] with his baby news.","es":"robarle el protagonismo a alguien","o":"Said to come from an 18th-century playwright who heard his new stage-thunder effect used in someone else's play.","th":"weather","lv":"B2","nw":1},{"e":"step on someone's toes","d":"to upset someone by getting involved in their work or responsibilities","x":"I don't want to [[step on anyone's toes]], but I have a few ideas for your project.","es":"meterse en el terreno de otro; pasar a llevar a alguien","th":"body","lv":"B2","src":["b2-workplace","b2-w-role"],"nw":0},{"e":"step up to the plate","d":"take responsibility and act when something needs to be done","x":"When our manager got sick, Lucía [[stepped up to the plate]] and led the whole project.","es":"dar un paso al frente / hacerse cargo","o":"From baseball, where the batter steps up to home plate. Very common at work and in American news.","th":"sport","lv":"B2","nw":1},{"e":"stick to your guns","d":"to refuse to change your decision even when people put pressure on you","x":"The client pushed for a lower price, but our sales director [[stuck to her guns]].","es":"mantenerse firme; no dar el brazo a torcer","th":"risk","lv":"B2","src":["b2-w-pushback4"],"nw":0},{"e":"strapped for cash","d":"having very little money available at the moment (informal)","x":"Can you pay this time? I'm a bit [[strapped for cash]] until payday.","es":"andar corto de plata; estar pato","th":"money","lv":"B2","src":["b2-cashless4"],"nw":0},{"e":"strike a chord","d":"to cause an emotional reaction","x":"The lyrics really [[struck a chord]] with me.","es":"tocar la fibra sensible","th":"feelings","lv":"B2","src":["b2-music","c2-music","c2-literature6"],"nw":0},{"e":"strike while the iron is hot","d":"to act quickly while you have a good opportunity","x":"Call the buyers you met tomorrow. [[Strike while the iron is hot]]!","es":"aprovechar la volada; aprovechar el momento","th":"time","lv":"B2","src":["b2-w-trips"],"nw":0},{"e":"sugarcoat","d":"to make bad news sound better than it really is","x":"Don't [[sugarcoat]] it. Just tell me if the project failed.","es":"dorar la píldora; endulzar las cosas","th":"food","lv":"B2","src":["b2-feedback4"],"nw":0},{"e":"take a hit","d":"to be badly affected and lose money or value","x":"Tourism [[took a hit]] when the airport closed for repairs.","es":"verse golpeado; sufrir un golpe","th":"money","lv":"B2","src":["b2-w-trends"],"nw":0},{"e":"take someone under your wing","d":"to protect, help and teach someone who is younger or has less experience","x":"When I joined the project, an older biologist [[took me under her wing]].","es":"tomar a alguien bajo el ala; apadrinar a alguien","th":"animals","lv":"B2","src":["b2-conservation4","c1-mentoring5"],"nw":0},{"e":"take something at face value","d":"to accept something as it appears, without questioning it","x":"Don't [[take online reviews at face value]]. Some of them are fake.","es":"creerse algo sin cuestionarlo; tomar algo al pie de la letra","th":"money","lv":"B2","src":["b2-media"],"nw":0},{"e":"take the bull by the horns","d":"to deal with a difficult situation directly and with courage","x":"Instead of waiting for the problem to disappear, Laura [[took the bull by the horns]] and called the client.","es":"tomar el toro por las astas","o":"Spanish uses the same image. It praises acting bravely instead of avoiding a problem.","th":"animals","lv":"B2","nw":1},{"e":"talk past each other","d":"to discuss something without really understanding what the other person means","x":"We [[talked past each other]] for weeks until we compared our notes.","es":"un diálogo de sordos; no entenderse","th":"talk","lv":"B2","src":["b2-w-global4"],"nw":0},{"e":"the ball is in your court","d":"it's your turn to act or make a decision","x":"We've sent our best offer, so [[the ball is in their court]] now.","es":"la pelota está en tu cancha","th":"sport","lv":"B2","src":["b2-negotiation"],"nw":0},{"e":"the buck stops with (someone)","d":"a particular person has the final responsibility","x":"I'm the project manager, so [[the buck stops with me]].","es":"la responsabilidad final es mía; yo me hago cargo","th":"risk","lv":"B2","src":["b2-w-decisions","c2-w-role"],"nw":0},{"e":"the butt of the joke","d":"the person everyone is laughing at","x":"I don't mind teasing, but I'm tired of always being [[the butt of the joke]].","es":"el blanco de las bromas; el hazmerreír","th":"people","lv":"B2","src":["b2-humor"],"nw":0},{"e":"the calm before the storm","d":"a quiet, peaceful period just before a time of great activity or trouble","x":"The office is quiet this week, but it's just [[the calm before the storm]] — tax season starts Monday.","es":"la calma antes de la tormenta","o":"Spanish uses the same image. Common before busy seasons at work, big events or an expected conflict.","th":"weather","lv":"B2","nw":1},{"e":"the cream of the crop","d":"the very best people or things in a group","x":"Our graduate program attracts [[the cream of the crop]] from local universities.","es":"la flor y nata; lo mejor de lo mejor","th":"food","lv":"B2","src":["b2-w-hiring4"],"nw":0},{"e":"the devil is in the details","d":"small details are often where problems and mistakes appear","x":"The plan looks simple, but [[the devil is in the details]].","es":"el diablo está en los detalles","th":"trouble","lv":"B2","src":["b2-w-details","c1-w-details"],"nw":0},{"e":"the elephant in the room","d":"an obvious problem that nobody wants to talk about","x":"The budget cut is [[the elephant in the room]].","es":"el elefante en la sala; el tema que nadie se atreve a tocar","th":"animals","lv":"B2","src":["b2-meetings","c2-aiart6","c1-w-opinions","c2-w-present"],"nw":0},{"e":"the glass ceiling","d":"an unofficial barrier that stops women or other groups from reaching top jobs","x":"She was the first woman at the bank to break through [[the glass ceiling]].","es":"el techo de cristal","th":"success","lv":"B2","src":["b2-w-career"],"nw":0},{"e":"the go-to person","d":"the person everyone asks when they need help with a particular thing","x":"Ask Rodrigo. He's [[the go-to person]] for anything technical.","es":"la persona a la que todos recurren; el referente","th":"people","lv":"B2","src":["b2-w-intro"],"nw":0},{"e":"the jury is still out","d":"people haven't decided yet whether something is good, true, or useful","x":"[[The jury is still out]] on whether AI tutors really help kids learn.","es":"todavía no hay veredicto; está por verse","th":"risk","lv":"B2","src":["b2-tech","c1-food","c2-futureorgs6"],"nw":0},{"e":"the left hand doesn't know what the right hand is doing","d":"different parts of an organization don't communicate with each other","x":"Marketing announced a sale that finance never approved. [[The left hand doesn't know what the right hand is doing]]!","es":"la mano izquierda no sabe lo que hace la derecha","th":"body","lv":"B2","src":["b2-w-role"],"nw":0},{"e":"the light at the end of the tunnel","d":"a sign that a long, difficult period will soon end","x":"The renovation has taken eight months, but we can finally see [[the light at the end of the tunnel]].","es":"ver la luz al final del túnel","o":"Often with \"see\" or \"there's\": \"There's light at the end of the tunnel.\" Positive and hopeful.","th":"travel","lv":"B2","nw":1},{"e":"the new kid on the block","d":"the newest person in a group, who hasn't been there long","x":"As [[the new kid on the block]], I spent my first month just listening.","es":"el nuevo; el recién llegado","th":"people","lv":"B2","src":["b2-w-genz4"],"nw":0},{"e":"the point of no return","d":"the moment after which you cannot change your decision or go back","x":"Once we signed the contract and paid the deposit, we had reached [[the point of no return]].","es":"el punto de no retorno","o":"Originally from aviation: the point where a plane no longer has enough fuel to go back. Now used for any big decision.","th":"risk","lv":"B2","nw":1},{"e":"the proof is in the pudding","d":"you can only judge if something is good by trying it or seeing the results","x":"The new recipe sounds strange, but [[the proof is in the pudding]]. Let's taste it!","es":"el movimiento se demuestra andando; hay que probar para creer","th":"food","lv":"B2","src":["b2-science4","b2-w-research4"],"nw":0},{"e":"the sky's the limit","d":"there are no limits to what you can achieve","x":"With your talent, [[the sky's the limit]].","es":"el cielo es el límite","th":"weather","lv":"B2","src":["b2-plans"],"nw":0},{"e":"the sweet spot","d":"the ideal point or level, where you get the best result","x":"At 9,990 pesos, we found [[the sweet spot]] between sales and profit.","es":"el punto justo; el punto ideal","th":"success","lv":"B2","src":["b2-w-pricing4"],"nw":0},{"e":"the tip of the iceberg","d":"a small part of a much bigger thing","x":"What we know about the ocean is just [[the tip of the iceberg]].","es":"la punta del iceberg","th":"weather","lv":"B2","src":["b2-curious","b2-environment","c2-globalhealth6","c1-w-toxic5"],"nw":0},{"e":"the writing is on the wall","d":"there are clear signs that something will soon end or fail","x":"When the bank closed three branches in one month, [[the writing was on the wall]].","es":"estaba cantado; las señales eran claras","th":"trouble","lv":"B2","src":["c1-plans","c1-careers","b2-w-fintech4"],"nw":0},{"e":"three's a crowd","d":"two people, especially a couple, prefer to be alone without a third person","x":"I'm not going to the movies with you and your new girlfriend. [[Three's a crowd]]!","es":"hacer el mal tercio / el tercero sobra","o":"The full saying is \"two's company, three's a crowd.\" Usually said jokingly by the person who decides to stay away.","th":"people","lv":"B2","nw":1},{"e":"throw someone a curveball","d":"surprise someone with something unexpected that is difficult to deal with","x":"The interviewer [[threw me a curveball]] and asked me to describe my biggest failure.","es":"descolocar a alguien con algo inesperado","o":"From baseball, where a curveball is a pitch that changes direction. Also common: \"Life threw us a curveball.\"","th":"sport","lv":"B2","nw":1},{"e":"throw your hat in the ring","d":"to announce that you want to compete for a job or position","x":"When the director's job opened up, three managers [[threw their hats in the ring]].","es":"postularse; lanzarse a competir por un cargo","th":"sport","lv":"B2","src":["b2-w-career"],"nw":0},{"e":"tighten your belt","d":"to spend less money because you have less than before","x":"With prices going up, a lot of families are [[tightening their belts]].","es":"apretarse el cinturón","o":"Spanish uses the same image. Very common in news about the economy; the noun is “belt-tightening.”","th":"money","lv":"B2","nw":1},{"e":"to be on the safe side","d":"as a precaution, to avoid any possible problems or risks","x":"Let's leave for the airport at six, just [[to be on the safe side]].","es":"por si acaso / para ir a la segura","o":"Very common with \"just\": \"just to be on the safe side.\" Compare the short comment \"better safe than sorry.\"","th":"risk","lv":"B2","nw":1},{"e":"to make a long story short","d":"used to skip the details and say what finally happened","x":"We missed the train, lost our hotel reservation and, [[to make a long story short]], we slept at the airport.","es":"en resumidas cuentas / para no alargar la historia","o":"In informal speech people often shorten it to \"long story short.\"","th":"talk","lv":"B2","nw":1,"uk":"UK: to cut a long story short"},{"e":"too good to be true","d":"so good that it is probably false or a trick","x":"A free phone for answering three questions? It sounds [[too good to be true]].","es":"demasiado bueno para ser cierto","th":"risk","lv":"B2","src":["b2-media","b2-crime4","c1-money5","c2-authenticity6","b2-w-compare"],"nw":0},{"e":"trust your gut","d":"to follow your instinct, even without clear evidence","x":"The numbers looked good, but I [[trusted my gut]] and said no.","es":"seguir tu instinto; hacerle caso a lo que te tinca","th":"body","lv":"B2","src":["b2-w-decisions","c1-w-decisions"],"nw":0},{"e":"truth is stranger than fiction","d":"real life can be more surprising than invented stories","x":"No one would believe that story in a movie. [[Truth really is stranger than fiction]].","es":"la realidad supera a la ficción","th":"talk","lv":"B2","src":["b2-curious"],"nw":0},{"e":"try your hand at","d":"to try doing something for the first time","x":"I'd love to [[try my hand at]] surfing.","es":"probar suerte con algo; atreverse con algo","th":"body","lv":"B2","src":["b2-hobbies"],"nw":0},{"e":"turn a blind eye","d":"to pretend not to notice something wrong","x":"The coach [[turned a blind eye]] to players arriving late.","es":"hacer la vista gorda; hacerse el leso","th":"body","lv":"B2","src":["b2-ethics","c1-bizethics5"],"nw":0},{"e":"turn back the clock","d":"to return to an earlier time or situation","x":"If I could [[turn back the clock]], I'd study medicine instead of law.","es":"volver el tiempo atrás","o":"Often used with regret, or to criticize a change that brings back old ways of doing things.","th":"time","lv":"B2","nw":1},{"e":"twist someone's arm","d":"to persuade someone to do something they don't really want to do","x":"I wasn't planning to go to karaoke night, but Mia [[twisted my arm]].","es":"convencer a alguien a fuerza de insistir; “ya, me convenciste”","o":"Often used jokingly when you accept an offer you actually like: “OK, you twisted my arm — one more slice.”","th":"body","lv":"B2","nw":1,"reg":"informal"},{"e":"until you're blue in the face","d":"for a long time and without any result, however hard you try","x":"You can argue with him [[until you're blue in the face]], but he won't change his mind.","es":"hasta el cansancio","o":"Used with verbs like talk, argue, explain or complain, to say that the effort is useless.","th":"colors","lv":"B2","nw":1,"reg":"informal"},{"e":"wake up on the wrong side of the bed","d":"to be in a bad mood all day for no clear reason","x":"What's wrong with Diego today? Did he [[wake up on the wrong side of the bed]]?","es":"levantarse con el pie izquierdo; andar de malas","o":"Usually a light, teasing question about someone's grumpy mood.","th":"feelings","lv":"B2","nw":1,"uk":"UK: get out of bed on the wrong side"},{"e":"walk on eggshells","d":"to be very careful about what you say or do so you don't upset someone","x":"Since the merger, everyone's been [[walking on eggshells]] around the new director.","es":"andar con pies de plomo; caminar sobre cáscaras de huevo","th":"food","lv":"B2","src":["c1-relationships","c1-workplace","c2-diplomacy6","b2-w-global4","c1-w-toxic5"],"nw":0},{"e":"walk the talk","d":"to act in the same way that you tell other people to act","x":"Our CEO says families come first, and she [[walks the talk]]: she never schedules meetings after six.","es":"predicar con el ejemplo","th":"talk","lv":"B2","src":["b2-w-trust4"],"nw":0},{"e":"wear your heart on your sleeve","d":"to show your emotions openly and clearly","x":"Diego [[wears his heart on his sleeve]], so you always know when he's unhappy with a decision.","es":"andar con el corazón en la mano; no esconder lo que siente","th":"body","lv":"B2","src":["c1-personal","c2-identity6","b2-w-body4","c2-w-authentic6"],"nw":0},{"e":"when it rains, it pours","d":"bad things tend to happen together, one after another","x":"First the car broke down, and then the washing machine. [[When it rains, it pours]]!","es":"llueve sobre mojado; las desgracias nunca vienen solas","o":"Said with a sigh when several problems arrive at the same time.","th":"weather","lv":"B2","nw":1,"uk":"UK: it never rains but it pours"},{"e":"wing it","d":"to do something without preparing for it first","x":"I didn't have time to prepare, so I had to [[wing it]].","es":"improvisar; salir del paso","th":"risk","lv":"B2","src":["b2-w-present","c1-w-media5"],"nw":0},{"e":"wrap your head around","d":"to understand something difficult or hard to believe (informal)","x":"I still can't [[wrap my head around]] the fact that sharks are older than trees.","es":"lograr entender algo; no caberle a uno en la cabeza","th":"body","lv":"B2","src":["b2-curious"],"nw":0},{"e":"young at heart","d":"feeling and acting young, even if you are old","x":"My aunt is 80, but she's still [[young at heart]]. She goes dancing every week.","es":"joven de espíritu; tener alma joven","th":"body","lv":"B2","src":["b2-generations4","c1-aging5"],"nw":0},{"e":"your eyes are bigger than your stomach","d":"you take more food than you can actually eat","x":"I always pile my plate too high at buffets. [[My eyes are bigger than my stomach]].","es":"comer con los ojos","th":"body","lv":"B2","src":["b2-food"],"nw":0},{"e":"your mind goes blank","d":"you suddenly can't remember anything or think of anything to say","x":"When the CEO asked me a question, [[my mind went blank]].","es":"quedarse en blanco","th":"body","lv":"B2","src":["b2-w-present"],"nw":0},{"e":"(as) thick as thieves","d":"very close friends who share secrets and spend a lot of time together","x":"Those two started on the same day and have been [[thick as thieves]] ever since.","es":"ser uña y carne; ser yunta","o":"Informal and usually friendly, though it can suggest they're keeping something from everyone else.","th":"people","lv":"C1","nw":1,"reg":"informal"},{"e":"(compare) apples to oranges","d":"comparing two things that are too different to compare fairly","x":"Comparing our two-person team with their fifty-person department is [[apples to oranges]].","es":"son peras y manzanas; comparar peras con manzanas","th":"food","lv":"C1","src":["c1-w-compare"],"nw":0},{"e":"a big ask","d":"a request that is difficult, or a lot to expect from someone","x":"Finishing the report by tomorrow is [[a big ask]], I know.","es":"es mucho pedir","th":"talk","lv":"C1","src":["c1-w-calls"],"nw":0},{"e":"a big fish in a small pond","d":"an important or successful person, but only in a small group or place","x":"In my hometown I was [[a big fish in a small pond]]; in Santiago, nobody knew me.","es":"ser cabeza de ratón; un pez grande en un estanque chico","th":"animals","lv":"C1","src":["c1-talent5"],"nw":0},{"e":"a blast from the past","d":"something or someone that suddenly and strongly reminds you of an earlier time","x":"Look who's here! Seeing you after twenty years is a real [[blast from the past]].","es":"un viaje al pasado; un recuerdo de otros tiempos","th":"time","lv":"C1","src":["c1-nostalgia5"],"nw":0},{"e":"a bull in a china shop","d":"a person who is clumsy or tactless in a situation that needs care","x":"He handled the delicate negotiation like [[a bull in a china shop]] and nearly lost us the client.","es":"como elefante en cristalería","o":"'China' here means fine plates and cups. Usually after 'like': He's like a bull in a china shop.","th":"animals","lv":"C1","nw":1},{"e":"a check-the-box exercise","d":"something done only to meet a formal requirement, not because it's useful","x":"Our ethics training used to be [[a check-the-box exercise]]: ten slides and a quiz.","es":"un mero trámite; algo que se hace para cumplir no más","th":"money","lv":"C1","src":["c1-w-rules"],"nw":0},{"e":"a cog in the machine","d":"a person who feels small and unimportant in a large organization","x":"In my last job, I was just [[a cog in the machine]]; nobody even knew my name.","es":"una pieza más del engranaje; un número más","th":"money","lv":"C1","src":["c1-w-process","c2-w-meaning6"],"nw":0},{"e":"a done deal","d":"an agreement or decision that is final and cannot be changed","x":"Don't announce anything yet. It isn't [[a done deal]].","es":"un hecho; cosa cerrada","th":"money","lv":"C1","src":["c1-w-ma5","c2-w-board6"],"nw":0},{"e":"a feather in your cap","d":"an achievement that you can be proud of","x":"Winning the national award was [[a feather in her cap]] and helped her get promoted.","es":"un logro del que enorgullecerse; un punto a tu favor","o":"Usually an achievement that improves your reputation or career, not just your personal happiness.","th":"success","lv":"C1","nw":1},{"e":"a fine line","d":"a very small difference between something acceptable and something that isn't","x":"There's [[a fine line]] between protecting employees and spying on them.","es":"una línea muy delgada","th":"risk","lv":"C1","src":["c1-privacy5"],"nw":0},{"e":"a fly on the wall","d":"someone who secretly watches or listens to a situation without being noticed","x":"I'd love to be [[a fly on the wall]] when they tell the CEO about the delay.","es":"ser una mosquita (para ver y escuchar sin ser visto)","o":"Usually in the pattern 'I'd love to be a fly on the wall'. Also an adjective: a fly-on-the-wall documentary.","th":"animals","lv":"C1","nw":1},{"e":"a fork in the road","d":"a point where you must choose between two different paths in life or work","x":"After graduation, I came to [[a fork in the road]]: take the job in Santiago or study abroad.","es":"una encrucijada","o":"Usually about big life or career decisions. Similar: at a crossroads.","th":"travel","lv":"C1","nw":1},{"e":"a ghost town","d":"a place that is almost completely empty, although it is supposed to be busy","x":"After 5 p.m. on Fridays, the whole building is [[a ghost town]].","es":"un pueblo fantasma; estar desierto","th":"travel","lv":"C1","src":["c1-w-space"],"nw":0},{"e":"a grain of truth","d":"a small amount of truth","x":"There's [[a grain of truth]] in most legends.","es":"algo de verdad; una pizca de verdad","th":"talk","lv":"C1","src":["c1-curious"],"nw":0},{"e":"a jack of all trades","d":"someone who can do many things, but none perfectly","x":"I'm [[a jack of all trades]], master of none.","es":"un todero; aprendiz de todo, maestro de nada","th":"people","lv":"C1","src":["c1-hobbies","c2-hobbies","c1-w-career"],"nw":0},{"e":"a license to print money","d":"a business or activity that makes huge profits very easily","x":"Some people thought owning a parking lot downtown was [[a license to print money]].","es":"una máquina de hacer plata; una mina de oro","th":"money","lv":"C1","src":["c1-money5"],"nw":0},{"e":"a lightning rod","d":"a person or thing that attracts most of the criticism or anger in a situation","x":"As the face of the new policy, the HR director became [[a lightning rod]] for employee complaints.","es":"el blanco de todas las críticas; el pararrayos","o":"Mainly American. Usually 'a lightning rod for criticism, anger or controversy'. Literally, a metal rod that protects buildings.","th":"weather","lv":"C1","nw":1},{"e":"a loose cannon","d":"a person who behaves unpredictably and may cause problems for their group","x":"Our new spokesperson is [[a loose cannon]]; you never know what he'll say to reporters.","es":"una bala perdida; alguien impredecible","o":"Used for employees, players or public figures who act on their own and embarrass the group.","th":"people","lv":"C1","nw":1},{"e":"a moonshot","d":"an extremely ambitious project that may seem impossible but could have a huge impact","x":"Flying passenger planes without any emissions is a real [[moonshot]], but engineers are working on it.","es":"un proyecto muy ambicioso; apuntar a la luna","th":"success","lv":"C1","src":["c1-spacefuture5"],"nw":0},{"e":"a one-hit wonder","d":"an artist famous for only one song","x":"Many '90s bands were [[one-hit wonders]].","es":"flor de un día; artista de un solo éxito","th":"success","lv":"C1","src":["c1-music"],"nw":0},{"e":"a perfect storm","d":"a rare combination of bad events that together make a situation much worse","x":"Rising rents, high interest rates and low wages have created [[a perfect storm]] for young buyers.","es":"una tormenta perfecta","o":"Very common in news and business. Use it when several problems hit at once and make each other worse.","th":"weather","lv":"C1","nw":1},{"e":"a piece of the pie","d":"a share of the money, profit or benefits from something","x":"Now that the app is making money, every early investor wants [[a piece of the pie]].","es":"una tajada; un pedazo de la torta","o":"Common in business and economics. Often 'a bigger piece of the pie' or 'a slice of the pie'.","th":"food","lv":"C1","nw":1},{"e":"a pipe dream","d":"a hope or plan that is impossible to achieve","x":"Opening fifty stores in a year is [[a pipe dream]]; we don't have the people.","es":"una quimera; un sueño imposible","th":"success","lv":"C1","src":["c1-w-future"],"nw":0},{"e":"a quick study","d":"a person who learns new things very fast","x":"She's [[a quick study]]: give her a week and she'll know the software better than you.","es":"alguien que aprende rápido; que cacha todo al tiro","th":"people","lv":"C1","src":["c1-talent5"],"nw":0},{"e":"a red herring","d":"a fact or idea that takes attention away from what really matters","x":"The budget debate was [[a red herring]]; the real problem was poor communication between departments.","es":"una pista falsa; una cortina de humo","o":"Common in mystery novels, where writers plant false clues to mislead readers, and in debates and business analysis.","th":"colors","lv":"C1","nw":1},{"e":"a red-letter day","d":"a very special, important or happy day that you will remember","x":"The day we finally paid off our mortgage was [[a red-letter day]] for our family.","es":"un día memorable; un día para marcar en el calendario","o":"From old calendars, which printed holidays and important days in red.","th":"colors","lv":"C1","nw":1},{"e":"a revolving door","d":"a place where people keep joining and leaving, so nobody stays long","x":"With three managers in a year, the marketing department has become [[a revolving door]].","es":"una puerta giratoria; un desfile de gente que entra y sale","th":"money","lv":"C1","src":["c1-corpculture5"],"nw":0},{"e":"a shot in the arm","d":"something that suddenly gives new energy, confidence or money","x":"The new contract was [[a shot in the arm]] for our small team after a slow year.","es":"una inyección de ánimo (o de energía)","o":"Common in business news: tourism, investment or a new product can be a shot in the arm for a company or town.","th":"body","lv":"C1","nw":1},{"e":"a sign of the times","d":"something that shows what society is like now, often in a negative way","x":"Our neighborhood bookstore is now a phone repair shop — [[a sign of the times]], I guess.","es":"un signo de los tiempos; reflejo de la época","o":"Usually said with a sigh about change: closed shops, new technology, changing habits.","th":"time","lv":"C1","nw":1},{"e":"a sitting duck","d":"a person or thing that is very easy to attack","x":"Without regular updates, our old servers are [[sitting ducks]].","es":"un blanco fácil; presa fácil","th":"animals","lv":"C1","src":["c1-w-cyber5"],"nw":0},{"e":"a slam dunk","d":"something that is certain to succeed or very easy to achieve","x":"With her experience, getting the job should be [[a slam dunk]].","es":"un triunfo asegurado; pan comido","o":"American, from basketball, where a player jumps and pushes the ball down through the basket. Used for deals, cases and decisions.","th":"sport","lv":"C1","nw":1,"reg":"informal"},{"e":"a slippery slope","d":"a first step that is likely to lead to worse and worse things","x":"Tracking employees' keystrokes is [[a slippery slope]].","es":"una pendiente resbaladiza; un terreno peligroso","th":"risk","lv":"C1","src":["c1-tech","c1-health","c1-ethics","c1-w-monitor5","c2-w-nudge6"],"nw":0},{"e":"a sounding board","d":"a person you share ideas with to find out how good they are","x":"My old boss is still my [[sounding board]] for big decisions.","es":"alguien con quien contrastar ideas; un consejero de confianza","th":"talk","lv":"C1","src":["c1-mentoring5"],"nw":0},{"e":"a square peg in a round hole","d":"a person who doesn't fit well into a particular situation or system","x":"As a restless, creative kid, he was [[a square peg in a round hole]] at such a strict school.","es":"sapo de otro pozo; como pez fuera del agua","th":"people","lv":"C1","src":["c1-edreform5","c2-careers","c1-w-neuro5"],"nw":0},{"e":"a sticking point","d":"an issue that stops people from reaching an agreement","x":"Working from home became [[a sticking point]] in the contract negotiations.","es":"el punto de discordia; el escollo","o":"Common in news about negotiations, contracts and deals: The main sticking point was price.","th":"trouble","lv":"C1","nw":1},{"e":"a stitch in time (saves nine)","d":"fixing a small problem early prevents a much bigger one later","x":"Update the software now, not after the next crash. [[A stitch in time saves nine]].","es":"más vale prevenir que curar; un arreglo a tiempo ahorra problemas","th":"time","lv":"C1","src":["c1-w-problems"],"nw":0},{"e":"a thorn in someone's side","d":"a person or thing that keeps annoying you or causing problems","x":"That one difficult customer has been [[a thorn in our side]] since we opened.","es":"una piedra en el zapato","o":"Used for rivals, critics, competitors or a problem that won't go away.","th":"trouble","lv":"C1","nw":1},{"e":"a ticking time bomb","d":"a situation that will become a serious problem in the future if nothing is done","x":"Experts call low savings among young workers [[a ticking time bomb]].","es":"una bomba de tiempo","th":"trouble","lv":"C1","src":["c1-aging5","c2-globalhealth6","c1-w-report"],"nw":0},{"e":"a tough act to follow","d":"someone or something so good that whoever comes next will struggle to match it","x":"Our last manager was brilliant, so whoever replaces her has [[a tough act to follow]].","es":"dejar la vara muy alta; difícil de igualar","o":"From show business, where an 'act' is a performance. Also: a hard act to follow.","th":"success","lv":"C1","nw":1},{"e":"a tourist trap","d":"an overpriced place designed to attract tourists","x":"That restaurant is a total [[tourist trap]].","es":"una trampa para turistas","th":"travel","lv":"C1","src":["c1-travel"],"nw":0},{"e":"a wet blanket","d":"a person who spoils other people's fun by being negative","x":"Don't be [[a wet blanket]] — come to the karaoke night, even if you just watch.","es":"un aguafiestas","o":"Informal. Used for someone who complains or refuses to join in. Similar: killjoy.","th":"people","lv":"C1","nw":1,"reg":"informal"},{"e":"a white elephant","d":"something very expensive that turns out to be useless or rarely used","x":"The new airport terminal has turned into [[a white elephant]]: it's huge, expensive and almost empty.","es":"un elefante blanco","th":"animals","lv":"C1","src":["c1-architecture5"],"nw":0},{"e":"add insult to injury","d":"to make a bad situation even worse for someone","x":"They lost my luggage and then, to [[add insult to injury]], charged me for the call.","es":"para colmo; echar sal en la herida","th":"trouble","lv":"C1","src":["c1-w-apology5"],"nw":0},{"e":"all bets are off","d":"what was expected or agreed no longer applies; anything could happen","x":"If the merger goes ahead, [[all bets are off]] for our department's budget.","es":"ya no hay nada seguro; todo puede pasar","o":"Often after an 'if' clause: If it rains, all bets are off. Common in sports, business and news.","th":"risk","lv":"C1","nw":1},{"e":"all over the map","d":"disorganized, inconsistent or dealing with too many different things","x":"His presentation was [[all over the map]], and nobody understood his main point.","es":"disperso; sin ton ni son","o":"American. Used for opinions, prices, results and plans that vary a lot or lack focus.","th":"travel","lv":"C1","nw":1,"reg":"informal","uk":"UK: all over the place"},{"e":"an ace up your sleeve","d":"a secret advantage that you can use when you need it","x":"The other candidates had more experience, but I had [[an ace up my sleeve]]: I speak fluent Portuguese.","es":"un as bajo la manga","o":"From card games, where a cheater hides an ace to play later. Usually with 'have' or 'keep'.","th":"sport","lv":"C1","nw":1},{"e":"an echo chamber","d":"a situation where you only hear opinions that match your own","x":"If you only follow people who agree with you, you end up in [[an echo chamber]].","es":"una cámara de eco; vivir en una burbuja","th":"talk","lv":"C1","src":["c1-media"],"nw":0},{"e":"an old flame","d":"a person you once had a romantic relationship with","x":"At the reunion, he bumped into [[an old flame]] from college and they talked for hours.","es":"un antiguo amor","o":"Softer and more nostalgic than 'my ex'. Often used when someone unexpectedly meets a former partner.","th":"people","lv":"C1","nw":1},{"e":"be on top of the world","d":"to feel extremely happy and proud","x":"She's [[been on top of the world]] since her daughter was born.","es":"estar feliz de la vida; sentirse en la gloria","th":"feelings","lv":"C1","src":["c1-happiness5"],"nw":0},{"e":"be snowed under (with)","d":"to have far more work than you can deal with","x":"Sorry for the slow reply; [[I'm snowed under]] with year-end reports.","es":"estar tapado de pega; estar hasta el cuello de trabajo","th":"weather","lv":"C1","src":["c1-w-email"],"nw":0},{"e":"be stretched thin","d":"to have too many responsibilities at the same time","x":"With three projects at once, [[I'm stretched thin]].","es":"no dar abasto; estar sobrepasado","th":"trouble","lv":"C1","src":["c1-everyday"],"nw":0},{"e":"beside yourself","d":"so upset, worried, angry or excited that you can't control your feelings","x":"When their daughter didn't come home or answer her phone, they were [[beside themselves]] with worry.","es":"fuera de sí","o":"Usually followed by 'with': beside herself with grief, anger or joy.","th":"feelings","lv":"C1","nw":1},{"e":"bet the farm","d":"to risk everything you have on one plan or idea","x":"It's a promising market, but I wouldn't [[bet the farm]] on it.","es":"jugarse el todo por el todo; apostarlo todo","th":"risk","lv":"C1","src":["c1-w-vc5"],"nw":0},{"e":"Big Brother","d":"a person or organization that watches people too closely and controls their lives","x":"With cameras in every meeting room, it feels like [[Big Brother]] is watching.","es":"el Gran Hermano","th":"people","lv":"C1","src":["c1-w-monitor5"],"nw":0},{"e":"bottle something up","d":"to hide strong feelings instead of expressing them","x":"Talk to someone — if you keep [[bottling everything up]], it'll only get worse.","es":"guardarse todo; tragarse las emociones","o":"Used for emotions such as anger, sadness or stress. Also as an adjective: bottled-up feelings.","th":"feelings","lv":"C1","nw":1},{"e":"bring out the best in someone","d":"to help someone show their best qualities","x":"Working with demanding clients [[brings out the best in her]].","es":"sacar lo mejor de alguien","th":"people","lv":"C1","src":["c1-mentoring5"],"nw":0},{"e":"broaden your horizons","d":"to increase your knowledge and experience of the world","x":"Traveling really [[broadens your horizons]].","es":"ampliar horizontes","th":"travel","lv":"C1","src":["c1-travel"],"nw":0},{"e":"bury the lede","d":"to hide the most important information in the middle or at the end","x":"Don't [[bury the lede]]: if we lost our biggest client, say so in the first sentence.","es":"esconder lo más importante; no ir al grano","th":"talk","lv":"C1","src":["c1-w-trends"],"nw":0},{"e":"bury your head in the sand","d":"to refuse to accept that a problem exists","x":"We can't keep [[burying our heads in the sand]] about rising energy costs.","es":"esconder la cabeza como el avestruz; no querer ver el problema","th":"body","lv":"C1","src":["c1-w-risk5","c2-w-die6"],"nw":0},{"e":"by the skin of your teeth","d":"only just; by a very small margin","x":"Traffic was terrible, and we made our connecting flight [[by the skin of our teeth]].","es":"por un pelo; (pasar) raspando","o":"Used with verbs like pass, escape, survive and make it. The pronoun changes: by the skin of my/her/our teeth.","th":"body","lv":"C1","nw":1},{"e":"call it a day","d":"to stop working for the day","x":"It's 8 p.m. Let's [[call it a day]].","es":"dar por terminada la jornada; dejarlo hasta aquí","th":"time","lv":"C1","src":["c1-everyday"],"nw":0},{"e":"close the loop","d":"to make sure that materials are recovered and used again instead of becoming waste","x":"By turning old bottles into new bottles, they've [[closed the loop]].","es":"cerrar el ciclo","th":"weather","lv":"C1","src":["c1-w-circular5"],"nw":0},{"e":"come apart at the seams","d":"to start to fail or break down completely","x":"Without a clear leader, the project started to [[come apart at the seams]].","es":"desmoronarse; venirse abajo","o":"Used for plans, teams, relationships and people under stress. Also: fall apart at the seams.","th":"trouble","lv":"C1","nw":1},{"e":"come back to haunt you","d":"(of something you said or did) to cause problems for you later","x":"That joke about our competitors [[came back to haunt him]] two years later.","es":"pasar la cuenta; volverse en contra","th":"trouble","lv":"C1","src":["c1-w-media5"],"nw":0},{"e":"come clean","d":"to finally tell the truth about something you have been hiding","x":"Eventually, the company [[came clean]] about the delays.","es":"sincerarse; confesar la verdad","th":"talk","lv":"C1","src":["c1-crisis5"],"nw":0},{"e":"come into your own","d":"to finally show your real abilities or value in the right situation","x":"She was quiet in her first year, but she really [[came into her own]] when she started leading projects.","es":"brillar con luz propia; encontrar su lugar","o":"Also used for things: Electric cars are finally coming into their own.","th":"success","lv":"C1","nw":1},{"e":"come to terms with","d":"to accept a difficult situation","x":"He finally [[came to terms with]] his mistakes.","es":"asumir algo; aceptar algo difícil","th":"feelings","lv":"C1","src":["c1-personal"],"nw":0},{"e":"connect the dots","d":"to see how separate pieces of information are related","x":"Nobody [[connected the dots]] between the price change and the drop in repeat customers.","es":"atar cabos","th":"trouble","lv":"C1","src":["c1-w-trends"],"nw":0},{"e":"cook the books","d":"to change financial records dishonestly, usually to hide losses or steal money","x":"The auditors discovered that the finance director [[had been cooking the books]] for years.","es":"maquillar las cuentas","o":"Informal. 'The books' are a company's accounts. Common in news about financial scandals.","th":"money","lv":"C1","nw":1,"reg":"informal"},{"e":"cross the line","d":"to go too far; to offend","x":"That joke really [[crossed the line]].","es":"pasarse de la raya","th":"people","lv":"C1","src":["c1-humor","c1-ethics","c1-w-monitor5"],"nw":0},{"e":"cut both ways","d":"to have both advantages and disadvantages","x":"Working from home [[cuts both ways]]: more freedom, but fewer boundaries.","es":"ser un arma de doble filo; tener su lado bueno y su lado malo","th":"risk","lv":"C1","src":["c1-tech"],"nw":0},{"e":"cut off your nose to spite your face","d":"to do something to punish someone else that actually hurts you more","x":"Quitting just to annoy your boss would be [[cutting off your nose to spite your face]].","es":"tirar piedras contra tu propio tejado","o":"Used to warn someone against acting out of anger or pride: Don't cut off your nose to spite your face.","th":"body","lv":"C1","nw":1},{"e":"cut to the chase","d":"to talk or write about the most important point immediately","x":"Let me [[cut to the chase]]: we need your approval by Friday.","es":"ir al grano","th":"talk","lv":"C1","src":["c1-w-email"],"nw":0},{"e":"cut your losses","d":"to stop doing something that is failing, so that you don't lose even more","x":"After six empty months, we [[cut our losses]] and closed the branch.","es":"cortar por lo sano; no seguir perdiendo","th":"money","lv":"C1","src":["c1-w-decisions"],"nw":0},{"e":"death by a thousand cuts","d":"slow damage caused by many small problems, none of which seems serious alone","x":"No single interruption is a disaster, but together they're [[death by a thousand cuts]].","es":"una muerte lenta; el desgaste de mil problemas chicos","th":"trouble","lv":"C1","src":["c1-w-routine"],"nw":0},{"e":"dig yourself into a hole","d":"to get yourself into a difficult situation, often through your own words or actions","x":"The more he tried to explain the mistake, the deeper he [[dug himself into a hole]].","es":"hundirse solo; meterse en un lío","o":"Often with 'deeper'. A common piece of advice: When you're in a hole, stop digging.","th":"trouble","lv":"C1","nw":1},{"e":"drag your feet","d":"to be slow to do something because you don't really want to do it","x":"The landlord [[has been dragging his feet]] on fixing the heating for weeks.","es":"dar largas; hacerse el remolón","o":"Usually critical. Often followed by 'on' or 'over': drag your feet on a decision. Also: drag your heels.","th":"body","lv":"C1","nw":1},{"e":"eat humble pie","d":"to admit publicly that you were wrong, even though it is embarrassing","x":"After the failed launch, the CEO had to [[eat humble pie]] in front of the investors.","es":"tragarse el orgullo; reconocer el error públicamente","th":"food","lv":"C1","src":["c1-w-apology5"],"nw":0},{"e":"fake it till you make it","d":"to act confident until you really become confident or skilled","x":"On my first day as a team leader, I decided to [[fake it till I made it]].","es":"aparentar seguridad hasta lograrla; finge hasta que lo consigas","th":"success","lv":"C1","src":["c1-w-imposter5","c2-w-authentic6"],"nw":0},{"e":"fall from grace","d":"to lose your good reputation or position, often because of a mistake or scandal","x":"The once-famous chef [[fell from grace]] after the tax scandal.","es":"caer en desgracia","o":"Can be a verb or a noun (a fall from grace). Common in news about celebrities and business leaders.","th":"success","lv":"C1","nw":1},{"e":"fly under the radar","d":"to avoid being noticed by the public or the authorities","x":"For years, the data company [[flew under the radar]]; most people had never heard of it.","es":"pasar desapercibido; pasar piola","th":"travel","lv":"C1","src":["c1-privacy5"],"nw":0},{"e":"foot the bill","d":"to pay for something, often when you don't want to","x":"The airline lost our luggage, so they'll have to [[foot the bill]] for the clothes we bought.","es":"correr con los gastos; pagar la cuenta","o":"Used with companies, governments, taxpayers or parents: Who's going to foot the bill?","th":"money","lv":"C1","nw":1},{"e":"for a song","d":"very cheaply; for much less than something is worth","x":"They bought the old farmhouse [[for a song]] and spent five years restoring it.","es":"a precio de huevo; regalado","o":"Usually with buy, sell or get: She picked up the painting for a song at a flea market.","th":"money","lv":"C1","nw":1},{"e":"full steam ahead","d":"with as much energy and speed as possible","x":"Once the bank approved the loan, it was [[full steam ahead]] with the new factory.","es":"a todo vapor; a toda máquina","o":"The image is a steamship or train at top speed. Often: It's full steam ahead with the project.","th":"travel","lv":"C1","nw":1},{"e":"game the system","d":"to use the rules in a clever but unfair way to get an advantage","x":"If you pay agents per call, some will [[game the system]] by ending calls early.","es":"aprovecharse del sistema; hecha la ley, hecha la trampa","th":"sport","lv":"C1","src":["c1-w-achieve"],"nw":0},{"e":"garbage in, garbage out","d":"if the information you put into a system is bad, the results will be bad too","x":"The forecast was wrong because half the sales data was missing. [[Garbage in, garbage out]].","es":"si entra basura, sale basura","th":"trouble","lv":"C1","src":["c1-w-process"],"nw":0},{"e":"get cold feet","d":"to suddenly feel too nervous to do something you had planned","x":"He [[got cold feet]] the night before the bungee jump.","es":"echarse para atrás a última hora","th":"body","lv":"C1","src":["c1-risk5","c1-w-ma5"],"nw":0},{"e":"get into the weeds","d":"to talk about small details that aren't relevant to your audience","x":"The board doesn't need to know how the software works, so don't [[get into the weeds]].","es":"perderse en los detalles; meterse en detalles técnicos","th":"weather","lv":"C1","src":["c1-w-present"],"nw":0},{"e":"get lost in translation","d":"(of a meaning or joke) to disappear or be misunderstood when it passes between languages or cultures","x":"My joke about Chilean paperwork [[got completely lost in translation]].","es":"perderse en la traducción","th":"talk","lv":"C1","src":["c1-crosscultural5","c2-language6"],"nw":0},{"e":"get your ducks in a row","d":"to organize everything carefully before you start something","x":"Before we pitch the idea to investors, we need to [[get our ducks in a row]].","es":"tener todo en orden; dejar todo listo","o":"Mainly American and very common at work. Also: have your ducks in a row.","th":"animals","lv":"C1","nw":1,"reg":"informal"},{"e":"give someone a run for their money","d":"to compete so strongly that the other side has to work hard to win","x":"The new fintech is [[giving the big banks a run for their money]].","es":"dar pelea; ponérsela difícil a alguien","th":"sport","lv":"C1","src":["c1-w-compare"],"nw":0},{"e":"give someone free rein","d":"to allow someone complete freedom to act as they think best","x":"The CEO [[gave the design team free rein]] on the new store layout.","es":"dar carta blanca; dar rienda suelta","th":"people","lv":"C1","src":["c1-w-micro5"],"nw":0},{"e":"go back to the drawing board","d":"to start planning again from the beginning because an idea has failed","x":"Users hated the new design, so the team [[went back to the drawing board]].","es":"volver a foja cero; empezar de nuevo","th":"success","lv":"C1","src":["c1-innovation5"],"nw":0},{"e":"go down a rabbit hole","d":"to become completely absorbed in a topic, moving from one thing to the next (often online)","x":"I [[went down a rabbit hole]] about medieval bookbinding and lost my whole Sunday.","es":"perderse en un tema; engancharse con algo en internet","th":"animals","lv":"C1","src":["c1-hobbies","c2-tech"],"nw":0},{"e":"go down in flames","d":"to fail completely and very publicly","x":"Their plan to open ten new stores in one year [[went down in flames]].","es":"fracasar estrepitosamente; irse a pique","o":"Informal and dramatic. Used for plans, businesses, relationships and product launches.","th":"success","lv":"C1","nw":1,"reg":"informal"},{"e":"go for broke","d":"to risk everything you have in one big attempt to succeed","x":"They decided to [[go for broke]] and invest all their savings in a second restaurant.","es":"jugarse el todo por el todo","o":"Informal, mainly American. 'Broke' means having no money, the possible result of the risk.","th":"risk","lv":"C1","nw":1,"reg":"informal"},{"e":"go native","d":"to adopt the local customs and lifestyle (often humorous)","x":"After a year in Japan, he completely [[went native]].","es":"adoptar las costumbres locales; volverse uno más del lugar","th":"travel","lv":"C1","src":["c1-travel"],"nw":0},{"e":"go out on a limb","d":"to take a risk by saying or doing something others may not support","x":"I'll [[go out on a limb]] and say this product will be our best seller next year.","es":"arriesgarse; jugársela","o":"Common pattern: I'll go out on a limb and say... Also used when you support someone at your own risk.","th":"risk","lv":"C1","nw":1},{"e":"go to pieces","d":"to become so upset or nervous that you cannot think or act normally","x":"She's calm in most situations, but she [[goes to pieces]] whenever she has to speak in public.","es":"derrumbarse; perder el control","o":"Used for stress, grief or panic. Also: fall to pieces. The opposite is 'keep it together'.","th":"feelings","lv":"C1","nw":1},{"e":"go under the hammer","d":"to be sold at an auction","x":"The singer's guitar collection will [[go under the hammer]] next month.","es":"salir a remate; ser rematado","th":"money","lv":"C1","src":["c1-artworld5"],"nw":0},{"e":"green around the gills","d":"looking pale and sick, as if you might throw up","x":"After the boat ride, half the tour group looked [[green around the gills]].","es":"pálido; con cara de mareado","o":"Informal and a little humorous. Often used for seasickness, hangovers or nerves before a big event.","th":"colors","lv":"C1","nw":1,"reg":"informal","uk":"UK also: green about the gills"},{"e":"half-baked","d":"(of an idea or plan) not carefully thought through","x":"The committee rejected the proposal as [[half-baked]] and asked for real numbers.","es":"a medio cocinar; mal pensado","o":"Used for ideas, plans, schemes and theories. Usually before a noun: a half-baked idea.","th":"food","lv":"C1","nw":1},{"e":"have a chip on your shoulder","d":"to feel resentful and easily offended because you think you've been treated unfairly","x":"Ever since he was passed over for promotion, Mark [[has had a chip on his shoulder]] about management.","es":"andar resentido; sentirse menospreciado","o":"Often followed by 'about': She has a chip on her shoulder about not going to college.","th":"body","lv":"C1","nw":1},{"e":"have bigger fish to fry","d":"to have more important things to deal with","x":"I'm not going to argue about the coffee machine; I [[have bigger fish to fry]] this week.","es":"tener cosas más importantes que hacer","o":"Used to explain why you're ignoring a small problem. Also: have other fish to fry.","th":"food","lv":"C1","nw":1,"reg":"informal"},{"e":"have deep pockets","d":"to have a lot of money available to spend","x":"Small businesses can't compete with chains that [[have deep pockets]] for advertising.","es":"tener mucha plata; tener los bolsillos llenos","o":"Often used for companies, investors or governments. Also as an adjective: a deep-pocketed investor.","th":"money","lv":"C1","nw":1},{"e":"have egg on your face","d":"to look foolish because something you said or did turned out wrong","x":"If we announce the launch date and then miss it, we'll [[have egg on our faces]].","es":"quedar en ridículo","o":"Common in news and office talk about public mistakes. Also: end up with egg on your face.","th":"food","lv":"C1","nw":1,"reg":"informal"},{"e":"head and shoulders above","d":"much better than others","x":"Her proposal was [[head and shoulders above]] the rest.","es":"estar muy por encima del resto; no tener comparación","th":"body","lv":"C1","src":["c1-w-compare"],"nw":0},{"e":"hit a wall","d":"to reach a point where you cannot make any more progress","x":"I studied Japanese happily for a year, and then I [[hit a wall]].","es":"estancarse; toparse con una pared","th":"trouble","lv":"C1","src":["c1-talent5"],"nw":0},{"e":"hit the right note","d":"to do or say something appropriate","x":"The singer's speech [[hit the right note]] with the audience.","es":"dar con el tono justo; dar en el clavo","th":"talk","lv":"C1","src":["c1-music","c1-w-voice5"],"nw":0},{"e":"hot under the collar","d":"angry, annoyed or embarrassed","x":"He got a bit [[hot under the collar]] when the client questioned his numbers.","es":"picado; acalorado","o":"Informal. Describes anger you can see on someone's face, often in an argument or a tense meeting.","th":"feelings","lv":"C1","nw":1,"reg":"informal"},{"e":"imitation is the sincerest form of flattery","d":"people copy you because they admire you (often said ironically)","x":"They copied our slogan word for word. Well, [[imitation is the sincerest form of flattery]].","es":"la imitación es la forma más sincera de halago","th":"people","lv":"C1","src":["c1-w-ip5"],"nw":0},{"e":"in black and white","d":"in writing, so that it is official and clear","x":"The landlord said we could have a cat, but I want it [[in black and white]] before we sign.","es":"por escrito; negro sobre blanco","o":"Also: see things in black and white, meaning to think in simple right-or-wrong terms.","th":"colors","lv":"C1","nw":1},{"e":"in so many words","d":"directly and clearly; often used in the negative to mean only suggested","x":"She didn't say it [[in so many words]], but I could tell she wasn't happy with my report.","es":"con todas sus letras","o":"Most often negative: 'He didn't say it in so many words' means he suggested it without saying it directly.","th":"talk","lv":"C1","nw":1},{"e":"in the black","d":"making a profit; having more money coming in than going out","x":"After two difficult years, the restaurant is finally [[in the black]].","es":"en azul; con números azules","o":"From bookkeeping, where profits were written in black ink and losses in red. The opposite is 'in the red'.","th":"colors","lv":"C1","nw":1},{"e":"in the eye of the beholder","d":"depending on the personal opinion of the person who is looking","x":"Is it beautiful? Well, beauty is [[in the eye of the beholder]].","es":"todo depende del cristal con que se mire","th":"body","lv":"C1","src":["c1-artworld5","c2-aesthetics6"],"nw":0},{"e":"in the pipeline","d":"being planned or developed","x":"New laws on AI are [[in the pipeline]].","es":"en carpeta; en camino","th":"time","lv":"C1","src":["c1-plans"],"nw":0},{"e":"in this day and age","d":"in the modern world; nowadays","x":"[[In this day and age]], it's hard to believe some offices still use fax machines.","es":"en pleno siglo XXI; hoy en día","o":"Often used to express surprise or criticism about something that seems old-fashioned or unfair today.","th":"time","lv":"C1","nw":1},{"e":"jump to conclusions","d":"to decide something too quickly, without all the facts","x":"Don't [[jump to conclusions]] before you see the data.","es":"sacar conclusiones apresuradas","th":"risk","lv":"C1","src":["c1-curious"],"nw":0},{"e":"keep someone at arm's length","d":"to avoid getting too close or friendly with someone","x":"Our new manager is polite but [[keeps everyone at arm's length]], so nobody really knows her.","es":"mantener a alguien a distancia","o":"Often used for colleagues, relatives or companies you don't fully trust. Also: hold someone at arm's length.","th":"body","lv":"C1","nw":1},{"e":"keep tabs on","d":"to watch someone or something carefully, often without them knowing","x":"Some parents use apps to [[keep tabs on]] their teenagers.","es":"seguirle la pista a alguien; tener vigilado","th":"people","lv":"C1","src":["c1-privacy5","c1-w-micro5"],"nw":0},{"e":"keep up with the Joneses","d":"to try to own the same things as your neighbors or friends so you don't look less successful","x":"Social media has turned [[keeping up with the Joneses]] into a full-time job.","es":"no querer ser menos que el vecino; aparentar","th":"people","lv":"C1","src":["c1-minimalism5","c2-w-luxury6"],"nw":0},{"e":"kick the can down the road","d":"to delay dealing with a problem, leaving it for later","x":"If we keep [[kicking the can down the road]], the problem will only get more expensive.","es":"patear el problema para adelante","th":"trouble","lv":"C1","src":["c1-environment","c2-plans","c2-urban6","c1-w-report","c2-w-layoffs6"],"nw":0},{"e":"let sleeping dogs lie","d":"to avoid talking about an old problem because it could cause new trouble","x":"I almost asked my brother about the old family argument, but decided to [[let sleeping dogs lie]].","es":"mejor no alborotar el gallinero; no remover el pasado","o":"Often given as advice: Just let sleeping dogs lie. The problem is quiet now and should stay that way.","th":"animals","lv":"C1","nw":1},{"e":"level the playing field","d":"to make a situation fair so that everyone has the same chance","x":"Sending interview questions in advance helps [[level the playing field]].","es":"emparejar la cancha","th":"sport","lv":"C1","src":["c1-w-neuro5"],"nw":0},{"e":"light-years ahead of","d":"far more advanced than someone or something else","x":"Their navigation software was [[light-years ahead of]] anything we had.","es":"estar a años luz de","th":"success","lv":"C1","src":["c1-spacefuture5"],"nw":0},{"e":"live paycheck to paycheck","d":"to spend all the money you earn each month and have no savings left","x":"Millions of workers [[live paycheck to paycheck]], even with full-time jobs.","es":"vivir al día; llegar con lo justo a fin de mes","th":"money","lv":"C1","src":["c1-gig5"],"nw":0},{"e":"lose sight of","d":"to forget about an important aim because you're busy with other things","x":"In the rush to hit monthly targets, we [[lost sight of]] our customers.","es":"perder de vista","th":"success","lv":"C1","src":["c1-w-future"],"nw":0},{"e":"lose the room","d":"to lose the attention or support of the people you are presenting to","x":"He [[lost the room]] on slide four, when he started reading a table aloud.","es":"perder al público; desconectarse la audiencia","th":"talk","lv":"C1","src":["c1-w-present"],"nw":0},{"e":"lose your train of thought","d":"to forget what you were thinking or saying because something interrupted you","x":"Sorry, the phone rang and I [[lost my train of thought]]. Where was I?","es":"perder el hilo","th":"talk","lv":"C1","src":["c1-w-routine"],"nw":0},{"e":"make a mountain out of a molehill","d":"to treat a small problem as if it were very serious","x":"It's just one bad review — you're [[making a mountain out of a molehill]].","es":"hacer una tormenta en un vaso de agua","o":"A molehill is the small pile of earth a mole leaves. Usually said to calm someone down.","th":"weather","lv":"C1","nw":1},{"e":"make a name for yourself","d":"to become well known and respected in your field","x":"She [[made a name for herself]] as the go-to expert on mining contracts.","es":"hacerse un nombre","th":"success","lv":"C1","src":["c1-w-intro"],"nw":0},{"e":"make headway","d":"to make progress, especially when it is slow or difficult","x":"We're finally [[making headway]] on the kitchen renovation, though there's still a lot to do.","es":"avanzar; hacer progresos","o":"Originally a sailing term for a ship moving forward. Often with 'on' or 'with': make headway on a project.","th":"travel","lv":"C1","nw":1},{"e":"march to the beat of your own drum","d":"to do things your own way, without caring what others think","x":"My aunt has always [[marched to the beat of her own drum]]. She went backpacking around Asia at sixty.","es":"hacer las cosas a su manera; ir a su propio ritmo","th":"people","lv":"C1","src":["c1-personal"],"nw":0},{"e":"mend fences","d":"to repair a relationship after an argument or disagreement","x":"She called her sister the day after the wedding drama to try to [[mend fences]].","es":"limar asperezas; hacer las paces","o":"Common in work, family and diplomacy. Often with 'with': mend fences with a client.","th":"people","lv":"C1","nw":1},{"e":"miss the forest for the trees","d":"to focus so much on details that you don't see the bigger picture","x":"We spent three hours on the font of the report and [[missed the forest for the trees]].","es":"los árboles no dejan ver el bosque","th":"weather","lv":"C1","src":["c1-w-achieve"],"nw":0},{"e":"miss the mark","d":"to fail to have the effect you intended","x":"The campaign was clever, but it completely [[missed the mark]] with older customers.","es":"no dar en el blanco; errar el tiro","th":"success","lv":"C1","src":["c1-w-voice5"],"nw":0},{"e":"money talks","d":"people with money have the most power and influence","x":"The player said he loved the club, but in the end, [[money talks]].","es":"poderoso caballero es don Dinero; la plata manda","th":"money","lv":"C1","src":["c1-fairplay5"],"nw":0},{"e":"more bang for your buck","d":"better value; more benefit for the money or effort you spend","x":"If you buy a used car, you'll get [[more bang for your buck]] than with a new one.","es":"más por tu plata; mejor relación precio-calidad","o":"Informal, American. Usually with 'get': You get more bang for your buck with the bigger package.","th":"money","lv":"C1","nw":1,"reg":"informal"},{"e":"more money than sense","d":"used about someone who spends money in a foolish way","x":"Three thousand dollars for a pair of sneakers? Some people have [[more money than sense]].","es":"tener más plata que sentido común","th":"money","lv":"C1","src":["c1-minimalism5"],"nw":0},{"e":"mum's the word","d":"I will keep this a secret; don't tell anyone","x":"We're planning a surprise party for Javier, so [[mum's the word]], OK?","es":"punto en boca","o":"Here 'mum' means silent, not mother, as in 'keep mum'. Informal and a little old-fashioned, but still used.","th":"talk","lv":"C1","nw":1,"reg":"informal"},{"e":"not hold water","d":"(of an argument or excuse) to seem illogical or unconvincing when you examine it","x":"The claim that solar power is too unreliable for Chile [[doesn't hold water]] anymore.","es":"no sostenerse; no tener asidero","th":"talk","lv":"C1","src":["c1-resources5"],"nw":0},{"e":"off the hook","d":"no longer responsible for something or in trouble","x":"You forgot the wine, but you cooked the main course, so you're [[off the hook]].","es":"salvarse; zafar","th":"trouble","lv":"C1","src":["c1-etiquette5"],"nw":0},{"e":"on borrowed time","d":"still working or existing, but likely to end or fail soon","x":"Our old printer is living [[on borrowed time]] — it jams every single day.","es":"tener los días contados","o":"Often with 'living' or 'running': The project is running on borrowed time. Used for people, machines, jobs and companies.","th":"time","lv":"C1","nw":1},{"e":"on the back burner","d":"postponed or given low priority for now","x":"We've had to put the website redesign [[on the back burner]] until the new budget is approved.","es":"en segundo plano; congelado","o":"The image is a stove: the back burner is for pots that can wait. Opposite: on the front burner.","th":"time","lv":"C1","nw":1},{"e":"on the ropes","d":"close to failing or being defeated","x":"After losing its biggest client, the agency was [[on the ropes]] for most of the year.","es":"contra las cuerdas","o":"From boxing, where a fighter pushed back against the ropes is close to losing. Used for companies, teams and people.","th":"sport","lv":"C1","nw":1},{"e":"one-size-fits-all","d":"designed to suit everyone in the same way, even though people's needs are different","x":"There's no [[one-size-fits-all]] approach to managing people.","es":"talla única; la misma receta para todos","th":"people","lv":"C1","src":["c1-w-neuro5"],"nw":0},{"e":"open Pandora's box","d":"to start something that will cause many problems nobody expected","x":"Allowing gene editing for cosmetic reasons could [[open Pandora's box]].","es":"abrir la caja de Pandora","th":"trouble","lv":"C1","src":["c1-genetics5"],"nw":0},{"e":"out of left field","d":"completely unexpected or strange","x":"Her question about my salary came [[out of left field]], and I didn't know what to say.","es":"de la nada; totalmente inesperado","o":"American, from baseball. Used for ideas, questions or events that take you by surprise.","th":"sport","lv":"C1","nw":1},{"e":"out of sorts","d":"slightly unwell, tired or in a bad mood","x":"Sorry I'm so quiet today; I've been feeling [[out of sorts]] since I got back from my trip.","es":"andar decaído; no sentirse muy bien","o":"A mild expression: not really sick or angry, just not your usual self.","th":"feelings","lv":"C1","nw":1},{"e":"out of the frying pan into the fire","d":"from a bad situation into an even worse one","x":"I left my stressful job for a startup that went bankrupt — [[out of the frying pan into the fire]].","es":"de mal en peor; salir de Guatemala y meterse en Guatepeor","o":"Often with 'jump' or 'go': I jumped out of the frying pan into the fire.","th":"trouble","lv":"C1","nw":1},{"e":"paint a picture (of)","d":"to describe something so that people can clearly imagine or understand it","x":"These figures [[paint a worrying picture]] of our cash flow.","es":"pintar un panorama; dar una imagen de algo","th":"talk","lv":"C1","src":["c1-w-trends"],"nw":0},{"e":"par for the course","d":"normal and expected, especially when it is something bad","x":"Delays on that train line are [[par for the course]], so I always leave early.","es":"lo normal; el pan de cada día","o":"From golf, where 'par' is the expected number of strokes. Usually describes something disappointing but typical.","th":"sport","lv":"C1","nw":1},{"e":"pass the buck","d":"to make someone else deal with a problem that you should deal with yourself","x":"Every time a client complains, the managers [[pass the buck]] to the call center.","es":"tirarle la pelota a otro; lavarse las manos","th":"trouble","lv":"C1","src":["c2-ethics","c1-w-role"],"nw":0},{"e":"pave the way for","d":"to make something possible in the future","x":"These discoveries [[pave the way for]] new medicines.","es":"abrir el camino a; allanar el camino para","th":"travel","lv":"C1","src":["c1-plans"],"nw":0},{"e":"pay dividends","d":"to bring benefits or advantages later","x":"All those hours practicing English [[paid dividends]] at her first international meeting.","es":"dar frutos","o":"A dividend is money a company pays its shareholders. Used for effort, training or investment that is rewarded over time.","th":"money","lv":"C1","nw":1},{"e":"phone it in","d":"to do something with minimum effort and no real interest","x":"His last two reports were full of errors. He's clearly [[phoning it in]].","es":"hacer las cosas por cumplir","th":"success","lv":"C1","src":["c1-w-quietquit5"],"nw":0},{"e":"pick holes in","d":"to find faults and weaknesses in an idea or an argument","x":"The finance team [[picked holes in]] our proposal, and they were right.","es":"ponerle peros a algo; buscarle las fallas","th":"talk","lv":"C1","src":["c1-w-opinions"],"nw":0},{"e":"play God","d":"to make decisions about life and nature that some people think humans shouldn't make","x":"Critics accuse researchers of [[playing God]] when they edit human embryos.","es":"jugar a ser Dios","th":"risk","lv":"C1","src":["c1-genetics5","c2-bioethics6"],"nw":0},{"e":"play hardball","d":"to act in a tough, determined way to get what you want, especially in negotiations","x":"If the supplier won't lower its prices, we'll have to [[play hardball]] and look elsewhere.","es":"ponerse duro; jugar fuerte","o":"American, from baseball (hardball is the regular game, as opposed to softball). Common in business and law.","th":"sport","lv":"C1","nw":1},{"e":"play it safe","d":"to avoid risks and choose the careful option","x":"With an exam tomorrow, I'll [[play it safe]] and stay home tonight.","es":"ir a la segura; no arriesgarse","th":"risk","lv":"C1","src":["c1-risk5"],"nw":0},{"e":"play the long game","d":"to accept slower results now in order to succeed in the future","x":"Our competitors are cutting prices, but we're [[playing the long game]] and investing in quality.","es":"apostar al largo plazo","th":"sport","lv":"C1","src":["c2-strategy6","c1-w-future"],"nw":0},{"e":"pour cold water on","d":"to criticize a plan or idea so that people feel less enthusiastic about it","x":"My boss [[poured cold water on]] my plan to put solar panels on the office roof.","es":"echarle un balde de agua fría a algo","th":"weather","lv":"C1","src":["c1-resources5"],"nw":0},{"e":"practice what you preach","d":"to do the things you tell other people they should do","x":"If you want your team to switch off on weekends, [[practice what you preach]] and stop sending emails on Sunday.","es":"predicar con el ejemplo","th":"people","lv":"C1","src":["c1-corpculture5"],"nw":0},{"e":"preach to the choir","d":"to try to persuade people who already agree with you","x":"Posting about it on your own page is just [[preaching to the choir]].","es":"predicarles a los convencidos","th":"talk","lv":"C1","src":["c1-negotiation","c2-media","c2-w-present"],"nw":0},{"e":"press the flesh","d":"to meet and shake hands with a lot of people, especially to build contacts","x":"At the trade fair, our CEO spent three days [[pressing the flesh]].","es":"estrechar manos; saludar a medio mundo","th":"body","lv":"C1","src":["c1-w-trips"],"nw":0},{"e":"price yourself out of the market","d":"to charge so much that customers stop buying from you","x":"If we raise our rates again, we'll [[price ourselves out of the market]].","es":"quedar fuera del mercado por caro","th":"money","lv":"C1","src":["c1-w-inflation5"],"nw":0},{"e":"pull the plug (on)","d":"to stop a project or activity, especially because it isn't working","x":"After a year of losses, the board [[pulled the plug on]] the new store.","es":"ponerle fin a algo; bajar la cortina","th":"success","lv":"C1","src":["c1-w-past"],"nw":0},{"e":"pull your punches","d":"to criticize someone less strongly than you could","x":"The auditor didn't [[pull her punches]]: she called our controls 'chaotic.'","es":"suavizar las críticas; (en negativo) no tener pelos en la lengua","th":"sport","lv":"C1","src":["c1-w-candor5"],"nw":0},{"e":"punch above your weight","d":"to compete or succeed at a level that seems beyond your size or ability","x":"Our small agency [[punches above its weight]] against the big international firms.","es":"competir de igual a igual con los grandes; rendir más de lo esperado","th":"sport","lv":"C1","src":["c2-influence6","c1-w-imposter5"],"nw":0},{"e":"push the envelope","d":"to go beyond normal limits","x":"That comedian always [[pushes the envelope]].","es":"ir más allá de los límites; romper esquemas","th":"risk","lv":"C1","src":["c1-humor","c2-aiart6"],"nw":0},{"e":"put a positive spin on","d":"to present information in a way that makes it look better than it is","x":"The report tried to [[put a positive spin on]] a terrible quarter.","es":"darle un giro positivo; maquillar la realidad","th":"talk","lv":"C1","src":["c1-w-pr5","c2-w-trends"],"nw":0},{"e":"put in a good word for","d":"to say positive things about someone in order to help them","x":"I'll [[put in a good word for]] you with the purchasing manager.","es":"hablar bien de alguien; recomendar a alguien","th":"talk","lv":"C1","src":["c1-w-calls"],"nw":0},{"e":"put in your two cents","d":"to give your opinion, even if no one has asked for it","x":"Everyone in my family likes to [[put in their two cents]] about how I raise my kids.","es":"dar tu opinión; meter tu cuchara","o":"American. Also: 'Just my two cents', said after giving an opinion, often modestly.","th":"talk","lv":"C1","nw":1,"reg":"informal","uk":"UK: put in your two pennies' worth"},{"e":"put out fires","d":"to deal with one urgent problem after another instead of planning ahead","x":"I spend so much time [[putting out fires]] that I never get to the strategic work.","es":"apagar incendios","th":"trouble","lv":"C1","src":["c1-w-problems"],"nw":0},{"e":"put someone out to pasture","d":"to make someone stop working because they are considered too old","x":"He was [[put out to pasture]] at sixty, even though he was still the best engineer on the team.","es":"jubilar a alguien a la fuerza; dejar a alguien en la banca","th":"animals","lv":"C1","src":["c1-aging5","c2-w-career"],"nw":0},{"e":"put the cart before the horse","d":"to do things in the wrong order","x":"Buying furniture before you've even found an apartment is [[putting the cart before the horse]].","es":"empezar la casa por el tejado","o":"Used to criticize plans that skip a necessary first step. Often: Let's not put the cart before the horse.","th":"animals","lv":"C1","nw":1},{"e":"put yourself out there","d":"to accept the risk of being seen, judged or rejected in order to get opportunities","x":"Publishing my first article was scary, but sometimes you have to [[put yourself out there]].","es":"exponerse; atreverse a mostrarse","th":"risk","lv":"C1","src":["c1-w-intro"],"nw":0},{"e":"read someone the riot act","d":"to warn someone angrily that they must stop behaving badly","x":"After the third complaint, the manager [[read us the riot act]] about being late.","es":"leerle la cartilla a alguien","o":"From the British Riot Act of 1714, which officials read aloud to order crowds to break up.","th":"talk","lv":"C1","nw":1},{"e":"rest on your laurels","d":"to stop making an effort because you are satisfied with past success","x":"We're the market leader, but we can't afford to [[rest on our laurels]].","es":"dormirse en los laureles","th":"success","lv":"C1","src":["c1-innovation5","c2-ambition6","c2-w-die6"],"nw":0},{"e":"rock the boat","d":"to cause problems by challenging the way things are done","x":"New hires are often afraid to [[rock the boat]] in their first few months.","es":"agitar las aguas; causar problemas","th":"travel","lv":"C1","src":["c1-corpculture5","c2-change6","c2-w-opinions"],"nw":0},{"e":"roll the dice","d":"to take a chance and hope that things turn out well","x":"We had no guarantees, but we [[rolled the dice]] and moved the whole family to Canada.","es":"probar suerte; arriesgarse","o":"Common in business and sports: roll the dice on a new product or a young player. Noun: a roll of the dice.","th":"risk","lv":"C1","nw":1},{"e":"ruffle someone's feathers","d":"to annoy or upset someone, often without meaning to","x":"Her blunt comments in the meeting [[ruffled a few feathers]] in the sales department.","es":"pisar callos; incomodar a alguien","o":"Often 'ruffle a few feathers', especially by questioning how things are done. Opposite: smooth someone's ruffled feathers.","th":"animals","lv":"C1","nw":1},{"e":"running on empty","d":"continuing to work or function with no energy left","x":"After three months without a vacation, the whole team was [[running on empty]].","es":"andar con las pilas descargadas; estar sin energía","th":"travel","lv":"C1","src":["c1-w-mental5"],"nw":0},{"e":"second nature","d":"something you do automatically","x":"After years of practice, it's [[second nature]].","es":"algo automático; una segunda naturaleza","th":"success","lv":"C1","src":["c1-hobbies","c2-hobbies"],"nw":0},{"e":"see which way the wind is blowing","d":"to find out what people think or what will probably happen before you decide","x":"Let's [[see which way the wind is blowing]] at Monday's meeting before we commit to anything.","es":"ver para dónde sopla el viento; ver para dónde va la micro","o":"Used about opinions, trends and office politics, often to delay a decision. Also: know which way the wind blows.","th":"weather","lv":"C1","nw":1},{"e":"shed light on","d":"to help explain something","x":"New research [[sheds light on]] how memory works.","es":"arrojar luz sobre; aclarar","th":"talk","lv":"C1","src":["c1-curious"],"nw":0},{"e":"shift gears","d":"to change your approach, activity or focus, often quickly","x":"Okay, let's [[shift gears]] and talk about next quarter's marketing plan.","es":"cambiar el chip; pasar a otra cosa","o":"American. Common in meetings to move to a new topic. Also: switch gears.","th":"travel","lv":"C1","nw":1,"uk":"UK: change gear"},{"e":"sing someone's praises","d":"to praise someone a lot and with enthusiasm, especially to other people","x":"Your old boss was [[singing your praises]] when I called for a reference.","es":"hablar maravillas de alguien; deshacerse en elogios","o":"Also used for things, usually as 'sing the praises of': Everyone's singing the praises of the new system.","th":"talk","lv":"C1","nw":1},{"e":"skin in the game","d":"a personal financial stake in the success of something","x":"Investors like founders who've put their own money in: real [[skin in the game]].","es":"tener algo en juego; arriesgar plata propia","th":"body","lv":"C1","src":["c1-w-vc5"],"nw":0},{"e":"smell a rat","d":"to begin to suspect that something is wrong or dishonest","x":"When the 'bank' asked for my password, I [[smelled a rat]].","es":"olerse algo raro; aquí hay gato encerrado","th":"animals","lv":"C1","src":["c1-w-cyber5","c2-w-details"],"nw":0},{"e":"smooth sailing","d":"easy progress without any problems","x":"Once we got the permits, it was [[smooth sailing]] all the way to opening day.","es":"viento en popa; sin contratiempos","o":"Often after a difficult start: Once we fixed the bug, it was smooth sailing.","th":"travel","lv":"C1","nw":1,"uk":"UK: plain sailing"},{"e":"speak the same language","d":"to share the same ideas, attitudes or way of thinking","x":"My new boss and I really [[speak the same language]].","es":"hablar el mismo idioma","th":"talk","lv":"C1","src":["c1-langculture5"],"nw":0},{"e":"split hairs","d":"to argue about very small differences that don't really matter","x":"Let's not [[split hairs]] over a two-dollar difference.","es":"hilar demasiado fino; discutir por detalles","th":"body","lv":"C1","src":["c2-ethics","c1-w-details"],"nw":0},{"e":"stay ahead of the curve","d":"to anticipate changes and stay more advanced than others","x":"Short courses help you [[stay ahead of the curve]].","es":"estar a la vanguardia; adelantarse a los cambios","th":"success","lv":"C1","src":["c1-careers"],"nw":0},{"e":"stick out like a sore thumb","d":"to look completely different from everything around it, in a bad way","x":"In my jeans and sneakers, I [[stuck out like a sore thumb]] at the formal dinner.","es":"ser sapo de otro pozo; notarse a la legua","th":"body","lv":"C1","src":["c1-architecture5","c2-w-rules"],"nw":0},{"e":"strike a chord with","d":"to make people feel emotion or a personal connection","x":"His story about failing in his first business [[struck a chord with]] the audience.","es":"tocar una fibra sensible; llegarle a alguien","th":"feelings","lv":"C1","src":["c1-presentations"],"nw":0},{"e":"sweep something under the rug","d":"to hide a problem instead of dealing with it","x":"You can't just [[sweep the complaints under the rug]] and hope they disappear.","es":"esconder algo debajo de la alfombra","th":"trouble","lv":"C1","src":["c1-workplace"],"nw":0},{"e":"take it with a grain of salt","d":"to not completely believe something","x":"He exaggerates a lot, so [[take his stories with a grain of salt]].","es":"tomarlo con pinzas","th":"food","lv":"C1","src":["c1-humor"],"nw":0},{"e":"take something on the chin","d":"to accept criticism or a setback without complaining","x":"The project lead [[took the criticism on the chin]] and fixed the plan by Friday.","es":"aguantar el golpe; asumirlo sin quejarse","th":"body","lv":"C1","src":["c1-w-candor5"],"nw":0},{"e":"take the sting out of","d":"to make something unpleasant less upsetting or hurtful","x":"Acknowledging people's frustration first [[takes the sting out of]] a hostile question.","es":"suavizar algo; bajarle el tono a algo","th":"feelings","lv":"C1","src":["c1-w-toughq5"],"nw":0},{"e":"take the wind out of someone's sails","d":"to make someone suddenly lose confidence or enthusiasm","x":"Her cold reply to my proposal really [[took the wind out of my sails]].","es":"desinflar a alguien; quitarle el impulso","o":"The image is a sailboat that stops when the wind is blocked. Often used for criticism or bad news.","th":"weather","lv":"C1","nw":1},{"e":"tempt fate","d":"to do or say something risky that might bring bad luck","x":"I don't want to [[tempt fate]], but I think we might actually finish on time.","es":"tentar a la suerte","o":"Often said just before a hopeful prediction, as a kind of superstition, or as a warning: Don't tempt fate.","th":"risk","lv":"C1","nw":1},{"e":"that's the way the cookie crumbles","d":"that's how things happen, and nothing can be done about it","x":"We lost the contract to a cheaper company — [[that's the way the cookie crumbles]].","es":"así es la vida; son cosas que pasan","o":"Informal, mainly American. Said to accept bad luck calmly. Similar: that's life.","th":"food","lv":"C1","nw":1,"reg":"informal"},{"e":"the apple doesn't fall far from the tree","d":"children are usually similar to their parents in character or behavior","x":"Her dad was a chef and now she runs a bakery — [[the apple doesn't fall far from the tree]].","es":"de tal palo, tal astilla","o":"Can be a compliment or a criticism, depending on what the parent and child have in common.","th":"people","lv":"C1","nw":1},{"e":"the bottom line","d":"the most important fact or result, often about money","x":"[[The bottom line]] is that we need a second warehouse within a year.","es":"en resumidas cuentas; lo esencial","th":"money","lv":"C1","src":["c1-w-present"],"nw":0},{"e":"the crown jewels","d":"the most valuable assets that an organization owns","x":"Our customer database is [[the crown jewels]]; only three people can access all of it.","es":"la joya de la corona","th":"money","lv":"C1","src":["c1-w-ip5"],"nw":0},{"e":"the die is cast","d":"a decision has been made and it cannot be changed now","x":"I've handed in my resignation, so [[the die is cast]].","es":"la suerte está echada","o":"Attributed to Julius Caesar (Latin 'alea iacta est'). 'Die' is the singular of 'dice'.","th":"risk","lv":"C1","nw":1},{"e":"the emperor's new clothes","d":"something everyone praises although it has no real value, because nobody dares to say so","x":"Some critics called the exhibition a case of [[the emperor's new clothes]].","es":"el traje nuevo del emperador","th":"people","lv":"C1","src":["c1-artworld5","c2-authenticity6"],"nw":0},{"e":"the genie is out of the bottle","d":"something has happened that can't be reversed or brought back under control","x":"Now that the technology is cheap, [[the genie is out of the bottle]].","es":"ya no hay vuelta atrás; el genio salió de la botella","th":"trouble","lv":"C1","src":["c1-genetics5"],"nw":0},{"e":"the good old days","d":"a time in the past that people remember as better than the present","x":"My uncle is always talking about [[the good old days]], when concerts were cheap.","es":"los buenos tiempos; todo tiempo pasado fue mejor","th":"time","lv":"C1","src":["c1-nostalgia5"],"nw":0},{"e":"the lesser of two evils","d":"the less harmful of two bad options","x":"Closing one branch to save the other three was [[the lesser of two evils]].","es":"el mal menor","th":"risk","lv":"C1","src":["c1-ethics"],"nw":0},{"e":"the lion's share","d":"the biggest part of something","x":"[[The lion's share]] of the funding will go to product development.","es":"la parte del león; la mayor parte","th":"animals","lv":"C1","src":["c1-w-vc5","c2-w-execpay6"],"nw":0},{"e":"the Midas touch","d":"the ability to make money or succeed in everything you do","x":"Everything she invests in seems to make money; she really has [[the Midas touch]].","es":"el toque de Midas","o":"From the Greek myth of King Midas, who turned everything he touched into gold. Usually with 'have'.","th":"success","lv":"C1","nw":1},{"e":"the million-dollar question","d":"the most important question, which nobody can answer yet","x":"Will the new tariffs affect our exports? That's [[the million-dollar question]].","es":"la pregunta del millón","th":"money","lv":"C1","src":["c1-w-toughq5"],"nw":0},{"e":"the path of least resistance","d":"the easiest option, which people often choose even when it isn't the best one","x":"Checking messages is tempting because it's [[the path of least resistance]].","es":"el camino más fácil; la ley del mínimo esfuerzo","th":"travel","lv":"C1","src":["c2-meetings","c1-w-routine"],"nw":0},{"e":"the pot calling the kettle black","d":"criticizing someone for a fault that you also have","x":"Tom said I talk too much in meetings — talk about [[the pot calling the kettle black]]!","es":"el burro hablando de orejas","o":"Usually said as a reaction: That's the pot calling the kettle black! A little humorous.","th":"colors","lv":"C1","nw":1},{"e":"the rat race","d":"the tiring, competitive struggle to earn more money and status","x":"Lots of people dream of escaping [[the rat race]] and opening a café by the beach.","es":"la vorágine laboral; la competencia del día a día","th":"animals","lv":"C1","src":["c1-happiness5"],"nw":0},{"e":"the time is ripe","d":"it is the right moment to do something","x":"With interest rates falling, [[the time is ripe]] to refinance your mortgage.","es":"es el momento propicio; llegó la hora","o":"Usually followed by 'for' or 'to': The time is ripe for change. A little formal.","th":"time","lv":"C1","nw":1},{"e":"the weakest link","d":"the part of a system or team that is most likely to fail and cause problems","x":"In most attacks, a tired, rushed employee is [[the weakest link]].","es":"el eslabón más débil","th":"trouble","lv":"C1","src":["c1-w-cyber5"],"nw":0},{"e":"there's no silver bullet","d":"there is no single, simple solution to a complex problem","x":"[[There's no silver bullet]] for climate change; we need a mix of policies.","es":"no hay fórmulas mágicas","th":"trouble","lv":"C1","src":["c1-environment"],"nw":0},{"e":"throw a wrench into something","d":"to cause a problem that stops a plan from working smoothly","x":"The sudden flight cancellation [[threw a wrench into]] our vacation plans.","es":"poner palos en la rueda","o":"American. Also: throw a monkey wrench into the works. A wrench is a tool for turning nuts and bolts.","th":"trouble","lv":"C1","nw":1,"uk":"UK: put a spanner in the works"},{"e":"throw caution to the wind","d":"to stop worrying about danger and do something bold","x":"We [[threw caution to the wind]] and spent all our savings on a trip around the world.","es":"dejar la prudencia de lado; lanzarse sin pensarlo","th":"weather","lv":"C1","src":["c1-risk5"],"nw":0},{"e":"throw good money after bad","d":"to keep spending money on something that is already failing","x":"Another upgrade for that old system would be [[throwing good money after bad]].","es":"seguir botando plata en algo perdido","th":"money","lv":"C1","src":["c1-w-decisions"],"nw":0},{"e":"throw someone under the bus","d":"to blame someone else, or let them take the blame, to protect yourself","x":"When the launch failed, he [[threw his own team under the bus]].","es":"echarle la culpa a otro para salvarse; tirar a alguien a los leones","th":"travel","lv":"C1","src":["c1-workplace","c1-w-toxic5","c2-w-past"],"nw":0},{"e":"throw the baby out with the bathwater","d":"to get rid of something good while trying to get rid of something bad","x":"Exams have their problems, but scrapping them entirely would be [[throwing the baby out with the bathwater]].","es":"tirar al niño junto con el agua sucia; botar lo bueno con lo malo","th":"risk","lv":"C1","src":["c1-edreform5","c2-environment","c2-futureorgs6","c1-w-process"],"nw":0},{"e":"time is of the essence","d":"it is very important to act quickly","x":"Please send the signed documents today — [[time is of the essence]].","es":"el tiempo apremia; no hay tiempo que perder","o":"Formal. Common in business emails, legal language and emergencies.","th":"time","lv":"C1","nw":1,"reg":"formal"},{"e":"tip the scales","d":"to be the factor that decides the result","x":"Their after-sales service [[tipped the scales]] in their favor.","es":"inclinar la balanza","th":"risk","lv":"C1","src":["c1-negotiation"],"nw":0},{"e":"to put it mildly","d":"used to say the real situation is much worse or stronger than your words","x":"The first day with the new software was chaotic, [[to put it mildly]].","es":"por decirlo suavemente; por no decir otra cosa","o":"A form of understatement, often humorous. Similar: to say the least.","th":"talk","lv":"C1","nw":1},{"e":"toe the line","d":"to follow the official position or the rules, even if you disagree","x":"Managers are expected to [[toe the line]] in public.","es":"alinearse; acatar la línea oficial","th":"body","lv":"C1","src":["c1-w-opinions"],"nw":0},{"e":"tongue-in-cheek","d":"said ironically, not seriously","x":"His review of the movie was totally [[tongue-in-cheek]].","es":"en tono irónico; medio en broma","th":"body","lv":"C1","src":["c1-humor","c2-humor","c2-w-irony6"],"nw":0},{"e":"too little, too late","d":"an action that isn't enough and comes after it could have helped","x":"The apology came a month later, and most customers saw it as [[too little, too late]].","es":"muy poco y demasiado tarde","th":"time","lv":"C1","src":["c1-w-apology5"],"nw":0},{"e":"toot your own horn","d":"to boast about your achievements","x":"He's talented, but he loves [[tooting his own horn]].","es":"echarse flores","th":"talk","lv":"C1","src":["c1-music","c1-w-pr5"],"nw":0},{"e":"trim the fat","d":"to remove the parts of something that are unnecessary or wasteful","x":"The new manager [[trimmed the fat]] by canceling three pointless weekly meetings.","es":"recortar lo que sobra; eliminar gastos innecesarios","th":"food","lv":"C1","src":["c1-w-stock"],"nw":0},{"e":"turn the tide","d":"to change a situation completely, usually from bad to good","x":"The new marketing campaign helped [[turn the tide]] after three years of falling sales.","es":"dar vuelta la situación; cambiar el rumbo","o":"Common in news, sports and history. Also: the tide is turning, meaning a change has started.","th":"weather","lv":"C1","nw":1},{"e":"walking on air","d":"extremely happy and excited","x":"Ever since she got the acceptance letter from the university, she's been [[walking on air]].","es":"no caber de felicidad; estar feliz de la vida","o":"Used after very good news: a new job, a new relationship, a big win. Also: floating on air.","th":"feelings","lv":"C1","nw":1},{"e":"weather the storm","d":"to survive a difficult period without serious damage","x":"Thanks to its loyal customers, the hotel [[weathered the storm]].","es":"capear el temporal","th":"weather","lv":"C1","src":["c1-crisis5"],"nw":0},{"e":"worth its weight in gold","d":"extremely useful or valuable","x":"A local contact who knows the regulations is [[worth their weight in gold]].","es":"valer oro; valer su peso en oro","th":"money","lv":"C1","src":["c1-w-trips","c2-w-trustasset6"],"nw":0},{"e":"worth your salt","d":"good at your job and deserving respect","x":"Any accountant [[worth her salt]] would have spotted that mistake immediately.","es":"que se precie","o":"Usually in the pattern 'any teacher/doctor/chef worth their salt' + would or should.","th":"food","lv":"C1","nw":1},{"e":"a badge of honor","d":"something people are proud of, although it may not really deserve admiration","x":"In some firms, never taking a vacation is worn as [[a badge of honor]].","es":"un motivo de orgullo; una medalla de honor","th":"success","lv":"C2","src":["c2-w-busy6"],"nw":0},{"e":"a bitter pill to swallow","d":"an unpleasant fact or situation that is hard to accept","x":"Losing their bonuses was [[a bitter pill to swallow]] for the sales team.","es":"un trago amargo","th":"feelings","lv":"C2","src":["c2-w-layoffs6"],"nw":0},{"e":"a blank slate","d":"a mind with no inborn ideas or tendencies, shaped entirely by experience","x":"Modern psychology rejects the idea that children arrive as [[a blank slate]].","es":"una tabla rasa; una hoja en blanco","th":"people","lv":"C2","src":["c2-naturenurture6"],"nw":0},{"e":"a blue-ribbon panel","d":"a group of top experts chosen to study a problem and give official advice","x":"The governor appointed [[a blue-ribbon panel]] to investigate why the new hospital was two years late.","es":"una comisión de expertos de alto nivel","o":"American. Also: a blue-ribbon commission. A blue ribbon is the traditional first prize at American fairs and competitions.","th":"colors","lv":"C2","nw":1},{"e":"a catch-22","d":"a situation you can't escape because each solution depends on the other","x":"It's [[a catch-22]]: you need experience to get a job, but you need a job to get experience.","es":"un círculo vicioso; un callejón sin salida","th":"trouble","lv":"C2","src":["c2-curious"],"nw":0},{"e":"a charm offensive","d":"a deliberate campaign of friendliness designed to win approval","x":"The new ambassador launched [[a charm offensive]], appearing at every concert and food fair in town.","es":"una ofensiva de simpatía; una campaña para caer bien","th":"people","lv":"C2","src":["c2-softpower6"],"nw":0},{"e":"a chicken-and-egg question","d":"a situation where it's impossible to say which of two things caused the other","x":"Do we lack the word because we lack the concept? It's [[a chicken-and-egg question]].","es":"el dilema del huevo o la gallina","th":"animals","lv":"C2","src":["c2-language6"],"nw":0},{"e":"a chip off the old block","d":"a person who is very similar to their parent in character or behavior","x":"Watching her argue with the referee, I thought: she's [[a chip off the old block]].","es":"de tal palo, tal astilla","th":"people","lv":"C2","src":["c2-naturenurture6"],"nw":0},{"e":"a dog and pony show","d":"an elaborate presentation or event designed mainly to impress people, often with little real substance","x":"The investors didn't want another [[dog and pony show]]; they wanted to see real sales numbers.","es":"puro show; una puesta en escena para impresionar","o":"American and usually disapproving. From small traveling circuses whose main attractions were trained dogs and ponies.","th":"animals","lv":"C2","nw":1},{"e":"a fair-weather friend","d":"a person who is only your friend when things are going well","x":"When I lost my job, I quickly found out who the [[fair-weather friends]] were.","es":"amigo de los buenos tiempos; amigo por conveniencia","th":"weather","lv":"C2","src":["c2-relationships"],"nw":0},{"e":"a foregone conclusion","d":"a result that is certain even before something begins","x":"Once her main rival withdrew, her promotion was [[a foregone conclusion]].","es":"algo cantado; un resultado previsible","th":"risk","lv":"C2","src":["c2-freewill6"],"nw":0},{"e":"a game of whack-a-mole","d":"a situation where solving one problem makes another appear somewhere else","x":"Fixing these bugs one by one is [[a game of whack-a-mole]].","es":"un cuento de nunca acabar; resolver un problema y que salte otro","th":"sport","lv":"C2","src":["c2-w-problems"],"nw":0},{"e":"a gilded cage","d":"a comfortable, privileged situation that limits your freedom","x":"For him, the high-paying corporate job had become [[a gilded cage]].","es":"una jaula de oro","th":"money","lv":"C2","src":["c2-ambition6"],"nw":0},{"e":"a goldfish bowl","d":"a situation in which you have no privacy because everyone can see what you're doing","x":"With glass walls on every side, the new meeting room is [[a goldfish bowl]].","es":"una pecera; estar a la vista de todos","th":"animals","lv":"C2","src":["c2-w-space"],"nw":0},{"e":"a horse of a different color","d":"a completely different matter from the one being discussed","x":"Working from home on Fridays is one thing; working from another country is [[a horse of a different color]].","es":"harina de otro costal","o":"Mainly American. Many people know it from the color-changing horse in the 1939 film The Wizard of Oz.","th":"colors","lv":"C2","nw":1,"uk":"UK: a different kettle of fish"},{"e":"a hostage to fortune","d":"a statement or commitment that could cause you serious problems later","x":"Promising zero layoffs in writing was [[a hostage to fortune]].","es":"un compromiso que se te puede volver en contra","th":"risk","lv":"C2","src":["c2-w-investors6"],"nw":0},{"e":"a king's ransom","d":"a very large amount of money","x":"We paid [[a king's ransom]] for that downtown apartment, and now prices have dropped twenty percent.","es":"un dineral; una fortuna","o":"Slightly formal or humorous. Common with pay, cost, spend or be worth: “It cost a king's ransom.”","th":"money","lv":"C2","nw":1},{"e":"a law unto yourself","d":"someone who does what they want and ignores normal rules and customs","x":"Our sales director is [[a law unto herself]]: she sets her own hours and never fills out reports.","es":"hacer lo que se le antoja; no seguir ninguna regla","o":"Can express frustration or reluctant admiration. The pronoun changes: a law unto himself, herself or themselves.","th":"people","lv":"C2","nw":1},{"e":"a leg up","d":"help that gives someone an advantage, especially at the start of something","x":"Growing up bilingual gave him a real [[leg up]] in his career.","es":"un empujón; una ventaja para partir","th":"body","lv":"C2","src":["c2-w-merit6"],"nw":0},{"e":"a lone wolf","d":"a person who prefers to work or live independently, without others","x":"She's always been a bit of [[a lone wolf]]; she does her best work alone.","es":"un lobo solitario","th":"animals","lv":"C2","src":["c2-solitude6"],"nw":0},{"e":"a marriage of convenience","d":"a partnership formed for practical advantage rather than real friendship or love","x":"The merger was [[a marriage of convenience]]: one company had the cash, and the other had the customers.","es":"un matrimonio por conveniencia; una alianza por interés","o":"Used literally for marriages, but today more often for business or political alliances between unlikely partners.","th":"people","lv":"C2","nw":1},{"e":"a Monday-morning quarterback","d":"someone who criticizes other people's decisions after already knowing how things turned out","x":"It's easy to be [[a Monday-morning quarterback]] now that we know the launch failed, but nobody objected at the time.","es":"opinar a toro pasado","o":"American. Football games are played on the weekend, and fans criticize the quarterback's choices on Monday. Also a verb.","th":"sport","lv":"C2","nw":1},{"e":"a new lease on life","d":"a fresh burst of energy, health or enthusiasm after a difficult period","x":"Moving to the coast gave my father [[a new lease on life]].","es":"un segundo aire; volver a nacer","th":"feelings","lv":"C2","src":["c2-health","c2-w-career"],"nw":0},{"e":"a one-trick pony","d":"a person or company with only one skill or product and very little else","x":"The startup was [[a one-trick pony]], and when its app went out of fashion, it collapsed.","es":"alguien que solo sabe hacer una cosa; una empresa de un solo producto","th":"animals","lv":"C2","src":["c2-w-skills"],"nw":0},{"e":"a poisoned chalice","d":"a job or reward that seems attractive but is likely to cause serious problems for whoever accepts it","x":"Leading the failing division turned out to be [[a poisoned chalice]].","es":"un regalo envenenado","th":"trouble","lv":"C2","src":["c2-w-achieve"],"nw":0},{"e":"a Pyrrhic victory","d":"a success that has cost so much that it's hardly worth having","x":"Winning the contract at that price was [[a Pyrrhic victory]]: we lost money on every unit.","es":"una victoria pírrica","th":"success","lv":"C2","src":["c2-w-achieve"],"nw":0},{"e":"a rising tide lifts all boats","d":"when the economy or a group does well, everyone involved benefits","x":"The mayor argued that the new port would help everyone—[[a rising tide lifts all boats]]—but local fishermen weren't convinced.","es":"si a la economía le va bien, a todos les va bien","o":"Associated with President John F. Kennedy; often quoted, sometimes skeptically, in debates about economic growth and who really benefits.","th":"weather","lv":"C2","nw":1},{"e":"a rule of thumb","d":"a simple, practical method based on experience rather than exact calculation","x":"A useful [[rule of thumb]] is that customers rarely notice price changes under five percent.","es":"una regla práctica; por regla general","th":"body","lv":"C2","src":["c2-w-behavioral6"],"nw":0},{"e":"a sacred cow","d":"a belief or tradition that people think must never be criticized","x":"In our office, the Friday barbecue is [[a sacred cow]]; nobody dares to cancel it.","es":"una vaca sagrada; algo intocable","th":"animals","lv":"C2","src":["c2-food"],"nw":0},{"e":"a sea change","d":"a complete and important shift in attitudes, opinions or a situation","x":"There's been [[a sea change]] in how companies view remote work; five years ago, most managers wouldn't even discuss it.","es":"un cambio radical; un vuelco total","o":"From Shakespeare's The Tempest. Common in news and business writing; stronger and more formal than “a big change.”","th":"weather","lv":"C2","nw":1},{"e":"a song and dance","d":"in American English, a long, complicated explanation or excuse meant to avoid the truth","x":"I asked why my refund was late and got [[a song and dance]] about “system upgrades.”","es":"un cuento (para no decir la verdad)","o":"In British English, “make a song and dance about something” means to make an unnecessary fuss.","th":"talk","lv":"C2","nw":1,"reg":"informal","uk":"UK: make a song and dance (about something) = make a fuss"},{"e":"a Swiss Army knife","d":"someone who is useful in many different situations because of their wide range of skills","x":"Our office manager is [[a Swiss Army knife]]: she does payroll, IT support and event planning.","es":"un comodín; un todoterreno","th":"people","lv":"C2","src":["c2-w-skills"],"nw":0},{"e":"a tempest in a teapot","d":"a lot of anger or excitement about something unimportant","x":"The fuss over the new logo turned out to be [[a tempest in a teapot]].","es":"una tormenta en un vaso de agua","th":"weather","lv":"C2","src":["c2-w-viral6"],"nw":0},{"e":"a tough crowd","d":"an audience or group of people that is very hard to impress","x":"Engineers can be [[a tough crowd]] if your data isn't solid.","es":"un público difícil","th":"people","lv":"C2","src":["c2-w-intro"],"nw":0},{"e":"a whistle-stop tour","d":"a fast trip with many short visits to different places","x":"Our CEO made [[a whistle-stop tour]] of the regional offices: Lima, Bogotá and Santiago in four days.","es":"una gira relámpago","o":"From small American train stations where trains stopped only on signal; politicians once campaigned from the back of trains.","th":"travel","lv":"C2","nw":1},{"e":"a white-shoe firm","d":"an old, prestigious and traditionally conservative law, finance or accounting firm","x":"After law school she joined [[a white-shoe firm]] in Manhattan, where partners still wore suits every day.","es":"un bufete (o firma) de élite y tradicional","o":"American. Refers to the white buckskin shoes once popular among wealthy students at elite East Coast universities.","th":"colors","lv":"C2","nw":1},{"e":"add fuel to the fire","d":"to make a tense or difficult situation even worse","x":"Copying the director into that thread only [[added fuel to the fire]].","es":"echarle leña al fuego","th":"trouble","lv":"C2","src":["c2-w-email"],"nw":0},{"e":"an albatross around your neck","d":"a problem or burden, often from your past, that you cannot get rid of and that keeps causing trouble","x":"That failed merger became [[an albatross around his neck]], and investors mentioned it every time he proposed a new deal.","es":"un lastre; una carga de la que no te puedes librar","o":"From Coleridge's 1798 poem “The Rime of the Ancient Mariner,” in which a sailor must wear a dead albatross as punishment.","th":"animals","lv":"C2","nw":1,"uk":"UK also: an albatross round your neck"},{"e":"an also-ran","d":"a person or thing that takes part in a competition but fails to win or make an impression","x":"Ten years ago they led the smartphone market; now they're [[an also-ran]] behind three newer brands.","es":"un segundón; uno del montón","o":"From horse racing, where newspapers listed the losing horses under the heading “also ran.”","th":"sport","lv":"C2","nw":1},{"e":"an ivory tower","d":"a place or situation that keeps people separate from the problems of ordinary life","x":"Head office makes its decisions from [[an ivory tower]] without ever visiting the stores.","es":"una torre de marfil","th":"people","lv":"C2","src":["c2-w-space"],"nw":0},{"e":"be at loggerheads (with someone)","d":"to strongly disagree with someone and be unable to reach an agreement","x":"The two co-founders have been [[at loggerheads]] for months over whether to sell the company.","es":"estar enfrentados; estar en pie de guerra","o":"Common in news about governments, unions, companies and families. Usually followed by “over” and the issue.","th":"people","lv":"C2","nw":1},{"e":"be hoist by your own petard","d":"to be harmed by the very plan or trick you intended to use against someone else","x":"The manager who installed cameras to watch his staff was [[hoist by his own petard]] when they recorded him napping at his desk.","es":"salirle el tiro por la culata","o":"From Shakespeare's Hamlet. A petard was a small explosive device; “hoist” means lifted. Also: hoisted with your own petard.","th":"trouble","lv":"C2","nw":1},{"e":"be in the driver's seat","d":"to be the person in control of a situation","x":"In a negotiation, whoever has more options [[is in the driver's seat]].","es":"tener la sartén por el mango; llevar las riendas","th":"travel","lv":"C2","src":["c2-freewill6"],"nw":0},{"e":"be left holding the bag","d":"to be left with all the blame or responsibility after others have escaped it","x":"The partners sold their shares and moved abroad, and the junior staff were [[left holding the bag]] when the auditors arrived.","es":"pagar los platos rotos","o":"American. Often about unfair blame after a failed deal or scheme.","th":"trouble","lv":"C2","nw":1,"uk":"UK: be left holding the baby"},{"e":"beg the question","d":"to make people want to ask something; traditionally, to assume as true the very point being argued","x":"The project is six months late, which [[begs the question]]: why did nobody raise the alarm earlier?","es":"lleva a preguntarse; plantea la pregunta","o":"Register trap: careful writers keep it for circular arguments, but most speakers today use it to mean “raises the question.”","th":"talk","lv":"C2","nw":1},{"e":"bite the hand that feeds you","d":"to harm the person or organization that supports you","x":"Criticizing your main client in public is [[biting the hand that feeds you]].","es":"morder la mano que te da de comer","th":"body","lv":"C2","src":["c2-w-platform6"],"nw":0},{"e":"call a spade a spade","d":"to say exactly what you think, even if it's unpleasant","x":"I like working with her because she [[calls a spade a spade]].","es":"al pan, pan y al vino, vino; llamar las cosas por su nombre","th":"talk","lv":"C2","src":["c2-diplomacy6","c2-w-euphemism6"],"nw":0},{"e":"call someone's bluff","d":"to challenge someone to carry out a threat you suspect is empty","x":"He threatened to walk out, so they [[called his bluff]] and opened the door.","es":"pagar para ver","th":"sport","lv":"C2","src":["c2-negotiation"],"nw":0},{"e":"carry a torch for someone","d":"to keep loving someone romantically, especially when they don't love you back","x":"Twenty years later, he still [[carries a torch for]] his college girlfriend, though he'd never admit it.","es":"seguir enamorado de alguien; seguir pegado con alguien (Chile)","o":"Usually about love that is old, secret or not returned. Sad love songs of this kind are called “torch songs.”","th":"feelings","lv":"C2","nw":1},{"e":"carry the day","d":"to win a contest, debate or argument; to be the most successful in the end","x":"There were strong arguments on both sides, but in the end the cheaper option [[carried the day]].","es":"imponerse; llevarse la victoria","o":"Slightly formal; common in news about votes, debates and court cases. Similar: win the day.","th":"success","lv":"C2","nw":1},{"e":"cast a long shadow","d":"to have a strong influence that continues long after something has ended","x":"The founder's decisions still [[cast a long shadow]] over the company's strategy.","es":"seguir pesando; tener una influencia duradera","th":"time","lv":"C2","src":["c2-w-future"],"nw":0},{"e":"chase your own tail","d":"to be very busy without achieving anything useful","x":"We spent the whole quarter [[chasing our own tails]] because nobody had agreed on the priorities.","es":"dar vueltas en círculos; como perro persiguiéndose la cola","th":"animals","lv":"C2","src":["c2-everyday"],"nw":0},{"e":"cherry-pick","d":"to choose only the facts that support your argument","x":"If you [[cherry-pick]] the best months, any year looks good.","es":"escoger solo lo que conviene","th":"food","lv":"C2","src":["c2-w-trends"],"nw":0},{"e":"circle the wagons","d":"to unite and defend your group against criticism or attack from outside","x":"When the scandal broke, the board [[circled the wagons]] and refused to answer any questions.","es":"cerrar filas","o":"American. From pioneers traveling west, who arranged their wagons in a circle for protection at night.","th":"travel","lv":"C2","nw":1},{"e":"close to the bone","d":"so near to a painful or sensitive truth that it may upset people","x":"Joking about layoffs a week after the restructuring was a bit [[close to the bone]].","es":"tocar un punto sensible; tocar la herida","th":"body","lv":"C2","src":["c2-w-irony6"],"nw":0},{"e":"cold comfort","d":"something meant to make you feel better that actually helps very little","x":"Hearing that other airlines had worse delays was [[cold comfort]] to passengers stuck at the gate overnight.","es":"un consuelo de tontos; un pobre consuelo","o":"Usually in the pattern “be cold comfort to/for someone.”","th":"feelings","lv":"C2","nw":1},{"e":"come full circle","d":"to end up back in the situation or place where something began","x":"She started her career as a student at that school and [[came full circle]] as its principal.","es":"cerrar el círculo; volver al punto de partida","th":"travel","lv":"C2","src":["c2-personal"],"nw":0},{"e":"comfortable in your own skin","d":"relaxed and confident about who you are","x":"It took me until my thirties to feel [[comfortable in my own skin]] at parties.","es":"sentirse a gusto consigo mismo; cómodo en su propia piel","th":"body","lv":"C2","src":["c2-solitude6"],"nw":0},{"e":"compare apples and oranges","d":"to compare two things that are too different to be compared fairly","x":"Comparing December with a normal month is [[comparing apples and oranges]].","es":"comparar peras con manzanas","th":"food","lv":"C2","src":["c2-w-trends"],"nw":0},{"e":"cross that bridge when you come to it","d":"to deal with a possible problem only if and when it actually happens","x":"The law might change next year, but we'll [[cross that bridge when we come to it]].","es":"cada cosa a su tiempo; no adelantarse a los problemas","th":"travel","lv":"C2","src":["c2-uncertainty6"],"nw":0},{"e":"cross the Rubicon","d":"to take a decisive step that makes it impossible to go back","x":"When we resigned from our jobs and signed the lease on the bakery, we knew we had [[crossed the Rubicon]].","es":"cruzar el Rubicón; quemar las naves","o":"In 49 BC, Julius Caesar led his army across the Rubicon River into Italy, a move that could not be undone.","th":"risk","lv":"C2","nw":1},{"e":"cut no ice (with someone)","d":"to have no effect on someone, or fail to impress or persuade them","x":"Fancy job titles [[cut no ice]] with Laura; she only cares whether you deliver results.","es":"no hacerle ni cosquillas (a alguien); no convencer","o":"Usually negative or with “little”: cut no ice / cut little ice with someone.","th":"weather","lv":"C2","nw":1},{"e":"cut out the middleman","d":"to deal directly with buyers or sellers, without an intermediary","x":"By selling directly online, the winery [[cut out the middleman]].","es":"saltarse al intermediario","th":"money","lv":"C2","src":["c2-w-platform6"],"nw":0},{"e":"cut the Gordian knot","d":"to solve a very complicated problem with one bold, simple action","x":"Instead of renegotiating every contract one by one, the new director [[cut the Gordian knot]] and switched suppliers entirely.","es":"cortar el nudo gordiano","o":"From the legend of Alexander the Great, who solved an impossible knot by simply cutting through it. Also: a Gordian knot (a hard problem).","th":"trouble","lv":"C2","nw":1},{"e":"cut the mustard","d":"to be good enough to meet the required standard","x":"He was great in the interview, but after three months it was clear he couldn't [[cut the mustard]].","es":"(no) dar la talla","o":"Usually negative: “doesn't/couldn't cut the mustard.” Its origin is uncertain.","th":"food","lv":"C2","nw":1,"reg":"informal"},{"e":"damn with faint praise","d":"to praise someone or something so weakly that it actually suggests criticism","x":"Calling her presentation “adequate” was [[damning it with faint praise]], and everyone in the room knew it.","es":"criticar con elogios tibios","o":"From a 1735 poem by Alexander Pope. Typical faint-praise words: “fine,” “adequate,” “interesting.”","th":"talk","lv":"C2","nw":1},{"e":"drink from a fire hose","d":"to try to absorb far more information than you can possibly handle","x":"Starting a job at a fast-growing startup is like [[drinking from a fire hose]].","es":"recibir información a chorros; quedar sobrepasado","th":"food","lv":"C2","src":["c2-w-now"],"nw":0},{"e":"easy on the eyes","d":"pleasant to look at","x":"The new website is [[easy on the eyes]], but it's impossible to find anything.","es":"agradable a la vista; lindo de ver","th":"body","lv":"C2","src":["c2-aesthetics6"],"nw":0},{"e":"eat crow","d":"to admit that you were wrong, which is embarrassing or humiliating","x":"After predicting the phone would flop, the tech reviewer had to [[eat crow]] when it sold out in a week.","es":"tragarse sus palabras","o":"Mainly American. “Eat humble pie” and “eat your words” have a similar meaning.","th":"food","lv":"C2","nw":1,"reg":"informal"},{"e":"fit to be tied","d":"extremely angry or upset","x":"When the airline lost her luggage for the second time in a month, Mom was [[fit to be tied]].","es":"echando chispas","o":"American; the image is of someone so angry that they might need to be held back.","th":"feelings","lv":"C2","nw":1,"reg":"informal"},{"e":"fly in the face of","d":"to directly contradict what people believe or expect","x":"These results [[fly in the face of]] everything we assumed about our customers.","es":"ir en contra de; contradecir por completo","th":"body","lv":"C2","src":["c2-w-behavioral6"],"nw":0},{"e":"get a word in edgewise","d":"to manage to say something while another person is talking too much","x":"Our sales director talks so much that nobody can [[get a word in edgewise]].","es":"(no poder) meter la cuchara; no dejar hablar a nadie","th":"talk","lv":"C2","src":["c2-w-silence6"],"nw":0},{"e":"get ahead of the story","d":"to act or speak before the media and the public decide what the story is","x":"By publishing the recall notice first, the company [[got ahead of the story]].","es":"adelantarse a la noticia","th":"talk","lv":"C2","src":["c2-w-viral6"],"nw":0},{"e":"get wind of","d":"to find out about something that was meant to be secret","x":"If our competitors [[get wind of]] the new product, they'll cut their prices.","es":"enterarse; llegarle el rumor","th":"weather","lv":"C2","src":["c2-w-report"],"nw":0},{"e":"get your head around","d":"to manage to understand something difficult or strange","x":"I still can't [[get my head around]] the idea that time passes slightly faster on a mountain than at sea level.","es":"lograr entender; que algo le entre en la cabeza","th":"body","lv":"C2","src":["c2-curious"],"nw":0},{"e":"give someone a wide berth","d":"to avoid someone or something, keeping a safe distance","x":"After his angry outburst at the holiday party, most of his colleagues [[gave him a wide berth]] for weeks.","es":"hacerle el quite (a alguien); mantenerse a distancia","o":"From sailing: a berth was the space a ship needed to move safely at anchor.","th":"travel","lv":"C2","nw":1},{"e":"go over like a lead balloon","d":"to be received very badly; to completely fail to impress or amuse people","x":"My joke about the budget [[went over like a lead balloon]]; nobody in the meeting even smiled.","es":"ser un fiasco total; caer pésimo","o":"“Lead” here is the heavy metal, pronounced /led/. Often about jokes, proposals and announcements.","th":"success","lv":"C2","nw":1,"uk":"UK: go down like a lead balloon"},{"e":"golden handcuffs","d":"financial benefits that make it very difficult to leave a job","x":"Her stock options were [[golden handcuffs]]: leaving before 2028 would cost her a fortune.","es":"esposas de oro; beneficios que te amarran a la empresa","th":"money","lv":"C2","src":["c2-careers","c2-w-loyalty6"],"nw":0},{"e":"golden parachute","d":"a very large payment promised to an executive if they lose their job","x":"He was fired after eighteen months, but his [[golden parachute]] was worth four million dollars.","es":"paracaídas dorado; una indemnización millonaria","th":"money","lv":"C2","src":["c2-w-execpay6"],"nw":0},{"e":"hang someone out to dry","d":"to leave someone to take all the blame, without supporting or defending them","x":"When the campaign failed, the agency [[hung its junior designer out to dry]].","es":"dejar a alguien botado; dejarlo solo con el problema","th":"people","lv":"C2","src":["c2-w-viral6"],"nw":0},{"e":"have a mind of its own","d":"to seem to act independently, as if nobody were controlling it","x":"Once a rumor starts, it [[has a mind of its own]].","es":"tener vida propia","th":"trouble","lv":"C2","src":["c2-freewill6"],"nw":0},{"e":"have a tin ear (for something)","d":"to be insensitive to something, such as music, language or how other people will react","x":"The CEO clearly [[has a tin ear]] for how employees feel: he announced pay cuts a week after accepting a huge bonus.","es":"no tener sensibilidad (ni oído) para algo; no tener tacto","o":"Originally about people who can't appreciate music; now often about leaders who misjudge the public mood. Adjective: tin-eared.","th":"body","lv":"C2","nw":1},{"e":"have it both ways","d":"to want two advantages that cannot exist together","x":"You can't [[have it both ways]]: either you want honesty or you want compliments.","es":"querer las dos cosas a la vez; no se puede tener todo","th":"risk","lv":"C2","src":["c2-ethics"],"nw":0},{"e":"have someone in the palm of your hand","d":"to have such influence over a person or an audience that they'll accept whatever you say","x":"By the end of her keynote, she [[had the whole room in the palm of her hand]].","es":"tener a alguien en la palma de la mano; tener al público en el bolsillo","th":"body","lv":"C2","src":["c2-w-intro"],"nw":0},{"e":"have someone over a barrel","d":"to be in such a strong position that the other side has no real choice","x":"With only one supplier in the region, they [[had us over a barrel]].","es":"tener a alguien contra las cuerdas","th":"trouble","lv":"C2","src":["c2-negotiation"],"nw":0},{"e":"have someone's ear","d":"to be listened to and trusted by someone important","x":"She doesn't have a big title, but she [[has the CEO's ear]].","es":"tener llegada con alguien","th":"body","lv":"C2","src":["c2-influence6"],"nw":0},{"e":"have the last word","d":"to make the final comment in an argument, often to feel that you have won","x":"She always has to [[have the last word]], even when she's clearly wrong.","es":"tener la última palabra","th":"talk","lv":"C2","src":["c2-w-silence6"],"nw":0},{"e":"have your cake and eat it (too)","d":"to want two good things that can't both be had at the same time","x":"Management wants longer opening hours and lower staff costs. They can't [[have their cake and eat it too]].","es":"querer la chancha y los veinte","th":"food","lv":"C2","src":["c2-w-routine"],"nw":0},{"e":"have your cake and eat it too","d":"to want two good things that can't both exist at the same time","x":"You want a cheap vacation with no other tourists? You can't [[have your cake and eat it too]].","es":"querer la chancha y los veinte; querer el oro y el moro","th":"food","lv":"C2","src":["c2-food"],"nw":0},{"e":"heads I win, tails you lose","d":"a situation in which one side benefits whatever happens","x":"A guaranteed bonus with no penalty for failure? That's [[heads I win, tails you lose]].","es":"cara gano yo, sello pierdes tú","th":"risk","lv":"C2","src":["c2-w-execpay6"],"nw":0},{"e":"hedge your bets","d":"to reduce your risk by choosing more than one option or a cautious middle path","x":"She [[hedged her bets]] by applying to universities in Chile and abroad.","es":"no poner todos los huevos en la misma canasta","th":"risk","lv":"C2","src":["c2-uncertainty6","c2-w-deglobal6"],"nw":0},{"e":"hindsight is 20/20","d":"it's easy to see the right decision once you know what happened","x":"[[Hindsight is 20/20]]; at the time, the decision looked perfectly reasonable.","es":"con el diario del lunes, cualquiera","th":"time","lv":"C2","src":["c2-w-past"],"nw":0},{"e":"hit home","d":"to be fully understood or felt, often emotionally","x":"The scale of the problem only [[hit home]] when she showed the empty classroom.","es":"calar hondo; tomar real conciencia","th":"feelings","lv":"C2","src":["c2-presentations"],"nw":0},{"e":"Hobson's choice","d":"a situation where you seem to have a choice but really have only one option","x":"Accept the new contract or lose your job? That's [[Hobson's choice]], not a negotiation.","es":"una falsa elección; o lo tomas o lo dejas","o":"Named after Thomas Hobson, an English stable owner of the early 1600s who offered customers the horse nearest the door or none.","th":"risk","lv":"C2","nw":1},{"e":"hold the purse strings","d":"to control how money is spent in a family, organization or government","x":"My father-in-law still [[holds the purse strings]] in the family business, so every big purchase needs his approval.","es":"manejar la billetera; llevar las finanzas","o":"Also: tighten the purse strings (spend less) or loosen them (spend more). Common in news about budgets.","th":"money","lv":"C2","nw":1},{"e":"hold your nose (and do something)","d":"to accept or do something you strongly dislike because there is no better option","x":"None of us liked the supplier's terms, but we [[held our noses]] and signed because the deadline was the next morning.","es":"hacer de tripas corazón","o":"People literally hold their nose to avoid a bad smell. Common in American English about unpopular deals, compromises and votes.","th":"body","lv":"C2","nw":1},{"e":"in a New York minute","d":"very quickly; immediately and without hesitating","x":"If someone offered me a remote job near the beach, I'd accept [[in a New York minute]].","es":"sin pensarlo dos veces; en un abrir y cerrar de ojos","o":"American, playing on New York's reputation as a fast-moving, impatient city.","th":"time","lv":"C2","nw":1,"reg":"informal"},{"e":"in high dudgeon","d":"in a state of deep anger or resentment, usually because you feel insulted","x":"The client left the meeting [[in high dudgeon]] after we suggested, very politely, that his idea might not work.","es":"ofendidísimo; hecho una furia","o":"Old-fashioned, so it is often used humorously. Typical verbs: leave, walk out, storm off.","th":"feelings","lv":"C2","nw":1,"reg":"formal"},{"e":"in one fell swoop","d":"all at once, in a single sudden action","x":"The new CEO closed three offices and replaced the entire leadership team [[in one fell swoop]].","es":"de un plumazo","o":"From Shakespeare's Macbeth; “fell” is an old word meaning fierce or cruel. Today it is neutral and simply means all at once.","th":"time","lv":"C2","nw":1},{"e":"in the doldrums","d":"in a period of low activity, no progress or low spirits","x":"The housing market has been [[in the doldrums]] for months, and agents are struggling to close any deals.","es":"de capa caída; estancado","o":"The doldrums are calm areas of ocean near the equator where sailing ships could be stuck for weeks without wind.","th":"weather","lv":"C2","nw":1},{"e":"in the fullness of time","d":"eventually, when the right moment comes, often after a long wait","x":"“We'll review salaries [[in the fullness of time]],” the director said, which everyone understood as “not this year.”","es":"a su debido tiempo","o":"Officials sometimes use it to delay without promising anything specific, so it can sound evasive.","th":"time","lv":"C2","nw":1,"reg":"formal"},{"e":"it goes without saying","d":"it is so obvious that it doesn't need to be said","x":"[[It goes without saying]] that you don't discuss your salary with clients.","es":"está de más decirlo; ni hablar","th":"talk","lv":"C2","src":["c2-w-rules"],"nw":0},{"e":"judge a book by its cover","d":"to form an opinion based only on appearance","x":"The café looks run-down, but don't [[judge a book by its cover]]; the food is excellent.","es":"juzgar por las apariencias; las apariencias engañan","th":"people","lv":"C2","src":["c2-literature6"],"nw":0},{"e":"keep a stiff upper lip","d":"to hide your feelings and stay calm and brave when something sad or difficult happens","x":"When the layoffs were announced, our manager [[kept a stiff upper lip]] and spent the day helping her team.","es":"mantener la compostura; aguantar sin quejarse","o":"Strongly associated with the traditional British ideal of hiding emotion and not complaining in hard times.","th":"body","lv":"C2","nw":1},{"e":"keep something under wraps","d":"to keep something secret, usually for a limited time","x":"The new product is being [[kept under wraps]] until the launch in March.","es":"mantener en secreto; guardar bajo siete llaves","th":"talk","lv":"C2","src":["c2-w-details"],"nw":0},{"e":"keep up appearances","d":"to pretend that everything is fine so that others don't see your problems","x":"They [[kept up appearances]] long after the money had run out.","es":"guardar las apariencias","th":"people","lv":"C2","src":["c2-identity6"],"nw":0},{"e":"keep your powder dry","d":"to stay ready to act, saving your resources until the right moment","x":"The union isn't striking yet; it's [[keeping its powder dry]] until the contract talks in March.","es":"esperar el momento oportuno; guardarse los cartuchos","o":"Originally about keeping gunpowder dry so it would work when needed. Common in politics, finance and negotiations.","th":"risk","lv":"C2","nw":1},{"e":"kick the tires","d":"to examine something carefully before you buy it or commit to it","x":"Before we invest, I'd like our own engineers to [[kick the tires]].","es":"revisar algo con lupa antes de comprar","th":"travel","lv":"C2","src":["c2-w-board6"],"nw":0},{"e":"kill the goose that lays the golden eggs","d":"to destroy the very source of your success through short-term greed","x":"Selling the founder's recipe to a mass producer would [[kill the goose that lays the golden eggs]].","es":"matar la gallina de los huevos de oro","th":"animals","lv":"C2","src":["c2-w-luxury6"],"nw":0},{"e":"know something inside out","d":"to know every detail of something extremely well","x":"After six years in customer service, he [[knows our return policy inside out]].","es":"conocer algo como la palma de la mano; saberse algo al revés y al derecho","th":"success","lv":"C2","src":["c2-w-skills"],"nw":0},{"e":"know which side your bread is buttered on","d":"to understand who gives you advantages, and act carefully so that you keep them","x":"Dan never argues with the regional director; he [[knows which side his bread is buttered on]].","es":"arrimarse al sol que más calienta","o":"Often suggests that someone is loyal or polite for practical, self-interested reasons.","th":"food","lv":"C2","nw":1},{"e":"lay it on thick","d":"to exaggerate emotion or praise so much that it seems insincere","x":"A little emotion is powerful, but if you [[lay it on thick]], people stop believing you.","es":"cargar las tintas; exagerar la nota","th":"talk","lv":"C2","src":["c2-presentations"],"nw":0},{"e":"make your mark","d":"to become noticed or remembered for something you achieve","x":"She [[made her mark]] as the first woman to run the hospital.","es":"dejar huella; dejar su marca","th":"success","lv":"C2","src":["c2-plans"],"nw":0},{"e":"meet your Waterloo","d":"to suffer a final, decisive defeat after a period of success","x":"The retail giant seemed unstoppable, but it [[met its Waterloo]] when online shopping took off.","es":"encontrar su Waterloo; sufrir su derrota definitiva","o":"Refers to Napoleon's final defeat at the Battle of Waterloo in 1815.","th":"success","lv":"C2","nw":1},{"e":"money for nothing","d":"money received without doing any work for it","x":"A guaranteed income isn't [[money for nothing]] if it helps people find better jobs.","es":"plata fácil; plata regalada","th":"money","lv":"C2","src":["c2-ubi6"],"nw":0},{"e":"nickel-and-dime someone","d":"to keep charging someone small extra amounts that add up and become annoying","x":"The hotel [[nickel-and-dimed]] us for everything: parking, towels, even bottled water.","es":"cobrar hasta por respirar","o":"American. A nickel is five cents and a dime ten. Also an adjective: nickel-and-dime fees.","th":"money","lv":"C2","nw":1,"reg":"informal"},{"e":"not have a leg to stand on","d":"to have no facts, evidence or rules to support your argument or claim","x":"Without a signed contract, I'm afraid you [[don't have a leg to stand on]] if the client refuses to pay.","es":"no tener en qué basarse; quedarse sin argumentos","o":"Common in legal and business disputes. Always negative: “They don't have a leg to stand on.”","th":"body","lv":"C2","nw":1},{"e":"not in my backyard","d":"supporting a project in general but opposing it near your own home","x":"Everyone wants more housing until a tower is planned next door. Then it's “[[not in my backyard]]”.","es":"sí, pero no al lado de mi casa","th":"people","lv":"C2","src":["c2-urban6"],"nw":0},{"e":"not mince words","d":"to say exactly what you think, even if it may upset people","x":"The auditor [[didn't mince words]]: she called our controls 'wholly inadequate'.","es":"no tener pelos en la lengua","th":"talk","lv":"C2","src":["c2-w-euphemism6"],"nw":0},{"e":"not to put too fine a point on it","d":"used before saying something very directly, even if it sounds harsh","x":"[[Not to put too fine a point on it]], if sales don't improve by March, we'll have to close the store.","es":"para decirlo sin rodeos; en buen chileno","o":"A polite warning that blunt words are coming. Similar to “to put it bluntly.”","th":"talk","lv":"C2","nw":1,"reg":"formal"},{"e":"on tenterhooks","d":"nervous and anxious while waiting to find out what will happen","x":"We were [[on tenterhooks]] all weekend, waiting to hear if the bank had approved our mortgage.","es":"con el alma en un hilo","o":"Tenterhooks were hooks that held wet cloth stretched tight on a frame while it dried. Usually with be, keep or leave someone.","th":"feelings","lv":"C2","nw":1},{"e":"out of pocket","d":"paid with your own money, not by your employer or insurance","x":"My insurance didn't cover the dental work, so I paid three thousand dollars [[out of pocket]].","es":"de su propio bolsillo","o":"In American business slang, “I'll be out of pocket Friday” also means unavailable. In British English, it means having lost money.","th":"money","lv":"C2","nw":1,"uk":"UK: be out of pocket = to have lost money"},{"e":"over the hill","d":"too old to do something well or to be attractive (often said jokingly)","x":"At thirty-five, many soccer players are told they're [[over the hill]].","es":"ya no estar para estos trotes","th":"time","lv":"C2","src":["c2-health"],"nw":0},{"e":"pass the baton","d":"to give your responsibilities to the next person, as in a relay race","x":"It's time for the founding partners to [[pass the baton]] to the next generation.","es":"pasar la posta","th":"sport","lv":"C2","src":["c2-w-future"],"nw":0},{"e":"pennies on the dollar","d":"a tiny part of the original value or of the amount owed","x":"When the startup collapsed, its equipment was sold for [[pennies on the dollar]] and investors lost almost everything.","es":"a precio de huevo (Chile); por una fracción de su valor","o":"American, common in finance and the news: debts settled, or assets sold, for pennies on the dollar.","th":"money","lv":"C2","nw":1},{"e":"penny-wise and pound-foolish","d":"careful about small expenses but careless about much bigger ones","x":"Refusing to pay for proper training is [[penny-wise and pound-foolish]].","es":"ahorrar en lo chico y derrochar en lo grande; lo barato sale caro","th":"money","lv":"C2","src":["c2-w-compare"],"nw":0},{"e":"pick up the slack","d":"to do the work that someone else should be doing or can no longer do","x":"When two people resigned, the rest of the team had to [[pick up the slack]].","es":"cubrir el trabajo de otros; ponerle el hombro","th":"people","lv":"C2","src":["c2-w-role"],"nw":0},{"e":"pick your battles","d":"to choose carefully which disagreements are worth having","x":"You can't object to every decision; you have to [[pick your battles]].","es":"saber qué peleas dar","th":"risk","lv":"C2","src":["c2-influence6"],"nw":0},{"e":"play it close to the vest","d":"to keep your plans, intentions or information secret","x":"The new owners are [[playing it close to the vest]], so nobody knows whether the store will stay open.","es":"no mostrar las cartas; guardarse la información","o":"From card games, where players hold their cards close to the body so nobody can see them. Also: close to the chest.","th":"sport","lv":"C2","nw":1,"uk":"UK: keep your cards close to your chest"},{"e":"pull strings","d":"to use your influence with important people to get an advantage","x":"Her father [[pulled a few strings]] to get her an internship at the bank.","es":"mover sus contactos; usar un pituto","th":"people","lv":"C2","src":["c2-w-merit6"],"nw":0},{"e":"pull the wool over someone's eyes","d":"to deceive someone by hiding the truth from them","x":"Don't try to [[pull the wool over the auditors' eyes]]; they'll find the problem anyway.","es":"meterle el dedo en la boca a alguien; engañar","th":"body","lv":"C2","src":["c2-w-nudge6"],"nw":0},{"e":"pull up the ladder","d":"to stop others from getting the opportunities that helped you succeed","x":"Senior staff who block training programs are [[pulling up the ladder]] behind them.","es":"patear la escalera; cerrarles el paso a los que vienen detrás","th":"people","lv":"C2","src":["c2-w-ai6"],"nw":0},{"e":"purple prose","d":"writing that is too elaborate, emotional or full of fancy words","x":"My editor slashed the [[purple prose]] from my travel piece: “Nobody needs six adjectives for a sunset.”","es":"prosa recargada; un texto rimbombante","o":"Used by editors and critics. Linked to the Roman poet Horace, who compared showy passages to purple patches on plain cloth.","th":"colors","lv":"C2","nw":1},{"e":"put down roots","d":"to settle in a place and make it your permanent home","x":"After years of moving around for work, they decided to [[put down roots]] in Puerto Varas.","es":"echar raíces","th":"weather","lv":"C2","src":["c2-travel","c2-w-trips"],"nw":0},{"e":"put lipstick on a pig","d":"to make only surface changes to something bad, trying to make it look better than it is","x":"Changing the logo won't fix a product nobody wants; it's just [[putting lipstick on a pig]].","es":"aunque la mona se vista de seda, mona se queda","o":"Often in the full form: “You can put lipstick on a pig, but it's still a pig.”","th":"animals","lv":"C2","nw":1,"reg":"informal"},{"e":"put on a brave face","d":"to look calm or cheerful when you are actually worried or upset","x":"He [[put on a brave face]] during the restructuring, but he was terrified of losing his job.","es":"poner al mal tiempo buena cara","th":"body","lv":"C2","src":["c2-w-authentic6"],"nw":0},{"e":"put someone's nose out of joint","d":"to offend or upset someone, especially by making them feel ignored or less important","x":"Inviting the new hire to the client dinner instead of Rachel really [[put her nose out of joint]].","es":"hacer que alguien se sienta pasado a llevar (Chile); herirle el orgullo","o":"Used when someone feels their status or position has been ignored. Also: have your nose out of joint.","th":"body","lv":"C2","nw":1,"reg":"informal"},{"e":"put somewhere on the map","d":"to make a place famous or widely known","x":"The film festival [[put this small coastal town on the map]].","es":"poner un lugar en el mapa","th":"travel","lv":"C2","src":["c2-softpower6"],"nw":0},{"e":"rearrange the deck chairs on the Titanic","d":"to make small, useless changes while ignoring a much bigger disaster","x":"Changing the office layout while the company loses millions every month is just [[rearranging the deck chairs on the Titanic]].","es":"poner parches mientras el barco se hunde","o":"Humorous and critical. Refers to the famous passenger ship that sank in 1912 after hitting an iceberg.","th":"trouble","lv":"C2","nw":1},{"e":"rob Peter to pay Paul","d":"to solve one problem in a way that creates another of the same kind","x":"Taking money from the maintenance budget to buy new buses is just [[robbing Peter to pay Paul]].","es":"desvestir un santo para vestir otro","th":"money","lv":"C2","src":["c2-environment","c2-w-stock"],"nw":0},{"e":"rubber-stamp","d":"to approve something automatically, without examining it properly","x":"Shareholders accused the board of [[rubber-stamping]] every plan the founder brought to it.","es":"aprobar sin leer; dar el visto bueno a ciegas","th":"risk","lv":"C2","src":["c2-w-board6"],"nw":0},{"e":"run interference (for someone)","d":"to deal with problems or people for someone so they can work without being disturbed","x":"My assistant [[runs interference]] for me with reporters so I can focus on the negotiations.","es":"hacer de escudo (para alguien)","o":"From American football, where players block opponents to protect the teammate carrying the ball.","th":"sport","lv":"C2","nw":1},{"e":"run yourself into the ground","d":"to work so hard for so long that you become completely exhausted","x":"He [[ran himself into the ground]] trying to hit his sales targets.","es":"matarse trabajando; sacarse la mugre","th":"travel","lv":"C2","src":["c2-w-achieve"],"nw":0},{"e":"run yourself ragged","d":"to exhaust yourself by trying to do too much","x":"Between the new job and the renovation, Paula has been [[running herself ragged]].","es":"andar a mil; no dar abasto","th":"travel","lv":"C2","src":["c2-everyday"],"nw":0},{"e":"salad days","d":"a time in the past when you were young, inexperienced and full of energy","x":"Back in our [[salad days]], we'd work until midnight and still go out dancing afterward.","es":"los años mozos","o":"From Shakespeare's Antony and Cleopatra: “My salad days, when I was green in judgment.” Sounds literary or humorous.","th":"food","lv":"C2","nw":1},{"e":"sandbag","d":"to deliberately set low expectations so that later results look impressive","x":"Some analysts suspect the company [[sandbagged]] its forecast to guarantee a beat.","es":"bajar las expectativas a propósito; hacerse el chico","th":"money","lv":"C2","src":["c2-w-investors6"],"nw":0},{"e":"see the writing on the wall","d":"to recognize clear signs that something is going to fail or end","x":"She [[saw the writing on the wall]] and left the company a year before it closed.","es":"verlo venir; ver las señales","th":"trouble","lv":"C2","src":["c2-w-die6"],"nw":0},{"e":"send shivers down your spine","d":"to cause a sudden, physical feeling of excitement, fear or awe","x":"The opening notes of that symphony still [[send shivers down my spine]].","es":"poner la piel de gallina; dar escalofríos","th":"body","lv":"C2","src":["c2-music"],"nw":0},{"e":"set in stone","d":"fixed and impossible to change","x":"The wedding program isn't [[set in stone]], so feel free to suggest changes.","es":"escrito en piedra; inamovible","th":"weather","lv":"C2","src":["c2-rituals6"],"nw":0},{"e":"shoot the messenger","d":"to blame the person who brings bad news instead of dealing with the problem","x":"Don't [[shoot the messenger]]; I'm only telling you what the client said.","es":"matar al mensajero","th":"talk","lv":"C2","src":["c2-w-opinions"],"nw":0},{"e":"silver bullet","d":"a simple solution that instantly solves a complicated problem","x":"There's no [[silver bullet]] for low productivity.","es":"una solución mágica; la varita mágica","th":"trouble","lv":"C2","src":["c2-w-problems"],"nw":0},{"e":"since time immemorial","d":"for so long that nobody can remember a time before it","x":"Our IT department has been “about to upgrade” the system [[since time immemorial]].","es":"desde tiempos inmemoriales","o":"Formal, but often used humorously in everyday speech to exaggerate how long something has been going on.","th":"time","lv":"C2","nw":1,"reg":"formal"},{"e":"small potatoes","d":"something unimportant, especially when compared with something much bigger","x":"A ten-thousand-dollar fine is [[small potatoes]] for a company that makes millions every week.","es":"poca cosa; son chauchas (Chile, informal)","o":"Mainly American. Can describe amounts of money, problems, people or companies.","th":"food","lv":"C2","nw":1,"reg":"informal"},{"e":"soften the blow","d":"to make bad news less painful for the person who receives it","x":"To [[soften the blow]], the company offered generous severance pay.","es":"suavizar el golpe; amortiguar el golpe","th":"feelings","lv":"C2","src":["c2-diplomacy6"],"nw":0},{"e":"speak volumes","d":"to show something very clearly without needing any words","x":"The fact that nobody volunteered [[speaks volumes]] about team morale.","es":"decirlo todo; hablar por sí solo","th":"talk","lv":"C2","src":["c2-w-silence6"],"nw":0},{"e":"spin your wheels","d":"to put in a lot of effort without making any real progress","x":"We spent three months [[spinning our wheels]] on a project nobody had approved.","es":"dar vueltas sin avanzar; patinar en el mismo lugar","th":"travel","lv":"C2","src":["c2-w-busy6"],"nw":0},{"e":"spread yourself too thin","d":"to try to do too many things at once, so that you do none of them well","x":"By opening three branches in one year, we [[spread ourselves too thin]].","es":"el que mucho abarca, poco aprieta","th":"trouble","lv":"C2","src":["c2-strategy6","c2-w-stock"],"nw":0},{"e":"stand on the shoulders of giants","d":"to make progress thanks to the work of people who came before you","x":"Every new vaccine [[stands on the shoulders of giants]] from earlier generations of scientists.","es":"subirse a hombros de gigantes","th":"body","lv":"C2","src":["c2-plans"],"nw":0},{"e":"steal the show","d":"to attract more attention and praise than anyone else at an event","x":"The junior engineer's live demo [[stole the show]] at the product launch.","es":"robarse la película","th":"success","lv":"C2","src":["c2-w-present"],"nw":0},{"e":"stick to your knitting","d":"to concentrate on what you know and do best instead of moving into new areas","x":"After the failed move into retail, the board told management to [[stick to its knitting]].","es":"zapatero a tus zapatos","th":"money","lv":"C2","src":["c2-w-compare"],"nw":0},{"e":"stick your neck out","d":"to take a personal risk by saying or doing something that others won't","x":"She [[stuck her neck out]] and told the board the project was failing.","es":"jugársela; arriesgar el pellejo","th":"body","lv":"C2","src":["c2-w-opinions"],"nw":0},{"e":"sweeten the deal","d":"to add something extra to make an offer more attractive","x":"To [[sweeten the deal]], they offered two years of free maintenance.","es":"endulzar la oferta; hacer más atractiva la oferta","th":"food","lv":"C2","src":["c2-negotiation"],"nw":0},{"e":"take the high road","d":"to act fairly and with dignity, even when others behave badly","x":"Her ex-partner insulted her online, but she [[took the high road]] and wished him well in public.","es":"no rebajarse; actuar con altura de miras","o":"Mainly American. The opposite, “take the low road,” means to act unfairly or dishonestly.","th":"travel","lv":"C2","nw":1},{"e":"take the path of least resistance","d":"to choose whatever option requires the least effort","x":"Most users [[take the path of least resistance]] and never change the default settings.","es":"irse por el camino fácil","th":"travel","lv":"C2","src":["c2-tech"],"nw":0},{"e":"teach an old dog new tricks","d":"(usually \"you can't…\") to get an older person to learn new skills or change long-held habits","x":"My boss says you can't [[teach an old dog new tricks]], but he learned the new CRM in a week.","es":"loro viejo no aprende a hablar","th":"animals","lv":"C2","src":["c2-w-career"],"nw":0},{"e":"the 800-pound gorilla","d":"a person or organization so powerful that it can do almost anything it wants","x":"In online retail, one company is [[the 800-pound gorilla]], so smaller sellers have little choice but to accept its rules.","es":"el que corta el queque (Chile); el gigante que manda","o":"American, from an old riddle: “Where does an 800-pound gorilla sit? Anywhere it wants.” Don't confuse with “the elephant in the room.”","th":"animals","lv":"C2","nw":1},{"e":"the attention span of a goldfish","d":"an extremely limited ability to concentrate (usually said humorously)","x":"After a week of back-to-back meetings, I have [[the attention span of a goldfish]].","es":"tener memoria de pez; no poder concentrarse ni un minuto","th":"animals","lv":"C2","src":["c2-tech"],"nw":0},{"e":"the be-all and end-all","d":"the single most important thing, more important than anything else","x":"Grades matter, but they're not [[the be-all and end-all]] of an education.","es":"lo único que importa; el centro de todo","th":"success","lv":"C2","src":["c2-everyday"],"nw":0},{"e":"the buck stops here","d":"I have the final responsibility and won't pass it to anyone else","x":"As general manager, I won't make excuses. [[The buck stops here]].","es":"la responsabilidad es mía; yo me hago cargo","th":"trouble","lv":"C2","src":["c2-w-past"],"nw":0},{"e":"the canary in the coal mine","d":"an early warning sign that something dangerous or bad is about to happen","x":"Rising credit card debt among young workers may be [[the canary in the coal mine]] for the wider economy.","es":"la primera señal de alarma","o":"From a real practice: miners took canaries underground, and if the bird got sick, dangerous gas was present.","th":"animals","lv":"C2","nw":1},{"e":"the fountain of youth","d":"an imaginary way of staying young forever","x":"Expensive face creams are sold as [[the fountain of youth]], but the evidence is thin.","es":"la fuente de la eterna juventud","th":"time","lv":"C2","src":["c2-health"],"nw":0},{"e":"the glue that holds something together","d":"the thing that keeps a group of people united","x":"Sunday lunch at my aunt's house was [[the glue that held our family together]].","es":"lo que mantiene unido al grupo; el alma de la familia","th":"people","lv":"C2","src":["c2-rituals6"],"nw":0},{"e":"the green-eyed monster","d":"jealousy, imagined as a powerful force that controls how someone behaves","x":"When his younger colleague got the promotion, [[the green-eyed monster]] took over and he stopped speaking to her.","es":"los celos; la envidia","o":"From Shakespeare's Othello, where jealousy is called “the green-eyed monster.” Slightly literary or humorous.","th":"colors","lv":"C2","nw":1},{"e":"the letter of the law","d":"the exact wording of a rule, as opposed to its purpose","x":"They followed [[the letter of the law]] but completely ignored its spirit.","es":"la letra de la ley; al pie de la letra","th":"talk","lv":"C2","src":["c2-workplace"],"nw":0},{"e":"the lowest common denominator","d":"a weak compromise designed to offend no one and inspire no one","x":"The final slogan was [[the lowest common denominator]]: approved by all and loved by none.","es":"el mínimo común denominador","th":"risk","lv":"C2","src":["c2-meetings"],"nw":0},{"e":"the moral of the story","d":"the lesson that a story is meant to teach","x":"[[The moral of the story]]? Always check who's still on the call.","es":"la moraleja","th":"talk","lv":"C2","src":["c2-presentations"],"nw":0},{"e":"the only game in town","d":"the only available option, so people have no choice but to use it","x":"For freight to the island, that ferry company is [[the only game in town]].","es":"la única alternativa; o eso o nada","th":"sport","lv":"C2","src":["c2-w-platform6"],"nw":0},{"e":"the pecking order","d":"the unofficial ranking of who is most and least important in a group","x":"In this company, the parking spaces tell you everything about [[the pecking order]].","es":"la jerarquía no oficial; quién manda en el gallinero","th":"animals","lv":"C2","src":["c2-w-space"],"nw":0},{"e":"the pendulum swings","d":"opinion or practice moves strongly in one direction and then back toward the other","x":"After decades of offshoring, [[the pendulum is swinging]] back toward regional suppliers.","es":"el péndulo oscila; la tendencia se revierte","th":"time","lv":"C2","src":["c2-w-deglobal6"],"nw":0},{"e":"the Peter Principle","d":"the idea that people keep getting promoted until they reach a job they can't do well","x":"Our best salesperson became a terrible manager—[[the Peter Principle]] in action.","es":"el principio de Peter","o":"Named after Laurence J. Peter, whose humorous 1969 book described it. Common in management talk.","th":"success","lv":"C2","nw":1},{"e":"the powers that be","d":"the people or groups in authority who make the important decisions","x":"We've asked for a better coffee machine, but [[the powers that be]] say there's no budget this year.","es":"los que mandan; los de arriba","o":"Often ironic, suggesting distant decision-makers you can't influence. Takes a plural verb: “The powers that be have decided...”","th":"people","lv":"C2","nw":1},{"e":"the real deal","d":"genuine and authentic, not a copy or imitation","x":"After the X-ray, the experts confirmed that the sketch was [[the real deal]].","es":"auténtico; de verdad","th":"money","lv":"C2","src":["c2-authenticity6"],"nw":0},{"e":"the squeaky wheel gets the grease","d":"the people who complain the loudest get the most attention or resources","x":"I hate to say it, but when budgets are decided, [[the squeaky wheel gets the grease]].","es":"el que no llora, no mama","th":"talk","lv":"C2","src":["c2-w-stock"],"nw":0},{"e":"the sword of Damocles","d":"a constant threat of disaster that could happen at any moment","x":"With the merger still uncertain, possible layoffs hang over the staff like [[the sword of Damocles]].","es":"la espada de Damocles","o":"From an ancient story about a courtier who sat at a feast beneath a sword hanging by a single hair. Usually with “hang over.”","th":"trouble","lv":"C2","nw":1},{"e":"the tail wagging the dog","d":"a situation in which something minor controls something far more important","x":"When editors choose stories by click counts, it's [[the tail wagging the dog]].","es":"la cola moviendo al perro; el mundo al revés","th":"animals","lv":"C2","src":["c2-media","c2-w-routine"],"nw":0},{"e":"there's no such thing as a free lunch","d":"everything has a cost, even if you can't see it at first","x":"The app is free, but [[there's no such thing as a free lunch]]: you pay with your data.","es":"nada es gratis en esta vida","th":"food","lv":"C2","src":["c2-environment"],"nw":0},{"e":"through rose-colored glasses","d":"in an unrealistically positive way","x":"My parents remember the eighties [[through rose-colored glasses]]; they forget how hard things were.","es":"verlo todo color de rosa","th":"colors","lv":"C2","src":["c2-personal","c2-memory6"],"nw":0},{"e":"through thick and thin","d":"in good times and bad times, without wavering","x":"They've supported each other [[through thick and thin]] for forty years.","es":"en las buenas y en las malas","th":"people","lv":"C2","src":["c2-relationships"],"nw":0},{"e":"throw in your lot with someone","d":"to decide to join someone and share whatever success or failure follows","x":"She left a safe government job to [[throw in her lot with]] two friends starting a solar energy company.","es":"unir su suerte a la de alguien; jugársela con alguien","o":"Slightly formal. American English also says “cast your lot with someone.”","th":"risk","lv":"C2","nw":1},{"e":"to coin a phrase","d":"said humorously before using a very familiar expression, or sometimes a new one","x":"Well, [[to coin a phrase]], every cloud has a silver lining—at least we won't have to work this weekend.","es":"valga la expresión (dicho con ironía)","o":"Register play: usually ironic, because the phrase that follows is a cliché, not anything new.","th":"talk","lv":"C2","nw":1},{"e":"too big for your britches","d":"acting as if you are more important or clever than you really are","x":"Since his promotion, Kevin's gotten a little [[too big for his britches]] and stopped saying hello to the team.","es":"subírsele los humos (a alguien)","o":"American; “britches” is an old word for pants. Often with “get”: “He's getting too big for his britches.”","th":"people","lv":"C2","nw":1,"reg":"informal","uk":"UK: too big for your boots"},{"e":"too many cooks","d":"used to say that when too many people are involved, the result suffers (from the proverb too many cooks spoil the broth)","x":"Six departments are reviewing the brochure. [[Too many cooks]], if you ask me.","es":"muchas manos en un plato hacen mucho garabato","th":"food","lv":"C2","src":["c2-w-role"],"nw":0},{"e":"tug at your heartstrings","d":"to make you feel strong sadness, love or sympathy","x":"That commercial with the old dog really [[tugs at your heartstrings]].","es":"tocar el corazón; conmover","th":"feelings","lv":"C2","src":["c2-music"],"nw":0},{"e":"turn on the charm","d":"to start behaving in a very pleasant way, often deliberately, to get what you want","x":"The moment the CEO walked in, the sales director [[turned on the charm]].","es":"desplegar todo su encanto; ponerse encantador","th":"people","lv":"C2","src":["c2-w-intro"],"nw":0},{"e":"turn your nose up at","d":"to refuse something because you think it isn't good enough for you","x":"Kids often [[turn their noses up at]] vegetables they've never even tasted.","es":"hacerle el asco a algo; mirar en menos","th":"body","lv":"C2","src":["c2-food"],"nw":0},{"e":"under a cloud","d":"suspected of having done something wrong, or in disgrace","x":"The CFO left the company [[under a cloud]] after questions were raised about his expense reports.","es":"bajo sospecha; con la reputación manchada","o":"Often with verbs like leave, resign or retire: “She resigned under a cloud.”","th":"weather","lv":"C2","nw":1},{"e":"walk a fine line","d":"to be in a situation where it's easy to move from acceptable to unacceptable","x":"Marketers [[walk a fine line]] between persuasion and deception.","es":"moverse en una línea muy delgada; caminar en la cuerda floja","th":"risk","lv":"C2","src":["c2-workplace","c2-w-nudge6"],"nw":0},{"e":"water under the bridge","d":"something in the past that no longer matters or causes problems","x":"We argued a lot at university, but that's all [[water under the bridge]] now.","es":"agua pasada no mueve molino","th":"time","lv":"C2","src":["c2-personal"],"nw":0},{"e":"weasel words","d":"words chosen deliberately to be vague or misleading","x":"Phrases like 'up to' and 'may help' are classic [[weasel words]] in advertising.","es":"palabras ambiguas; lenguaje para no comprometerse","th":"animals","lv":"C2","src":["c2-w-euphemism6"],"nw":0},{"e":"window dressing","d":"an action intended to make something look better than it really is","x":"Critics dismissed the new ethics committee as [[window dressing]].","es":"pura fachada; puro maquillaje","th":"money","lv":"C2","src":["c2-csr6"],"nw":0}];
